local PS = game:GetService("Players")
local RS = game:GetService("RunService")
local HS = game:GetService("HttpService")

-- ================================================================================================
-- TELA DE CARREGAMENTO (RoCLoad)
-- Mostra uma tela com barra de progresso enquanto o script monta tudo, e cede um frame ao jogo
-- entre as etapas (RoCLoad.Step) para o cliente não congelar/crashar durante a inicialização.
--   RoCLoad.Enabled    = false  -> desliga a tela e os yields (volta ao comportamento antigo)
--   RoCLoad.PreloadMax = N      -> segundos máximos esperando o preload dos arquivos de RClothesContent
--                                  (o que sobrar é resolvido sob demanda pelo getId)
--   RoCLoad.StallHide  = N      -> segundos sem nenhum progresso até a tela se fechar sozinha
--   RoCLoad.FullScreenUI = false -> volta a respeitar a área segura/notch/barra do Roblox no menu
-- ================================================================================================
local RoCLoad = {Enabled = true, PreloadMax = 45, StallHide = 90, FullScreenUI = true}
do
	local RunSvc = game:GetService("RunService")
	local TweenSvc = game:GetService("TweenService")
	local PlayersSvc = game:GetService("Players")

	local gui, root, fill, pctLabel, statusLabel, detailLabel, conn
	local cardScale, spinGrad, shine, particles = nil, nil, nil, {}
	local openClock = 0
	local target, shown = 0, 0
	local statusText, detailText = "Iniciando", ""
	local failed, closing = false, false
	local session = 0
	local startClock = os.clock()
	local lastTick = startClock

	local function attach(g)
		local getters = {
			function()
				local f = gethui or get_hidden_gui
				if type(f) == "function" then return f() end
			end,
			function() return game:GetService("CoreGui") end,
			function()
				local lp = PlayersSvc.LocalPlayer
				return lp and lp:FindFirstChildOfClass("PlayerGui")
			end,
		}
		for _, get in ipairs(getters) do
			local ok, parent = pcall(get)
			if ok and parent then
				local ok2 = pcall(function() g.Parent = parent end)
				if ok2 and g.Parent == parent then
					return parent
				end
			end
		end
		return nil
	end

	local function makeLabel(parent, name, y, h, size, color, font, align)
		local l = Instance.new("TextLabel")
		l.Name = name
		l.BackgroundTransparency = 1
		l.Position = UDim2.new(0, 20, 0, y)
		l.Size = UDim2.new(1, -40, 0, h)
		l.Font = font
		l.TextSize = size
		l.TextColor3 = color
		l.TextXAlignment = align or Enum.TextXAlignment.Left
		l.TextTruncate = Enum.TextTruncate.AtEnd
		l.Text = ""
		l.Parent = parent
		return l
	end

	function RoCLoad.Close()
		if conn then
			conn:Disconnect()
			conn = nil
		end
		local g = gui
		gui, root, fill, pctLabel, statusLabel, detailLabel = nil, nil, nil, nil, nil, nil
		cardScale, spinGrad, shine, particles = nil, nil, nil, {}
		closing = false
		if g then pcall(g.Destroy, g) end
	end

	-- tira o limite de tela do Roblox (área segura, notch, barra superior) para o ScreenGui usar o display inteiro
	function RoCLoad.FullScreen(g)
		if not g or not RoCLoad.FullScreenUI then return end
		pcall(function() g.IgnoreGuiInset = true end)
		pcall(function() g.ScreenInsets = Enum.ScreenInsets.None end)
	end

	local function build()
		local g = Instance.new("ScreenGui")
		g.Name = "RoClothesLoading"
		g.DisplayOrder = 2147483647
		g.IgnoreGuiInset = true
		g.ResetOnSpawn = false
		g.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
		pcall(function() g.ScreenInsets = Enum.ScreenInsets.None end)
		gui = g

		local parent = attach(g)
		if not parent then
			gui = nil
			pcall(g.Destroy, g)
			return
		end
		-- remove telas de uma execução anterior
		for _, child in ipairs(parent:GetChildren()) do
			if child ~= g and child.Name == "RoClothesLoading" then
				pcall(child.Destroy, child)
			end
		end

		local r = Instance.new("CanvasGroup")
		r.Name = "Root"
		r.Size = UDim2.fromScale(1, 1)
		r.BackgroundColor3 = Color3.fromRGB(8, 10, 18)
		r.BorderSizePixel = 0
		r.Active = true -- bloqueia cliques no jogo enquanto carrega
		r.Parent = g
		root = r

		-- partículas flutuando ao fundo
		particles = {}
		for i = 1, 14 do
			local d = Instance.new("Frame")
			local size = 3 + (i * 7) % 6
			d.Name = "Particle"
			d.Size = UDim2.fromOffset(size, size)
			d.BackgroundColor3 = (i % 2 == 0) and Color3.fromRGB(0, 217, 255) or Color3.fromRGB(120, 90, 255)
			d.BackgroundTransparency = 0.5
			d.BorderSizePixel = 0
			d.Parent = r
			local dc = Instance.new("UICorner")
			dc.CornerRadius = UDim.new(1, 0)
			dc.Parent = d
			particles[i] = {Frame = d, X = ((i * 37) % 100) / 100, Speed = 0.04 + ((i * 13) % 7) * 0.01, Phase = (i * 0.173) % 1}
		end

		local card = Instance.new("Frame")
		card.Name = "Card"
		card.AnchorPoint = Vector2.new(0.5, 0.5)
		card.Position = UDim2.fromScale(0.5, 0.5)
		card.Size = UDim2.new(0.9, 0, 0, 168)
		card.BackgroundColor3 = Color3.fromRGB(18, 22, 38)
		card.BorderSizePixel = 0
		card.Parent = r
		local cap = Instance.new("UISizeConstraint")
		cap.MaxSize = Vector2.new(420, 168)
		cap.Parent = card
		cardScale = Instance.new("UIScale")
		cardScale.Scale = 0.85
		cardScale.Parent = card
		local cardCorner = Instance.new("UICorner")
		cardCorner.CornerRadius = UDim.new(0, 14)
		cardCorner.Parent = card
		local cardStroke = Instance.new("UIStroke")
		cardStroke.Color = Color3.fromRGB(60, 80, 140)
		cardStroke.Thickness = 1
		cardStroke.Parent = card

		local title = makeLabel(card, "Title", 16, 30, 26, Color3.fromRGB(232, 242, 255), Enum.Font.GothamBold)
		title.Text = "RoClothes"
		title.Position = UDim2.new(0, 62, 0, 16)
		title.Size = UDim2.new(1, -82, 0, 30)

		-- spinner: anel com gradiente girando
		local spin = Instance.new("Frame")
		spin.Name = "Spinner"
		spin.Position = UDim2.new(0, 20, 0, 16)
		spin.Size = UDim2.fromOffset(34, 34)
		spin.BackgroundTransparency = 1
		spin.Parent = card
		local spinCorner = Instance.new("UICorner")
		spinCorner.CornerRadius = UDim.new(1, 0)
		spinCorner.Parent = spin
		local spinStroke = Instance.new("UIStroke")
		spinStroke.Thickness = 4
		spinStroke.Color = Color3.new(1, 1, 1)
		spinStroke.Parent = spin
		spinGrad = Instance.new("UIGradient")
		spinGrad.Color = ColorSequence.new(Color3.fromRGB(0, 217, 255), Color3.fromRGB(120, 90, 255))
		spinGrad.Transparency = NumberSequence.new({
			NumberSequenceKeypoint.new(0, 0),
			NumberSequenceKeypoint.new(0.55, 0.15),
			NumberSequenceKeypoint.new(0.75, 1),
			NumberSequenceKeypoint.new(1, 1),
		})
		spinGrad.Parent = spinStroke
		local sub = makeLabel(card, "Subtitle", 46, 18, 13, Color3.fromRGB(120, 135, 170), Enum.Font.Gotham)
		sub.Text = "Carregando, aguarde. Não feche o jogo."
		sub.Position = UDim2.new(0, 62, 0, 46)
		sub.Size = UDim2.new(1, -82, 0, 18)
		statusLabel = makeLabel(card, "Status", 84, 20, 14, Color3.fromRGB(170, 190, 230), Enum.Font.Gotham)

		local track = Instance.new("Frame")
		track.Name = "Track"
		track.Position = UDim2.new(0, 20, 0, 112)
		track.Size = UDim2.new(1, -40, 0, 10)
		track.BackgroundColor3 = Color3.fromRGB(30, 36, 60)
		track.BorderSizePixel = 0
		track.Parent = card
		local trackCorner = Instance.new("UICorner")
		trackCorner.CornerRadius = UDim.new(0, 5)
		trackCorner.Parent = track

		fill = Instance.new("Frame")
		fill.Name = "Fill"
		fill.Size = UDim2.new(0, 0, 1, 0)
		fill.BackgroundColor3 = Color3.fromRGB(0, 217, 255)
		fill.BorderSizePixel = 0
		fill.ClipsDescendants = true
		fill.Parent = track
		shine = Instance.new("Frame")
		shine.Name = "Shine"
		shine.Size = UDim2.new(0.35, 0, 1, 0)
		shine.Position = UDim2.new(-0.4, 0, 0, 0)
		shine.BackgroundColor3 = Color3.new(1, 1, 1)
		shine.BorderSizePixel = 0
		shine.Parent = fill
		local shineGrad = Instance.new("UIGradient")
		shineGrad.Transparency = NumberSequence.new({
			NumberSequenceKeypoint.new(0, 1),
			NumberSequenceKeypoint.new(0.5, 0.45),
			NumberSequenceKeypoint.new(1, 1),
		})
		shineGrad.Parent = shine
		local fillCorner = Instance.new("UICorner")
		fillCorner.CornerRadius = UDim.new(0, 5)
		fillCorner.Parent = fill

		pctLabel = makeLabel(card, "Percent", 130, 20, 14, Color3.fromRGB(232, 242, 255), Enum.Font.GothamBold)
		detailLabel = makeLabel(card, "Detail", 130, 20, 13, Color3.fromRGB(120, 135, 170), Enum.Font.Gotham, Enum.TextXAlignment.Right)

		openClock = os.clock()
		conn = RunSvc.Heartbeat:Connect(function(dt)
			if not gui then return end
			local now = os.clock()
			shown += (target - shown) * math.min(1, dt * 8)
			if math.abs(target - shown) < 0.2 then shown = target end
			fill.Size = UDim2.new(math.clamp(shown / 100, 0, 1), 0, 1, 0)
			pctLabel.Text = string.format("%d%%", math.floor(shown + 0.5))

			-- animações: entrada do card, spinner, brilho da barra e partículas
			local a = math.clamp((now - openClock) / 0.5, 0, 1)
			local back = 1 + 2.70158 * (a - 1) ^ 3 + 1.70158 * (a - 1) ^ 2
			if cardScale then cardScale.Scale = 0.85 + 0.15 * back end
			if spinGrad then spinGrad.Rotation = (now * 400) % 360 end
			if shine then
				shine.Visible = not failed
				shine.Position = UDim2.new(((now * 0.7) % 1.5) - 0.4, 0, 0, 0)
			end
			for _, pt in ipairs(particles) do
				local prog = (now * pt.Speed + pt.Phase) % 1
				pt.Frame.Position = UDim2.fromScale(pt.X + math.sin(now + pt.Phase * 6.28) * 0.015, 1 - prog)
				pt.Frame.BackgroundTransparency = 0.5 + 0.5 * math.abs(prog * 2 - 1) ^ 2
			end

			local stalled = now - lastTick
			local txt = statusText
			if not failed then
				if stalled > 12 then
					txt = txt .. " (demorando mais que o normal...)"
				else
					txt = txt .. string.rep(".", math.floor(now * 2) % 4)
				end
			end
			statusLabel.Text = txt
			local elapsed = string.format("%ds", math.floor(now - startClock))
			detailLabel.Text = (detailText ~= "") and (detailText .. "  |  " .. elapsed) or elapsed

			if not failed and stalled > RoCLoad.StallHide then
				warn(string.format("[RoC] tela de carregamento fechada: sem progresso há %ds", math.floor(stalled)))
				RoCLoad.Close()
			end
		end)
	end

	function RoCLoad.Start()
		if gui or not RoCLoad.Enabled or not RunSvc:IsClient() then return end
		session += 1
		target, shown, failed, closing = 0, 0, false, false
		statusText, detailText = "Iniciando", ""
		startClock = os.clock()
		lastTick = startClock
		local ok, err = pcall(build)
		if not ok then
			warn("[RoC] tela de carregamento:", err)
			RoCLoad.Close()
		end
	end

	-- atualiza barra/texto sem ceder o frame
	function RoCLoad.Set(pct, text, detail)
		if failed then return end
		lastTick = os.clock()
		if type(pct) == "number" and pct > target then
			target = math.min(pct, 100)
		end
		if text then statusText = text end
		if detail ~= nil then detailText = detail end
	end

	-- atualiza e cede um frame: deixa a tela redesenhar e evita o "congelamento" do cliente
	function RoCLoad.Step(pct, text, detail)
		RoCLoad.Set(pct, text, detail)
		if RoCLoad.Enabled then
			RunSvc.Heartbeat:Wait()
		end
	end

	function RoCLoad.Done()
		if not gui or failed or closing then return end
		closing = true
		target = 100
		statusText = "Pronto!"
		lastTick = os.clock()
		local mySession = session
		task.spawn(function()
			local t0 = os.clock()
			while gui and session == mySession and shown < 99.5 and os.clock() - t0 < 1.5 do
				RunSvc.Heartbeat:Wait()
			end
			if session ~= mySession then return end
			local r = root
			if r then
				local ok = pcall(function()
					TweenSvc:Create(r, TweenInfo.new(0.35), {GroupTransparency = 1}):Play()
				end)
				if ok then task.wait(0.4) end
			end
			if session == mySession then RoCLoad.Close() end
		end)
	end

	function RoCLoad.Fail(msg)
		if not gui or failed then return end
		failed = true
		statusText = tostring(msg)
		pcall(function()
			fill.BackgroundColor3 = Color3.fromRGB(255, 80, 90)
			statusLabel.TextColor3 = Color3.fromRGB(255, 120, 130)
		end)
		local mySession = session
		task.delay(8, function()
			if session == mySession then RoCLoad.Close() end
		end)
	end

	RoCLoad.Start()
end

