	-- // [DripSync port] Entradas VNS (malha estatica, sem SmartBone) // --
	-- Origem: estrutura de DripSync.lua.txt (Function.PartListDefault); numeros dos model.rbxm reais.
	-- Os .mesh precisam existir em RClothesContent/_vns/model/... no workspace do executor.
	-- ===================================================================================== --
	RoCLoad.Step(12, "Carregando funções")
	Function.VNS_MODEL_DIR = "RClothesContent/_vns/model/"

	-- [v34] Constantes copiadas de DripSync.lua (~26104-26111). Ajuste = derivado, NAO testado no jogo.
	do
		local function RotOnly(cf) return cf - cf.Position end
		local DsNipRel = {
			Left  = CFrame.new(-0.572320938, -0.203234434, 0.00150489807, 0.000296547514, 0.999854326, -0.0170696471, -0.982211947, 0.0029140336, -0.18775323, -0.187775597, 0.0168216899, 0.982067883),
			Right = CFrame.new(-0.572320938, -0.203234434, 0.00150489807, -0.000296547514, 0.999854326, -0.0170696471, -0.982211947, 0.0029140336, 0.18775323, 0.187775597, 0.0168216899, 0.982067883),
		}
		local DsBreastRot = {
			Left  = CFrame.new(0, 0, 0, 0.320868134, 0.223423854, -0.920394123, -0.184720367, 0.967879057, 0.170553446, 0.928935945, 0.115290381, 0.351832479),
			Right = CFrame.new(0, 0, 0, -0.320868134, -0.223423854, -0.920394123, -0.184720367, 0.967879057, -0.170553446, 0.928935945, 0.115290381, -0.351832479),
		}
		local V33NipRot = CFrame.new(0, 0, 0, -1, 0, 0, 0, 1, 0, 0, 0, -1) -- rotacao dos R180 dos "Left/Right Nipple SB1"
		Function.VnsDsNipRel, Function.VnsDsBreastRot = DsNipRel, DsBreastRot
		Function.VnsNippleAnchorEnabled = true -- false = piercing preso direto na malha do rig (fica fixo), so para isolar travadas
		-- Ajuste fino das roupas de malha no peito VNS (Pos em studs, Rot em graus; em volta do mamilo). Zero = so o calculo do DripSync.
		Function.VnsBreastAnchorFix = {
			Left = {Pos = Vector3.new(0, 0, 0), Rot = Vector3.new(0, 0, 0)},
			Right = {Pos = Vector3.new(0, 0, 0), Rot = Vector3.new(0, 0, 0)},
		}
		Function.VnsNippleClothAdjust = {}
		for Side in pairs(DsNipRel) do
			Function.VnsNippleClothAdjust[Side] = V33NipRot:Inverse() * RotOnly(DsBreastRot[Side]) * RotOnly(DsNipRel[Side])
		end
	end

	function Function.PartListDefault()
		local _data = Function.PartListBase()

		local _vnsBase = {
			Transparency = 0, Reflectance = 0,
			Material = Enum.Material.SmoothPlastic,
			Color = {Tone = "Base", Color = "Parent"},
			AdjustScale = {"Size", "CFrame1"},
		}
		local function _vnsEntry(name, meshFile, size, cf, cf1, fn, scale)
			local e = {}
			for k, v in pairs(_vnsBase) do e[k] = v end
			e.Instance = "Mesh"
			e.Name = name
			e.MeshId = "rbxasset://RClothesContent/_vns/model/" .. meshFile
			e.Size = size
			e.CFrame = cf
			e.CFrame1 = cf1
			e.Parent = {[1] = "Torso"}
			e.Scale = scale or "BreastsScale"
			if fn then e.Function = fn end
			return e
		end

		-- [DripSync port v2] Valores lidos dos model.rbxm reais (RClothesContent/_vns/model/*/1/model.rbxm):
		-- Size = tamanho do MeshPart; CFrame = C0 do Motor6D/Weld convertido para o referencial do Torso/limb real
		-- (todas as pecas ficam giradas 180 graus em Y em relacao ao Torso, como no rig do DripSync).
		local function R180(x, y, z)
			return CFrame.new(x, y, z, -1, 0, 0, 0, 1, 0, 0, 0, -1)
		end

		-- Breasts 6
		-- [v21] Igual ao RigVnsModel do DripSync: pele = cor do torso, aureola = SurfaceAppearance (rbxassetid://9065282081)
		-- tingida de pele escurecida; mamilos escurecidos e SEM BreastsScale (DripSync so escala "Breast" sem "Nipple").
		_data["Left Breast SB1"] = _vnsEntry("Left Breast", "breast/1/leftb.mesh", Vector3.new(1.147, 1.352, 1.291), R180(-0.341008, 0.308, -0.559991), CFrame.new(), {"VnsSkin", "VnsAreolaSA"})
		_data["Right Breast SB1"] = _vnsEntry("Right Breast", "breast/1/rightb.mesh", Vector3.new(1.147, 1.352, 1.291), R180(0.359007, 0.308, -0.559991), CFrame.new(), {"VnsSkin", "VnsAreolaSA"})
		_data["Left Nipple SB1"] = _vnsEntry("Left Nipple", "breast/1/leftn.mesh", Vector3.new(0.124515, 0.129078, 0.08621), R180(-0.667001, 0.0559999, -1.187995), CFrame.new(), "VnsSkin")
		_data["Right Nipple SB1"] = _vnsEntry("Right Nipple", "breast/1/rightn.mesh", Vector3.new(0.124407, 0.129081, 0.08615), R180(0.685459, 0.05568, -1.188105), CFrame.new(), "VnsSkin")
		for _, k in ipairs({"Left Nipple SB1", "Right Nipple SB1"}) do
			_data[k].Scale = nil
			_data[k].AdjustScale = {}
		end

		-- Butt 6
		_data["Left Butt SB1"] = _vnsEntry("Left Butt", "butt/1/left.mesh", Vector3.new(1.34628, 1.30545, 1.33038), R180(-0.534551, -0.972884, 0.356431), CFrame.new(), {"VnsSkin", "VnsPantsTexture", "NewWomanTorsoPantsClothing"}, "ButtsScale")
		_data["Right Butt SB1"] = _vnsEntry("Right Butt", "butt/1/right.mesh", Vector3.new(1.363, 1.339, 1.352), R180(0.535, -0.973, 0.356009), CFrame.new(), {"VnsSkin", "VnsPantsTexture", "NewWomanTorsoPantsClothing"}, "ButtsScale")

		-- Arm 5
		local function _arm(side)
			return {Instance = "Mesh", Transparency = 0, Reflectance = 0,
				Material = Enum.Material.SmoothPlastic, Color = {Tone = "Base", Color = "Parent"},
				CFrame1 = CFrame.new(0, 0, 0), ParentTransparency = 1, Function = {"VnsSkin", "VnsShirtTexture"},
				Name = side .. " Arm Mesh",
				MeshId = "rbxasset://RClothesContent/_vns/model/arm/1/" .. string.lower(side) .. ".mesh",
				Size = Vector3.new(1, 2, 1), CFrame = R180(0, 0, 0), Parent = {[1] = side .. " Arm"}}
		end
		_data["Left Arm5"] = _arm("Left")
		_data["Right Arm5"] = _arm("Right")

		-- Legs 8
		local function _leg(side, x)
			return {Instance = "Mesh", Transparency = 0, Material = Enum.Material.SmoothPlastic,
				Color = {Tone = "Base", Color = "Parent"}, CFrame1 = CFrame.new(),
				-- [v21] DripSync escala a perna VNS uniforme (Size * LegsScale nos 3 eixos), sem mexer no C0/C1.
				ParentTransparency = 1, Scale = "LegsScale", UniformScale = true, AdjustScale = {"Size"},
				Function = {"VnsSkin", "PantsTexture"},
				Name = side .. " Leg Mesh",
				MeshId = "rbxasset://RClothesContent/_vns/model/leg/1/" .. string.lower(side) .. ".mesh",
				Size = Vector3.new(1.18822, 2.11876, 1.17061), CFrame = R180(x, 0.059, 0.019), Parent = {[1] = side .. " Leg"}}
		end
		_data["Left Leg8"] = _leg("Left", -0.03)
		_data["Right Leg8"] = _leg("Right", 0.03)

		-- Torso 9
		_data["Torso9"] = {Instance = "Mesh", Name = "Torso Mesh",
			MeshId = "rbxasset://RClothesContent/_vns/model/torso/1/1.mesh",
			Size = Vector3.new(2.0421, 2.00957, 1.01604), CFrame = R180(0, -0.0083847, -0.00999832), CFrame1 = CFrame.new(0, 0, 0),
			Transparency = 0, Material = Enum.Material.SmoothPlastic,
			Color = {Tone = "Base", Color = "Parent"}, Parent = {[1] = "Torso"},
			ParentTransparency = 1, Function = {"VnsSkin", "VnsTorsoTexture"}}

		-- Breast Clothes (sutia do VNS). Numeros do fallback Function.Weld do DripSync (PartListDefault).
		local _bcCF = CFrame.new(0, 0.689, -0.419) * CFrame.Angles(0, math.rad(-90.75), math.rad(-10))
		local function _breastClothes(variant)
			return {Instance = "Mesh", Name = "Breast Clothes", Transparency = 0, DoubleSided = true,
				Material = Enum.Material.SmoothPlastic, Color = {Tone = "Base", Color = "Parent"},
				MeshId = "rbxasset://RClothesContent/_vns/model/breastclothes/" .. variant .. "/1.mesh",
				Size = Vector3.new(1.24, 1.38, 1.89), CFrame = _bcCF, CFrame1 = CFrame.new(0, 0.3, 0),
				Parent = {[1] = "Torso"}, Scale = "BreastsScale",
				AdjustScale = {"Size", "CFrame", ["CFrame1"] = 4.5},
				Function = "VnsBreastClothesTexture"}
		end
		_data["Breast Clothes SB1"] = _breastClothes(1)
		_data["Breast Clothes SB2"] = _breastClothes(2)

		return _data
	end

