	local preLoad = {}

	-- cache persistente: salvo em RClothesContent/RoC_cache.json pelo executor.
	-- no respawn o cache já está pronto em disco — nada precisa ser reprocessado.
	local CacheFile = "RClothesContent/RoC_cache.json"
	local function LoadDiskCache()
		if not (env.isfile and env.readfile) then return end
		local ok, raw = pcall(env.readfile, CacheFile)
		if not ok or not raw or raw == "" then return end
		local ok2, tbl = pcall(HS.JSONDecode, HS, raw)
		if ok2 and type(tbl) == "table" then
			for k, v in pairs(tbl) do
				preLoad[k] = v
			end
		end
	end
	local function SaveDiskCache()
		if not (env.writefile) then return end
		pcall(env.writefile, CacheFile, HS:JSONEncode(preLoad))
	end
	RoCLoad.Step(34, "Lendo cache em disco")
	LoadDiskCache()
	RoCLoad.Step(38, "Cache carregado")

local function getId(id)
    if env.isfolder and env.gca and env.isfolder("RClothesContent") then
        local file = string.gsub(id, "rbxasset://", "")
        if preLoad[file] then
            return preLoad[file]
        elseif env.isfile and env.isfile(file) then
            local ok, customAsset = pcall(env.gca, file)
            if ok and customAsset then
                preLoad[file] = customAsset
                return customAsset
            end
        end
    end
    return id
end

-- [DripSync port] Tipos VNS (malha estatica). Disponiveis so se os .mesh existirem no workspace do executor.
Function.VnsFiles = {
	Breasts = {[6] = {"breast/1/leftb.mesh", "breast/1/rightb.mesh", "breast/1/leftn.mesh", "breast/1/rightn.mesh"}},
	Torso = {[9] = {"torso/1/1.mesh"}},
	Arm = {[5] = {"arm/1/left.mesh", "arm/1/right.mesh"}},
	Legs = {[8] = {"leg/1/left.mesh", "leg/1/right.mesh"}},
	Butt = {[6] = {"butt/1/left.mesh", "butt/1/right.mesh"}},
	BreastClothes = {[1] = {"breastclothes/1/1.mesh"}, [2] = {"breastclothes/2/1.mesh"}},
}
-- Tipos que existem no DripSync mas cujos dados nao estao no arquivo (vem de payload remoto): ficam escondidos.
Function.TypesNoData = {Legs = {[7] = true}, Butt = {[4] = true, [5] = true}}
Function.VnsWarned = {}

function Function.VnsPresent(Category, N)
	local List = Function.VnsFiles[Category] and Function.VnsFiles[Category][N]
	if not List then return true end
	if not (env.isfile and env.isfolder and env.isfolder("RClothesContent")) then return false end
	for _, Rel in ipairs(List) do
		local ok, has = pcall(env.isfile, "RClothesContent/_vns/model/" .. Rel)
		if not (ok and has) then return false end
	end
	return true
end

-- Tipo efetivo para montar: se o tipo VNS salvo nao tem arquivos, usa o tipo 1 (nao altera o dado salvo).
function Function.VnsEffectiveType(Category, N)
	if (Function.TypesNoData[Category] and Function.TypesNoData[Category][N]) or not Function.VnsPresent(Category, N) then
		local Key = Category .. N
		if not Function.VnsWarned[Key] then
			Function.VnsWarned[Key] = true
			warn("[RoC] " .. Category .. " type " .. tostring(N) .. " indisponivel (arquivos _vns ausentes ou sem dados); usando type 1.")
		end
		return 1
	end
	return N
end

-- [RoC fix] SurfaceAppearance no client nao aceita asset local (rbxasset://...).
-- MeshPart.TextureID aceita. Retorna true se o SurfaceAppearance foi mantido.
Function.IsLocalAsset = function(content)
	return type(content) == "string" and string.sub(content, 1, 11) == "rbxasset://"
end

Function.ApplyColorMap = function(sa, part, content)
	if content == nil or content == "" then
		return true
	end
	if Function.IsLocalAsset(content) then
		if part and part:IsA("MeshPart") then
			part.TextureID = content
		end
		sa:Destroy()
		return false
	end
	Function.SALogged = Function.SALogged or {}
	if not Function.SALogged[content] then
		Function.SALogged[content] = true
		print("[RoC] SurfaceAppearance ColorMap:", part and part.Name or "?", tostring(content))
	end
	sa.ColorMap = content
	return true
end

