	function Function.PreloadContent()
	if not (env.isfolder and env.isfile and env.gca and env.listfiles) then
		warn("[RoC] preload: o executor não tem isfolder/isfile/listfiles/getcustomasset.")
		return
	end
	if not env.isfolder("RClothesContent") then
		warn("[RoC] preload: pasta \"RClothesContent\" não encontrada na raiz do workspace do executor.")
		return
	end

	-- varre a pasta inteira, com subpastas
	local Files = {}
	local function Scan(Dir)
		local Ok, List = pcall(env.listfiles, Dir)
		if not Ok or type(List) ~= "table" then return end
		for _, Path in ipairs(List) do
			Path = (string.gsub(Path, "\\", "/"))
			if env.isfolder(Path) then
				Scan(Path)
			else
				table.insert(Files, Path)
			end
		end
	end
	Scan("RClothesContent")
	RoCLoad.Step(84, "Verificando arquivos")

	-- filtra arquivos já no cache de disco (carregado em LoadDiskCache no início)
	local Pending = {}
	for _, File in ipairs(Files) do
		if not preLoad[File] then
			table.insert(Pending, File)
		end
	end

	local Started = os.clock()
	local Total = #Files
	local CachedCount = Total - #Pending
	local Ready = CachedCount
	local Failed = {}

	if #Pending == 0 then
		RoCLoad.Set(94, "Arquivos prontos (cache em disco)")
		print(string.format("[RoC] preload: %d/%d do cache em disco (%.1fs)", Ready, Total, os.clock() - Started))
		return
	end

	-- paralleliza em batches de 16: dispara N tasks ao mesmo tempo,
	-- aguarda todas terminarem antes do próximo batch.
	local BatchSize = 16
	local Active = 0
	local Done = Instance.new("BindableEvent")

	local function ProcessFile(File)
		if not GUIObject.Screen.Parent then
			Active -= 1
			if Active == 0 then Done:Fire() end
			return
		end
		if not preLoad[File] and env.isfile(File) then
			local ok, asset = pcall(env.gca, File)
			if ok and asset then
				preLoad[File] = asset
				Ready += 1
			else
				table.insert(Failed, File)
			end
		elseif preLoad[File] then
			Ready += 1
		else
			table.insert(Failed, File)
		end
		Active -= 1
		if Active == 0 then Done:Fire() end
	end

	local i = 1
	while i <= #Pending do
		if not GUIObject.Screen.Parent then break end
		if os.clock() - Started > RoCLoad.PreloadMax then
			warn(string.format("[RoC] preload: limite de %ds atingido (%d/%d); o resto carrega sob demanda", RoCLoad.PreloadMax, Ready, Total))
			break
		end
		Active = 0
		local batchEnd = math.min(i + BatchSize - 1, #Pending)
		for j = i, batchEnd do
			Active += 1
			task.spawn(ProcessFile, Pending[j])
		end
		-- aguarda o batch terminar
		if Active > 0 then
			local WaitStart = os.clock()
			while Active > 0 and os.clock() - WaitStart < 5 do
				RS.Heartbeat:Wait()
			end
		end
		RS.Heartbeat:Wait()
		RoCLoad.Set(82 + 12 * (Ready / math.max(Total, 1)), string.format("Carregando arquivos (%d/%d)", Ready, Total))
		i = batchEnd + 1
	end

	Done:Destroy()

	-- salva cache em disco pra respawns futuros serem instantâneos
	SaveDiskCache()

	print(string.format("[RoC] preload: %d/%d prontos em %.1fs | cache: %d | falhou: %d",
		Ready, Total, os.clock() - Started, CachedCount, #Failed))

	if #Failed > 0 then
		warn("[RoC] getcustomasset falhou (primeiros 20): " .. table.concat(Failed, ", ", 1, math.min(#Failed, 20)))
		if env.writefile then
			pcall(function()
				if env.makefolder and env.isfolder and not env.isfolder("RClothesLerp") then
					env.makefolder("RClothesLerp")
				end
				env.writefile("RClothesLerp/ContentReport.txt", "FALHARAM:\n" .. table.concat(Failed, "\n"))
			end)
		end
	end
end

