	-- [v21] Cor de pele das pecas VNS, mesma regra do RigVnsModel do DripSync:
	-- base = SkinTone (Color3) > BodyColors.TorsoColor3 > cor do Torso; mamilos = NippleColor (Tone "Use NippleColor")
	-- ou base escurecida 40% (Tone "Dark") / 17.75% (resto).
	function Function.VnsBodyColor(Character, Extra, Data)
		local DataDetail = PlayerData[Data]
		local Skin = (Extra and Extra.SkinTone) or (DataDetail and DataDetail.SkinTone)
		if typeof(Skin) == "Color3" then return Skin end
		local Holders = {Character}
		if DataDetail and DataDetail.Character and DataDetail.Character ~= Character then table.insert(Holders, DataDetail.Character) end
		for _, H in ipairs(Holders) do
			local BC = H and H:FindFirstChildOfClass("BodyColors")
			if BC then return BC.TorsoColor3 end
		end
		for _, H in ipairs(Holders) do
			local T = H and (H:FindFirstChild("Torso") or H:FindFirstChild("UpperTorso"))
			if T and T:IsA("BasePart") then return T.Color end
		end
		return nil
	end

	-- [v48] Base do VNS static (mamilo + aréola) = rosa fixo dos outros tipos, igual a usar NippleColor 255,167,169.
	RoCLoad.Step(42, "Carregando modelos VNS")
	Function.VnsBasePink = Color3.fromRGB(255, 167, 169)
	function Function.VnsDarkColor(Base, Extra, Data, StaticPink)
		local DataDetail = PlayerData[Data]
		local Tone = (Extra and Extra.Tone) or (DataDetail and DataDetail.Tone)
		local Nipple = (Extra and Extra.NippleColor) or (DataDetail and DataDetail.NippleColor)
		if Tone == "Use NippleColor" and typeof(Nipple) == "Color3" then return Nipple end
		if StaticPink and Tone ~= "Dark" then
			if not Function.VnsBasePinkLogged then
				Function.VnsBasePinkLogged = true
				print("[RoC] v48: Base do VNS static = rosa fixo", Function.VnsBasePink)
			end
			return Function.VnsBasePink
		end
		if not Base then return nil end
		local H, S, V = Base:ToHSV()
		local Pct = (Tone == "Dark") and 40 or 17.75
		return Color3.fromHSV(H, S, math.max(0, V * (1 - Pct / 100)))
	end

	function Function.VnsSkin(ObjectInstance, Character, Extra, Data)
		local Base = Function.VnsBodyColor(Character, Extra, Data)
		local C = Base
		if string.find(ObjectInstance.Name, "Nipple", 1, true) then
			C = Function.VnsDarkColor(Base, Extra, Data, true) or Base
		end
		if C then ObjectInstance.Color = C end
	end

	-- DripSync: o model.rbxm do breast/1 traz SurfaceAppearance "ColorSA" (ColorMap rbxassetid://9065282081) nos dois seios,
	-- tingida com NippleColor ou pele escurecida. Asset online, entao SurfaceAppearance funciona no client.
	Function.VnsAreolaColorMap = "rbxassetid://9065282081"
	function Function.VnsAreolaSA(ObjectInstance, Character, Extra, Data)
		local DataDetail = PlayerData[Data]
		if not DataDetail or ObjectInstance.Transparency == 1 then return end
		local SA = ObjectInstance:FindFirstChild("ColorSA")
		local isNew = false
		if not (SA and SA:IsA("SurfaceAppearance")) then
			SA = Instance.new("SurfaceAppearance")
			SA.Name = "ColorSA"
			isNew = true
		end
		-- [v46 fix] Parent ANTES do ColorMap: executor carrega a textura só depois que o SA
		-- está no DOM. Atribuir ColorMap a um SA orphan não carrega nada → textura branca.
		if isNew then SA.Parent = ObjectInstance end
		local Ok = pcall(function() SA.ColorMap = Function.VnsAreolaColorMap end)
		if not Ok then
			SA:Destroy()
			return Function.AreolaDecalCreateVNS(ObjectInstance, Character, Extra, Data)
		end
		-- [v46 fix] SA.Color: "Base" = sem tint (white = textura da areola com cor natural);
		-- "Dark" / "Use NippleColor" = VnsDarkColor tinge a textura pelo Tone do menu.
		local DataDetail2 = PlayerData[Data]
		local Tone2 = (Extra and Extra.Tone) or (DataDetail2 and DataDetail2.Tone)
		-- [v48 fix] Base nao fica mais branco (textura natural, clarinha): tinge com o rosa fixo VnsBasePink (255,167,169),
		-- o mesmo resultado de usar NippleColor com esse valor.
		local Tint = Function.VnsDarkColor(Function.VnsBodyColor(Character, Extra, Data), Extra, Data, true)
		if Tint then pcall(function() SA.Color = Tint end) end
		-- SA já está parented se isNew; se era existente, já estava parented antes
	end

	function Function.AreolaDecalCreateVNS(ObjectInstance, Character, Extra, Data)
		local DataDetail = PlayerData[Data]
		if not DataDetail then return end
		if ObjectInstance.Transparency ~= 1 then
			local Path = "rbxasset://RClothesContent/_vns/model/breast/1/areola.png"
			local Texture = getId(Path)
			if Texture == Path then
				Texture = getId("rbxasset://RClothesContent/6667257628.png")
			end

			local Decal = Instance.new("Decal", ObjectInstance)
			Decal.Texture = Texture
			Decal.Face = Enum.NormalId.Back
			Decal.Name = "Areola Decal"
			Decal.Color3 = Color3.fromRGB(255, 167, 169)
			if Extra and Extra.Tone == "Dark" then
				local H, S, V = ObjectInstance.Color:ToHSV()
				Decal.Color3 = Color3.fromHSV(H, S, V + (-DarkerColorPercentage * V / 100))
			elseif Extra and Extra.Tone == "Use NippleColor" and Extra.NippleColor ~= nil then
				Decal.Color3 = Extra.NippleColor
			end
			DataDetail.CurrentPartList.AreolaDecal[Decal] = ObjectInstance
		end
	end

