	-- [DripSync port v3] Textura das pecas VNS: mesma regra do _paintSBOverlay do DripSync.
	-- Pinta SurfaceAppearance (Overlay); asset local nao vai em SurfaceAppearance no client, entao cai no TextureID.
	function Function.VnsPaint(ObjectInstance, Template, Mode)
		if not ObjectInstance or not Template or Template == "" then return end
		local SP = ObjectInstance:FindFirstChildOfClass("SurfaceAppearance")
		if not SP then SP = Instance.new("SurfaceAppearance", ObjectInstance); SP:SetAttribute("RoCVnsCloth", true) end
		local Kept = Function.ApplyColorMap(SP, ObjectInstance, Template)
		if Kept then
			SP.AlphaMode = Mode or Enum.AlphaMode.Overlay
			ObjectInstance.Transparency = 0
		elseif ObjectInstance.Transparency < 1 then
			ObjectInstance.Transparency = 0.011
		end
	end

	function Function.VnsShirtTexture(ObjectInstance, Character, Extra, Data)
		local DataDetail = PlayerData[Data]
		if not DataDetail or not table.find(DataDetail.CurrentClothes, "Roblox Shirt") then return end
		local Template = (Extra.Shirt and Extra.Shirt.ShirtTemplate) or (Extra.Pants and Extra.Pants.PantsTemplate)
		Function.VnsPaint(ObjectInstance, Template)
	end

