	Function.MeshPartCache = Function.MeshPartCache or {}

	local function CreateMeshPartAsync(Id,Collision,Render)
		Id = getId(Id)

		-- [RoC fix] cache: a mesma malha nao e mais recarregada a cada build/espelho; clona o modelo ja carregado
		local CacheKey = tostring(Id) .. "|" .. tostring(Collision) .. "|" .. tostring(Render)
		local Cached = Function.MeshPartCache[CacheKey]
		if Cached then
			local okClone, Clone = pcall(function()
				return Cached:Clone()
			end)
			if okClone and Clone then
				return Clone
			end
		end

		local success, Object = pcall(function()
			return IS:CreateMeshPartAsync(Id,Collision,Render)
		end)
		
		if success then
			pcall(function()
				local Template = Object:Clone()
				if Template then
					Function.MeshPartCache[CacheKey] = Template
				end
			end)
			return Object
		else
			local backup = Instance.new("MeshPart")
			
			warn("Mesh not found! Please update or check your content folder.")
			return backup
		end
	end

	-- ===================================================================================== --
	-- // [v21] SmartBones Physics: rig VNS com Bones + motor SmartBone (port do DripSync) // --
	-- Arquivos (workspace do executor):
	--   RClothesContent/_vns/module/SmartBone.rbxm          -> motor SmartBone (ModuleScripts)
	--   RClothesContent/_vns/model/breast/1/model.rbxm      -> peito com Bones (Roots L.Bone.001,R.Bone.001)
	--   RClothesContent/_vns/model/butt/1/model.rbxm        -> bunda com Bones (Roots R.Bone,L.Bone)
	--   RClothesContent/_vns/model/collider.rbxm            -> colisores (cabeca/torso/bracos/pernas)
	-- So peito (Breasts 6) e bunda (Butt 6) tem Bones; Torso 9 / Arm 5 / Legs 8 continuam estaticos, como no DripSync.
	-- ===================================================================================== --
	Function.SB = {Tag = nil, ColliderTag = nil, Holder = nil, Stop = nil, Failed = false, Loading = false, Error = nil}
	Function.SB_MODULE_PATH = "RClothesContent/_vns/module/SmartBone.rbxm"
	Function.VNS_COLLIDER_PATH = "RClothesContent/_vns/model/collider.rbxm"

	function Function.VnsGetObjects(Path)
		local Objects
		if env.gca and env.isfile and env.isfile(Path) then
			local ok, Url = pcall(env.gca, Path)
			if ok and type(Url) == "string" and #Url > 0 then
				pcall(function() Objects = game:GetObjects(Url) end)
			end
		end
		if not Objects or #Objects == 0 then
			pcall(function() Objects = game:GetObjects("rbxasset://" .. Path) end)
		end
		if Objects and #Objects > 0 then return Objects end
		return nil
	end

	-- require proprio: ModuleScripts vindos de GetObjects nao rodam com require() no executor, entao roda o Source via loadstring.
	function Function.SBMakeRequire()
		local Cache = {}
		local Require
		Require = function(Module)
			if Cache[Module] ~= nil then return Cache[Module] end
			local LS = (getgenv and getgenv().loadstring) or loadstring
			if type(LS) ~= "function" then error("loadstring indisponivel neste executor") end
			local Src = Module.Source
			if type(Src) ~= "string" or Src == "" then error("Source ilegivel em " .. Module:GetFullName()) end
			if Module.Name == "SmartBone" then
				Src = Src:gsub('Player:WaitForChild%("PlayerScripts"%)',
					'(Player:FindFirstChildOfClass("PlayerScripts") or Player:WaitForChild("PlayerScripts", 3) or script)', 1)
			end
			local Chunk, Err = LS(Src, "=" .. Module.Name)
			if not Chunk then error("loadstring falhou em " .. Module.Name .. ": " .. tostring(Err)) end
			local ModuleEnv = {
				script = Module,
				require = function(Target)
					if typeof(Target) == "Instance" and Target:IsA("ModuleScript") then return Require(Target) end
					return require(Target)
				end,
				task = setmetatable({synchronize = function() end, desynchronize = function() end}, {__index = task}),
			}
			setmetatable(ModuleEnv, {__index = getfenv(Chunk)})
			setfenv(Chunk, ModuleEnv)
			local Result = Chunk()
			Cache[Module] = Result
			return Result
		end
		return Require
	end

	-- Carrega e inicia o SmartBone uma vez por sessao. Retorna a tag de CollectionService ou nil.
	function Function.SBEnsure()
		local SB = Function.SB
		if SB.Tag then return SB.Tag end
		if SB.Failed then return nil end
		if SB.Loading then
			local t0 = os.clock()
			repeat task.wait(0.05) until not SB.Loading or os.clock() - t0 > 15
			return SB.Tag
		end
		SB.Loading = true
		local ok, Err = pcall(function()
			if not (setfenv and getfenv) then error("setfenv/getfenv indisponivel") end
			local Objects = Function.VnsGetObjects(Function.SB_MODULE_PATH)
			local Root = Objects and Objects[1]
			if Root and not Root:IsA("ModuleScript") then
				Root = Root:FindFirstChild("SmartBone", true) or Root:FindFirstChildWhichIsA("ModuleScript", true)
			end
			if not (Root and Root:IsA("ModuleScript")) then error("SmartBone.rbxm nao carregou: " .. Function.SB_MODULE_PATH) end
			for _, D in ipairs(Root:GetDescendants()) do
				if D:IsA("LayerCollector") then pcall(function() D:Destroy() end) end
			end
			local Holder = Instance.new("Folder")
			Holder.Name = "_RCSmartBone"
			Root.Parent = Holder
			pcall(function() Holder.Parent = (env.gethui and env.gethui()) or game:GetService("CoreGui") end)
			if not Holder.Parent then Holder.Parent = game:GetService("ReplicatedStorage") end
			local Tag = game:GetService("HttpService"):GenerateGUID(false)
			Root:SetAttribute("tag", Tag)
			Root:SetAttribute("smartboneTag", Tag)
			-- [v26] igual ao DripSync: tag propria (GUID) para os colisores alem da tag fixa "SmartCollider"
			local ColTag = game:GetService("HttpService"):GenerateGUID(false)
			Root:SetAttribute("smartcolliderTag", ColTag)
			SB.ColliderTag = ColTag
			Root:SetAttribute("inject", true)
			local Require = Function.SBMakeRequire()
			local Engine = Require(Root)
			if type(Engine) ~= "table" or type(Engine.Start) ~= "function" then error("modulo SmartBone sem Start()") end
			local Runtime = Engine.Start()
			if type(Runtime) ~= "table" or type(Runtime.Stop) ~= "function" then error("SmartBone.Start() nao retornou handle") end
			SB.Stop = Runtime.Stop
			SB.Tag = Tag
			SB.Holder = Holder
		end)
		SB.Loading = false
		if not ok then
			SB.Failed = true
			SB.Error = tostring(Err)
			warn("[RoC] SmartBone desativado: " .. SB.Error)
			return nil
		end
		return SB.Tag
	end

	local VnsR15 = {["Torso"] = "UpperTorso", ["Left Arm"] = "LeftUpperArm", ["Right Arm"] = "RightUpperArm",
		["Left Leg"] = "LeftUpperLeg", ["Right Leg"] = "RightUpperLeg"}

	local function VnsResolveCharacterMotors(Root, Character)
		for _, M in ipairs(Root:GetDescendants()) do
			if M:IsA("Motor6D") or M:IsA("Weld") then
				local Attr = M:GetAttribute("Part0")
				local Name = type(Attr) == "string" and Attr:match("^{character}%.(.+)$")
				if Name then
					local Target = Character:FindFirstChild(Name) or (VnsR15[Name] and Character:FindFirstChild(VnsR15[Name]))
					if not (Target and Target:IsA("BasePart")) then return false, Name end
					local P1 = M.Part1
					if P1 then pcall(function() P1.CFrame = Target.CFrame * M.C0 * M.C1:Inverse() end) end
					M.Part0 = Target
				end
			end
		end
		return true
	end

	local function VnsPrepareParts(Root)
		local PP = PhysicalProperties.new(0.001, 0, 0)
		for _, P in ipairs(Root:GetDescendants()) do
			if P:IsA("BasePart") then
				P.Anchored = false
				P.CanCollide = false
				P.CanQuery = false
				P.CanTouch = false
				P.Massless = true
				P.CustomPhysicalProperties = PP
				P:AddTag("RoClothes")
			end
		end
		Root:AddTag("RoClothes")
		Root.Archivable = not hidden
	end

	-- ===================================================================================== --
	-- // [v26] PORT DO DRIPSYNC: Roots automatico, tuning (SB Stiffness/Damping/Elasticity/Gravity) e retag // --
	-- Os rigs ficam em DataDetail.VnsRigs (Character normal, Method 2, NPC e espelho), entao o tuning percorre
	-- os rigs registrados e nao precisa varrer o Method2CharacterFolder como o DripSync faz.
	-- ===================================================================================== --
	Function.SBDefaults = {Stiffness = 0.2, Damping = 0.1, Elasticity = 3, Gravity = Vector3.new(0, -25, 0)}
	Function.SBTuneMap = {Stiffness = "SBStiffness", Damping = "SBDamping", Elasticity = "SBElasticity", Gravity = "SBGravity"}
	Function.SBTuneQueued = false

	-- Garante o atributo Roots (nomes dos Bones filhos diretos da peca). Devolve true se a peca tem fisica.
	function Function.SBEnsureRoots(Part)
		if not (Part and Part:IsA("BasePart")) then return false end
		if Part:GetAttribute("Roots") ~= nil then return true end
		local Names = {}
		for _, C in ipairs(Part:GetChildren()) do
			if C:IsA("Bone") then table.insert(Names, C.Name) end
		end
		if #Names == 0 then return false end
		Part:SetAttribute("Roots", table.concat(Names, ","))
		return true
	end

	-- Aplica os multiplicadores do DataDetail nos atributos da peca (o valor original fica em _RCorig_*).
	function Function.SBTunePart(Part, DataDetail)
		if not (Part and DataDetail) then return end
		for Attr, Field in pairs(Function.SBTuneMap) do
			local Orig = Part:GetAttribute("_RCorig_" .. Attr)
			if Orig == nil then
				Orig = Part:GetAttribute(Attr)
				if Orig == nil then Orig = Function.SBDefaults[Attr] end
				Part:SetAttribute("_RCorig_" .. Attr, Orig)
			end
			local Mult = tonumber(DataDetail[Field]) or 1
			local Value = Orig * Mult
			if Attr == "Damping" then Value = math.clamp(Value, 0, 0.95) end
			if Attr == "Stiffness" then Value = math.clamp(Value, 0, 0.99) end
			Part:SetAttribute(Attr, Value)
		end
	end

	-- O motor so le os atributos ao montar a BoneTree: por isso tira a tag e recoloca no proximo frame.
	function Function.ApplySmartBoneTuning(Name)
		local DataDetail = PlayerData[Name or SelectPlayer]
		local Tag = Function.SB.Tag
		if not (DataDetail and DataDetail.VnsRigs and Tag) then return 0 end
		local CS = game:GetService("CollectionService")
		local Count = 0
		for _, Rig in pairs(DataDetail.VnsRigs) do
			if Rig.Parent then
				for _, P in ipairs(Rig:GetDescendants()) do
					if P:IsA("BasePart") and CS:HasTag(P, Tag) then
						pcall(Function.SBTunePart, P, DataDetail)
						pcall(function() CS:RemoveTag(P, Tag) end)
						task.defer(function()
							if P.Parent and DataDetail.SmartBoneEnabled then
								pcall(function() CS:AddTag(P, Tag) end)
							end
						end)
						Count += 1
					end
				end
			end
		end
		return Count
	end

	-- Debounce (0.3s) para o arrasto dos sliders nao refazer a BoneTree a cada pixel.
	function Function.QueueSmartBoneTuning()
		if Function.SBTuneQueued then return end
		Function.SBTuneQueued = true
		task.delay(0.3, function()
			Function.SBTuneQueued = false
			pcall(Function.ApplySmartBoneTuning, SelectPlayer)
		end)
	end

	-- Chamado ao fechar o script: para o motor SmartBone e remove o holder dos modulos.
	function Function.SBShutdown()
		local SB = Function.SB
		if SB.Stop then pcall(SB.Stop) end
		if SB.Holder then pcall(function() SB.Holder:Destroy() end) end
		SB.Stop = nil
		SB.Tag = nil
		SB.ColliderTag = nil
		SB.Holder = nil
	end

	function Function.VnsEnsureCollider(Character, DataDetail)
		local Existing = Character:FindFirstChild("RC_VNS_collider")
		if Existing then return Existing end
		local Objects = Function.VnsGetObjects(Function.VNS_COLLIDER_PATH)
		if not Objects then return nil end
		local Src = Objects[1]:FindFirstChildOfClass("Model") or Objects[1]
		local Col = Src:Clone()
		for _, O in ipairs(Objects) do pcall(function() O:Destroy() end) end
		Col.Name = "RC_VNS_collider"
		if not VnsResolveCharacterMotors(Col, Character) then Col:Destroy(); return nil end
		VnsPrepareParts(Col)
		local CS = game:GetService("CollectionService")
		for _, P in ipairs(Col:GetDescendants()) do
			if P:IsA("BasePart") then
				P.Transparency = 1
				if not P:GetAttribute("ColliderShape") then
					P:SetAttribute("ColliderShape", P:IsA("Part") and P.Shape.Name or "Box")
				end
			end
		end
		Col.Parent = Character
		for _, P in ipairs(Col:GetDescendants()) do
			if P:IsA("BasePart") then
				CS:AddTag(P, "SmartCollider")
				if Function.SB.ColliderTag then CS:AddTag(P, Function.SB.ColliderTag) end
			end
		end
		DataDetail.VnsRigs = DataDetail.VnsRigs or {}
		DataDetail.VnsRigs[Col.Name] = Col
		return Col
	end

	-- Liga/desliga a fisica nas pecas raiz (as que tem atributo Roots) dos rigs ja montados.
	function Function.VnsApplySmartBoneTags(DataDetail)
		if not DataDetail or not DataDetail.VnsRigs then return end
		local CS = game:GetService("CollectionService")
		local Tag = DataDetail.SmartBoneEnabled and Function.SBEnsure() or Function.SB.Tag
		if not Tag then return end
		for _, Rig in pairs(DataDetail.VnsRigs) do
			if Rig.Parent then
				for _, P in ipairs(Rig:GetDescendants()) do
					if P:IsA("BasePart") and Function.SBEnsureRoots(P) then
						if DataDetail.SmartBoneEnabled then
							pcall(Function.SBTunePart, P, DataDetail)
							CS:AddTag(P, Tag)
						else
							CS:RemoveTag(P, Tag)
						end
					end
				end
			end
		end
	end

	function Function.VnsRigCleanup(Character, DataDetail, Keep)
		if DataDetail and DataDetail.VnsRigs then
			for Name, Rig in pairs(DataDetail.VnsRigs) do
				if not (Keep and Keep[Name]) then
					pcall(function() Rig:Destroy() end)
					DataDetail.VnsRigs[Name] = nil
				end
			end
		end
		if Character then
			for _, C in ipairs(Character:GetChildren()) do
				if C:IsA("Model") and C.Name:sub(1, 7) == "RC_VNS_" and not (Keep and Keep[C.Name]) then
					pcall(function() C:Destroy() end)
				end
			end
		end
	end

	-- Monta o rig de "breast" ou "butt" a partir do model.rbxm (com Bones) e devolve {NomeDaPeca = MeshPart}.
	-- Mesmo fluxo do Function.RigVnsModel do DripSync: resolve {character}.X, recria as MeshParts a partir dos .mesh locais
	-- (o rbxm aponta para rbxasset://_vns/... que nao existe no content do Roblox), cor/escala de pele, colisor e tag do SmartBone.
	function Function.VnsRig(Kind, Character, Extra, Data)
		local DataDetail = PlayerData[Data]
		if not DataDetail or not Character or not Character.Parent then return nil end
		local Path = "RClothesContent/_vns/model/" .. Kind .. "/1/model.rbxm"
		local Objects = Function.VnsGetObjects(Path)
		if not Objects then warn("[RoC] SmartBone: nao carregou " .. Path); return nil end
		local Src = Objects[1]:FindFirstChildOfClass("Model")
		local Rig
		if Src then
			Rig = Src:Clone()
		else
			Rig = Instance.new("Model")
			for _, C in ipairs(Objects[1]:GetChildren()) do
				if C:IsA("BasePart") or C:IsA("Folder") then C:Clone().Parent = Rig end
			end
		end
		for _, O in ipairs(Objects) do pcall(function() O:Destroy() end) end
		Rig.Name = "RC_VNS_" .. Kind

		local Resolved, Missing = VnsResolveCharacterMotors(Rig, Character)
		if not Resolved then
			warn("[RoC] SmartBone: parte do personagem ausente: " .. tostring(Missing))
			Rig:Destroy()
			return nil
		end

		-- Recria as MeshParts com o .mesh local (v4.01, com skinning) e move filhos/motores para a peca nova.
		local Map = {}
		for _, Old in ipairs(Rig:GetDescendants()) do
			if Old:IsA("MeshPart") then
				local Id = Old.MeshId:gsub("^rbxasset://_vns/", "rbxasset://RClothesContent/_vns/")
				local New = CreateMeshPartAsync(Id, Enum.CollisionFidelity.Box, Enum.RenderFidelity.Performance)
				if not New or New.MeshId == "" then
					warn("[RoC] SmartBone: malha nao carregou: " .. Id)
					Rig:Destroy()
					return nil
				end
				New.Name = Old.Name
				pcall(function() New.Size = Old.Size end)
				New.Color = Old.Color
				New.Material = Old.Material
				New.Transparency = Old.Transparency
				New.Reflectance = Old.Reflectance
				New.DoubleSided = Old.DoubleSided
				for K, V in pairs(Old:GetAttributes()) do pcall(function() New:SetAttribute(K, V) end) end
				for _, Child in ipairs(Old:GetChildren()) do Child.Parent = New end
				New.CFrame = Old.CFrame
				New.Parent = Old.Parent
				Map[Old] = New
			end
		end
		for _, M in ipairs(Rig:GetDescendants()) do
			if M:IsA("Motor6D") or M:IsA("Weld") then
				if Map[M.Part0] then M.Part0 = Map[M.Part0] end
				if Map[M.Part1] then M.Part1 = Map[M.Part1] end
			end
		end
		for Old in pairs(Map) do Old:Destroy() end

		-- Cor e escala iguais ao DripSync.
		local Base = Function.VnsBodyColor(Character, Extra, Data)
		local Dark = Function.VnsDarkColor(Base, Extra, Data, Kind == "breast") -- [v48] SmartBone ligado: peito tambem usa o rosa fixo no Base
		local BScale = tonumber(DataDetail.BreastsScale) or 1
		local BtScale = tonumber(DataDetail.ButtsScale) or 1
		local Parts = {}
		for _, P in ipairs(Rig:GetDescendants()) do
			if P:IsA("MeshPart") then
				local Name = P.Name
				if Name:find("Nipple", 1, true) then
					if Dark then P.Color = Dark end
				elseif Base then
					P.Color = Base
				end
				local SA = P:FindFirstChildOfClass("SurfaceAppearance")
				if SA and Dark then pcall(function() SA.Color = Dark end) end
				local S = (Name:find("Breast", 1, true) and not Name:find("Nipple", 1, true) and BScale)
					or (Name:find("Butt", 1, true) and BtScale) or nil
				if S then P.Size = P.Size * S end
				Parts[Name] = P
			end
		end

		VnsPrepareParts(Rig)

		-- Remove rig antigo do mesmo tipo e publica o novo.
		local Old = Character:FindFirstChild(Rig.Name)
		while Old do Old:Destroy(); Old = Character:FindFirstChild(Rig.Name) end
		Rig.Parent = Character
		DataDetail.VnsRigs = DataDetail.VnsRigs or {}
		DataDetail.VnsRigs[Rig.Name] = Rig

		-- Texturas de roupa nas pecas da bunda (mesmas funcoes da versao estatica).
		if Kind == "butt" then
			for _, P in pairs(Parts) do
				pcall(Function.VnsPantsTexture, P, Character, Extra, Data)
				pcall(Function.NewWomanTorsoPantsClothing, P, Character, Extra, Data)
			end
		end

		-- Fisica: colisor primeiro (o SmartBone junta os SmartCollider no Setup), depois a tag nas pecas com Roots.
		if DataDetail.SmartBoneEnabled then
			local Tag = Function.SBEnsure()
			if Tag then
				Function.VnsEnsureCollider(Character, DataDetail)
				local CS = game:GetService("CollectionService")
				for _, P in ipairs(Rig:GetDescendants()) do
					if P:IsA("BasePart") and Function.SBEnsureRoots(P) then
						pcall(Function.SBTunePart, P, DataDetail)
						CS:AddTag(P, Tag)
					end
				end
			end
		end

		return Parts
	end

	-- [v25] Roupa Roblox do peito com SmartBone ligado (igual ao DripSync: RigVnsModel(breastclothes) + Motor6D.Part0 = Breasts).
	-- Antes a roupa/sutia era malha ESTATICA soldada no Torso e a "Roblox Breasts Clothing" ainda escondia o peito com Bones,
	-- entao o peito ficava parado assim que uma roupa Roblox entrava. Agora a roupa e uma malha com skin presa aos MESMOS Bones
	-- do peito (peca "Breasts" do RC_VNS_breast), entao balanca junto com o SmartBone.
	function Function.VnsRigBra(Variant, Character, Extra, Data, PaintShirt)
		local DataDetail = PlayerData[Data]
		if not DataDetail or not Character or not Character.Parent then return nil end
		local RigBreast = Character:FindFirstChild("RC_VNS_breast")
		if not RigBreast then return nil end
		local Breasts = RigBreast:FindFirstChild("Breasts", true)
		local LB = RigBreast:FindFirstChild("Left Breast", true)
		local RB = RigBreast:FindFirstChild("Right Breast", true)
		if not (Breasts and Breasts:IsA("BasePart") and LB and LB:IsA("BasePart") and RB and RB:IsA("BasePart")) then return nil end

		local Path = "RClothesContent/_vns/model/breastclothes/" .. tostring(Variant) .. "/model.rbxm"
		local Objects = Function.VnsGetObjects(Path)
		if not Objects then warn("[RoC] SmartBone: nao carregou " .. Path); return nil end
		local Old
		for _, O in ipairs(Objects) do
			if O:IsA("MeshPart") and O.Name == "BreastClothes" then Old = O else Old = O:FindFirstChild("BreastClothes", true) end
			if Old then break end
		end
		local function Free() for _, O in ipairs(Objects) do pcall(function() O:Destroy() end) end end
		if not (Old and Old:IsA("MeshPart")) then Free(); return nil end

		-- O rbxm aponta para rbxasset://_vns/... (nao existe no content do Roblox): recria a MeshPart a partir do .mesh local, com skin.
		local Id = Old.MeshId:gsub("^rbxasset://_vns/", "rbxasset://RClothesContent/_vns/")
		local New = CreateMeshPartAsync(Id, Enum.CollisionFidelity.Box, Enum.RenderFidelity.Performance)
		if not New or New.MeshId == "" then
			warn("[RoC] SmartBone: malha do sutia nao carregou: " .. Id)
			Free()
			return nil
		end
		New.Name = "BreastClothes"
		local BScale = tonumber(DataDetail.BreastsScale) or 1
		pcall(function() New.Size = Old.Size * BScale end)
		New.Color = Function.VnsBodyColor(Character, Extra, Data) or Old.Color
		New.Material = Old.Material
		New.Transparency = Old.Transparency
		New.Reflectance = Old.Reflectance
		New.DoubleSided = Old.DoubleSided
		for K, V in pairs(Old:GetAttributes()) do pcall(function() New:SetAttribute(K, V) end) end

		local Motor
		for _, Child in ipairs(Old:GetChildren()) do
			Child.Parent = New
			if Child:IsA("Motor6D") and not Motor then Motor = Child end
		end
		if not Motor then
			Motor = Instance.new("Motor6D")
			Motor.Name = "BreastsClothes"
			Motor.Parent = New
		end

		-- Posiciona no meio dos dois peitos, com a orientacao da peca "Breasts" (mesmo calculo do DripSync).
		local TargetCF = CFrame.new((LB.Position + RB.Position) / 2) * (Breasts.CFrame - Breasts.Position)
		New.CFrame = TargetCF
		Motor.Part1 = New
		Motor.C0 = Breasts.CFrame:Inverse() * TargetCF * Motor.C1
		Motor.Part0 = Breasts

		New.Anchored = false
		New.CanCollide = false
		New.CanQuery = false
		New.CanTouch = false
		New.Massless = true
		New.CustomPhysicalProperties = PhysicalProperties.new(0.001, 0, 0)
		New:AddTag("RoClothes")

		local OldBra = RigBreast:FindFirstChild("BreastClothes")
		while OldBra do OldBra:Destroy(); OldBra = RigBreast:FindFirstChild("BreastClothes") end
		New.Parent = RigBreast
		Free()

		-- Camisa Roblox pintada na malha da roupa (AlphaMode.Transparency), como o DripSync faz no BreastClothes.
		local Template = Extra and Extra.Shirt and Extra.Shirt.ShirtTemplate
		if PaintShirt and Template and Template ~= "" then
			Function.VnsPaint(New, Template, Enum.AlphaMode.Transparency)
		end
		return New
	end

	-- [v44] Peito VNS (static) por baixo do sutia/roupa Roblox: com a roupa do peito o Left/Right Breast do rig ficava com
	-- Transparency 1 (invisivel) e com o SurfaceAppearance da areola tingido. Aqui o peito e revelado (T=0, cor da pele, sem ColorSA)
	-- e travado em 0 enquanto o sutia existir, porque outras rotinas (Unvisible/HP/realtime) tentam esconder de novo.
	function Function.VnsRevealStaticBreast(Character, Extra, Data, BraPart)
		local RigBreast = Character and Character:FindFirstChild("RC_VNS_breast")
		if not RigBreast then return end
		for _, Name in ipairs({"Left Breast", "Right Breast"}) do
			local P = RigBreast:FindFirstChild(Name, true)
			if P and P:IsA("BasePart") then
				local Areola = P:FindFirstChild("ColorSA")
				while Areola do Areola:Destroy(); Areola = P:FindFirstChild("ColorSA") end
				pcall(Function.VnsSkin, P, Character, Extra, Data)
				P:SetAttribute("Alpha", 0)
				P:SetAttribute("maxTransparencyRC", 0)
				P.Transparency = 0
				if not P:GetAttribute("RCBraReveal") then
					P:SetAttribute("RCBraReveal", true)
					P:GetPropertyChangedSignal("Transparency"):Connect(function()
						if P.Transparency ~= 0 and BraPart and BraPart.Parent then P.Transparency = 0 end
					end)
				end
			end
		end
	end

	-- [v22] Acha a peca do rig SmartBone (RC_VNS_breast / RC_VNS_butt) pelo nome, ex.: "Left Butt".
	function Function.VnsResolveRigParent(Character, Name, Data)
		local DD = PlayerData[Data]
		if DD and DD.VnsRigs then
			for RigName, Rig in pairs(DD.VnsRigs) do
				if RigName ~= "RC_VNS_collider" and Rig and Rig.Parent then
					local F = Rig:FindFirstChild(Name, true)
					if F and F:IsA("BasePart") then return F end
				end
			end
		end
		if Character then
			for _, C in ipairs(Character:GetChildren()) do
				if C:IsA("Model") and C.Name:sub(1, 7) == "RC_VNS_" and C.Name ~= "RC_VNS_collider" then
					local F = C:FindFirstChild(Name, true)
					if F and F:IsA("BasePart") then return F end
				end
			end
		end
		return nil
	end

	-- [v39] Ancoras do VNS com SmartBone. A malha do rig e skinada: a peca fica parada e so os vertices mexem com os Bones,
	-- entao roupa soldada nela fica fixa. Baseado no _vnsBreastAnchor do DripSync (~26125). Tres pecas invisiveis por lado:
	--   Nip  = pose do mamilo padrao (Piercing/Lactation, Parent {"Torso","Left Breast","Nipple"});
	--   Br   = pose do peito padrao com o mamilo em Rel*BreastsScale (roupas com Scale="BreastsScale", ex.: Heart Stickers);
	--   Br1  = pose do peito padrao com o mamilo em Rel sem escala (roupas sem Scale, ex.: Cross Tape).
	-- A pose e presa ao Bone mais proximo (posicao E rotacao), com o deslocamento gravado na pose de repouso. As pecas NAO sao
	-- ancoradas: ficam presas por Weld na malha do mamilo do rig (que anda com o personagem); so o C0 muda por frame.
	-- Ajuste fino ao vivo: atributos Vector3 "RCBreastPos_Left"/"RCBreastRot_Left" (graus) no modelo RC_VNS_breast (e _Right),
	-- aplicados em volta do mamilo; ou Function.VnsBreastAnchorFix[Side] = {Pos=..., Rot=...}.
	-- Retorna NipAnchor, BreastAnchor, BreastAnchorSemEscala, ou nil + motivo.
	function Function.VnsBreastAnchors(Character, Side, TorsoPart, Data)
		local DD = PlayerData[Data]
		if Function.VnsNippleAnchorEnabled == false then return nil, "desativada (Function.VnsNippleAnchorEnabled=false)" end
		local Rel = Function.VnsDsNipRel and Function.VnsDsNipRel[Side]
		local Rot = Function.VnsDsBreastRot and Function.VnsDsBreastRot[Side]
		if not (TorsoPart and DD and Rel and Rot) then return nil, "dados ausentes" end
		if tonumber(DD.BreastsType) ~= 6 then return nil, "BreastsType ~= 6" end
		local Rig = Character and Character:FindFirstChild("RC_VNS_breast")
		if not Rig then
			local R2 = DD.VnsRigs and DD.VnsRigs["RC_VNS_breast"]
			if R2 and R2.Parent then Rig = R2 end
		end
		if not Rig then return nil, "sem RC_VNS_breast" end
		local NipKey, BrKey, Br1Key = "RCNipAnchor_" .. Side, "RCBreastAnchor_" .. Side, "RCBreastAnchor1_" .. Side
		Function.VnsAnchorLive = Function.VnsAnchorLive or setmetatable({}, {__mode = "k"})
		local ExNip, ExBr, ExBr1 = Rig:FindFirstChild(NipKey), Rig:FindFirstChild(BrKey), Rig:FindFirstChild(Br1Key)
		if ExNip and ExBr and ExBr1 and Function.VnsAnchorLive[ExNip] and Function.VnsAnchorLive[ExBr] and Function.VnsAnchorLive[ExBr1] then
			return ExNip, ExBr, ExBr1
		end
		if ExNip then ExNip:Destroy() end
		if ExBr then ExBr:Destroy() end
		if ExBr1 then ExBr1:Destroy() end
		local NipMesh = Rig:FindFirstChild(Side .. " Nipple", true)
		if not (NipMesh and NipMesh:IsA("BasePart")) then return nil, "sem malha do mamilo no rig" end
		if (NipMesh.Position - TorsoPart.Position).Magnitude > 10 then return nil, "rig ainda nao posicionado no Torso" end
		-- Pose de repouso do Bone (sem Transform). Se WorldCFrame nao existir, cai na pose transformada.
		local function Rest(B)
			local ok, cf = pcall(function() return B.WorldCFrame end)
			if ok and typeof(cf) == "CFrame" then return cf end
			return B.TransformedWorldCFrame
		end
		local Tail, Best = nil, math.huge
		for _, B in ipairs(Rig:GetDescendants()) do
			if B:IsA("Bone") then
				local D = (Rest(B).Position - NipMesh.Position).Magnitude
				if D < Best then Tail, Best = B, D end
			end
		end
		if not Tail or Best > 1.5 then return nil, "sem Bone perto (dist=" .. tostring(Best) .. ")" end
		-- Pose do mamilo padrao no repouso: posicao da malha do mamilo, rotacao Torso * rot * Rel (DripSync), guardada no referencial do Bone.
		local NipWorld0 = CFrame.new(NipMesh.Position) * (TorsoPart.CFrame.Rotation * Rot * Rel.Rotation)
		local Offset = Rest(Tail):ToObjectSpace(NipWorld0)

		local DKey = "v39diag/" .. Side
		if not Function.VnsWarned[DKey] then
			Function.VnsWarned[DKey] = true
			local x, y, z = TorsoPart.CFrame:ToObjectSpace(NipMesh.CFrame):ToEulerAnglesXYZ()
			warn(("[RoC][v39] ancora %s: BreastsScale=%s TorsoSize=%s bone=%s dist=%.3f NipMeshRotRelTorso(deg)=%.0f,%.0f,%.0f"):format(
				Side, tostring(DD.BreastsScale), tostring(TorsoPart.Size), Tail.Name, Best, math.deg(x), math.deg(y), math.deg(z)))
		end

		-- Os nomes nao podem ser "Nipple"/"Left Breast": VnsResolveRigParent acharia e trataria como peca do rig.
		local function MakeAnchor(Name)
			local A = Instance.new("Part")
			A.Name = Name
			A.Size = Vector3.new(0.05, 0.05, 0.05)
			A.Transparency = 1
			A.Anchored = false
			A.CanCollide = false
			A.CanQuery = false
			A.CanTouch = false
			A.CastShadow = false
			A.Massless = true
			A.CustomPhysicalProperties = PhysicalProperties.new(0.0001)
			local W = Instance.new("Weld")
			W.Name = Name .. " Weld"
			W.Part0 = NipMesh
			W.Part1 = A
			return A, W
		end
		local NipA, NipW = MakeAnchor(NipKey)
		local BrA, BrW = MakeAnchor(BrKey)
		local Br1A, Br1W = MakeAnchor(Br1Key)
		local function FixCF()
			local P = Rig:GetAttribute("RCBreastPos_" .. Side)
			local R = Rig:GetAttribute("RCBreastRot_" .. Side)
			local Cfg = Function.VnsBreastAnchorFix and Function.VnsBreastAnchorFix[Side]
			if typeof(P) ~= "Vector3" then P = (Cfg and Cfg.Pos) or Vector3.zero end
			if typeof(R) ~= "Vector3" then R = (Cfg and Cfg.Rot) or Vector3.zero end
			return CFrame.new(P) * CFrame.Angles(math.rad(R.X), math.rad(R.Y), math.rad(R.Z))
		end
		local function Place()
			local Sc = tonumber(DD.BreastsScale) or 1
			local RelS = Rel - Rel.Position + Rel.Position * Sc
			local NipWorld = Tail.TransformedWorldCFrame * Offset
			local Base = NipMesh.CFrame
			local Fix = FixCF()
			NipW.C0 = Base:ToObjectSpace(NipWorld)
			BrW.C0 = Base:ToObjectSpace(NipWorld * Fix * RelS:Inverse())
			Br1W.C0 = Base:ToObjectSpace(NipWorld * Fix * Rel:Inverse())
		end
		Place()
		NipA.CFrame = NipMesh.CFrame * NipW.C0
		BrA.CFrame = NipMesh.CFrame * BrW.C0
		Br1A.CFrame = NipMesh.CFrame * Br1W.C0
		NipW.Parent = NipA
		BrW.Parent = BrA
		Br1W.Parent = Br1A
		NipA.Parent = Rig
		BrA.Parent = Rig
		Br1A.Parent = Rig
		Function.VnsAnchorSeq = (Function.VnsAnchorSeq or 0) + 1
		local BindName = "RCVnsNipAnchor" .. Function.VnsAnchorSeq
		RS:BindToRenderStep(BindName, Enum.RenderPriority.Character.Value + 1, function()
			if not (NipA.Parent and BrA.Parent and Br1A.Parent and Tail:IsDescendantOf(Rig) and NipMesh:IsDescendantOf(Rig)
				and TorsoPart.Parent and tonumber(DD.BreastsType) == 6) then
				pcall(RS.UnbindFromRenderStep, RS, BindName)
				Function.VnsAnchorLive[NipA] = nil
				Function.VnsAnchorLive[BrA] = nil
				Function.VnsAnchorLive[Br1A] = nil
				if NipA.Parent then NipA:Destroy() end
				if BrA.Parent then BrA:Destroy() end
				if Br1A.Parent then Br1A:Destroy() end
				return
			end
			Place()
		end)
		Function.VnsAnchorLive[NipA] = true
		Function.VnsAnchorLive[BrA] = true
		Function.VnsAnchorLive[Br1A] = true
		return NipA, BrA, Br1A
	end

	-- Compat. com o v36/v37: devolve so a ancora do mamilo (ou nil + motivo).
	function Function.VnsNippleAnchor(Character, Side, TorsoPart, Data)
		local Nip, Br = Function.VnsBreastAnchors(Character, Side, TorsoPart, Data)
		if Nip then return Nip end
		return nil, Br
	end

	-- [v22] Roupa Classic (camisa/calca) sobre peca com Bones: pinta SurfaceAppearance Overlay na propria peca. Calca vence camisa, como no DripSync.
	-- [v45] Bunda VNS static com SmartBone: Roblox Pants + Roblox Butt Shirt juntas, como na versao estatica (pants na malha, camisa por cima).
	-- Antes a calca era pintada na malha inteira e a camisa era ignorada. Agora a camisa vira uma copia da peca (mesmos Bones, mesma fisica)
	-- levemente maior, pintada com AlphaMode.Transparency, entao o que for transparente na camisa deixa a calca/pele aparecer por baixo.
	function Function.VnsButtShirtOverlay(Part, Template)
		if not (Part and Part.Parent and Part:IsA("MeshPart")) then return end
		local Holder = Part.Parent
		local OverlayName = "RCShirtOverlay_" .. Part.Name:gsub("%s", "")
		local Old = Holder:FindFirstChild(OverlayName)
		while Old do Old:Destroy(); Old = Holder:FindFirstChild(OverlayName) end

		local Clone = Part:Clone()
		Clone.Name = OverlayName
		for _, C in ipairs(Clone:GetChildren()) do
			if C:IsA("SurfaceAppearance") or C:IsA("Decal") or C:IsA("Texture") then C:Destroy() end
		end
		Clone.TextureID = ""
		pcall(function() Clone.Size = Part.Size + Vector3.new(0.003, 0.003, 0.003) end)

		-- motor/weld que prende a peca ao personagem: se nao veio dentro da peca, copia o que existir no rig apontando para ela
		local HasMotor = false
		for _, C in ipairs(Clone:GetChildren()) do
			if C:IsA("Motor6D") or C:IsA("Weld") then HasMotor = true end
		end
		if not HasMotor then
			local Root = Part:FindFirstAncestorOfClass("Model") or Holder
			for _, M in ipairs(Root:GetDescendants()) do
				if (M:IsA("Motor6D") or M:IsA("Weld")) and M.Part1 == Part and not M:IsDescendantOf(Part) then
					local M2 = M:Clone()
					M2.Part1 = Clone
					M2.Parent = Clone
					HasMotor = true
				end
			end
		end
		if not HasMotor then Clone:Destroy(); return end

		Clone.Anchored = false
		Clone.CanCollide = false
		Clone.CanQuery = false
		Clone.CanTouch = false
		Clone.Massless = true
		Clone.Parent = Holder
		Function.VnsPaint(Clone, Template, Enum.AlphaMode.Transparency)
		return Clone
	end

	function Function.VnsPaintRigCloth(Part, Fn, Extra, Data)
		if not (Part and Extra) then return end
		local Names = {}
		if typeof(Fn) == "string" then Names[1] = Fn
		elseif typeof(Fn) == "table" then for _, v in pairs(Fn) do Names[#Names + 1] = v end end
		local Template, IsShirt
		for _, N in ipairs(Names) do
			if type(N) == "string" then
				local Low = N:lower()
				if Low:find("pants", 1, true) then
					Template = (Extra.Pants and Extra.Pants.PantsTemplate) or Template; IsShirt = false
				elseif Low:find("shirt", 1, true) and Template == nil then
					Template = Extra.Shirt and Extra.Shirt.ShirtTemplate; IsShirt = true
				end
			end
		end
		if not Template or Template == "" then return end
		local DD = PlayerData[Data]
		-- [v48 fix] Mesma regra do TorsoShirtTexture (caminho sem SmartBones): a camisa so e pintada na bunda se "Roblox Shirt"
		-- (ou New Woman / Roblox Breasts Clothing) estiver ligado. Antes, com SmartBones, a camisa era pintada mesmo desligada.
		if IsShirt and Part.Name:find("Butt", 1, true) and DD and DD.CurrentClothes
			and not (table.find(DD.CurrentClothes, "Roblox Shirt") or table.find(DD.CurrentClothes, "New Woman") or table.find(DD.CurrentClothes, "Roblox Breasts Clothing")) then
			return
		end
		if IsShirt and DD and DD.CurrentClothes and table.find(DD.CurrentClothes, "Roblox Pants") and Extra.Pants and Extra.Pants.PantsTemplate then
			-- [v45] bunda: a calca fica na malha e a camisa entra como camada por cima (igual a versao estatica)
			if Part.Name:find("Butt", 1, true) then pcall(Function.VnsButtShirtOverlay, Part, Template) end
			return
		end
		local SA = Part:FindFirstChildOfClass("SurfaceAppearance")
		if SA and not SA:GetAttribute("RoCVnsCloth") then return end -- ja tem SurfaceAppearance proprio (ex.: aureola): nao sobrescreve
		Function.VnsPaint(Part, Template)
	end

	function Function.convertToJSON(value:UDim2)
		if typeof(value) == "Color3" then
			return {["R"] = value.R, ["G"] = value.G, ["B"] = value.B}
		elseif typeof(value) == "Vector3" then
			return {["X"] = value.X, ["Y"] = value.Y, ["Z"] = value.Z}
		elseif typeof(value) == "EnumItem" then
			return {["EnumType"] = tostring(value.EnumType), ["Value"] = value.Value}
		elseif typeof(value) == "UDim2" then
			return {["Scale"]={["X"] = value.X.Scale, ["Y"] = value.Y.Scale}, 
				["Offset"]={["X"] = value.X.Offset, ["Y"] = value.Y.Offset}}
		end
		return value
	end

	function Function.convertFromJSON(value)
		if typeof(value) == "table" then
			if value["R"] and value["G"] and value["B"] then
				return Color3.new(value.R, value.G, value.B)
			elseif value["X"] and value["Y"] and value["Z"] then
				return Vector3.new(value.X, value.Y, value.Z)
			elseif value["EnumType"] and value["Value"] then
				return Enum[value.EnumType]:FromValue(value.Value)
			elseif value["Scale"] and value["Offset"] then
				return UDim2.new(value.Scale.X, value.Offset.X, value.Scale.Y, value.Offset.Y)
			end
		end
		return value,true
	end

	function Function.toFormatString(value)
		if typeof(value) == "Color3" then
			return string.format("Color3.fromRGB(%s, %s, %s)", value.R * 255, value.G * 255, value.B * 255)
		elseif typeof(value) == "Vector3" then
			return string.format("Vector3.new(%s, %s, %s)", value.X, value.Y, value.Z)
		elseif typeof(value) == "string" then
			return string.format("%q", value)
		elseif typeof(value) == "CFrame" then
			return string.format("CFrame.new(%s)", tostring(value))
		end
		return tostring(value)
	end

	function Function.JaroSimilarity(original: string, target: string): number
		local original_len = original:len()
		local target_len = target:len()

		if (original_len == 0 and target_len == 0) or (original == target) then return 1 end

		local match_distance = (math.floor(math.max(original_len, target_len) / 2)) - 1
		local original_matches = table.create(original_len, false)
		local target_matches = table.create(target_len, false)

		local matches = 0
		local transpositions = 0

		local min = math.min
		local max = math.max
		for i = 1, original_len do
			local _start = max(1, i - match_distance)
			local _end = min(i + match_distance + 1, target_len)

			for j = _start, _end do
				if target_matches[j] then
					continue end
				if original:sub(i, i) ~= target:sub(j, j)  then
					continue end
				original_matches[i] = true
				target_matches[j] = true
				matches += 1
				break
			end
		end

		if matches == 0 then
			return 0
		end

		local k = 1
		for i = 1, original_len do
			if not original_matches[i] then continue end

			while target_matches[k] == false do
				k += 1
			end

			if original:sub(i, i) ~= target:sub(k, k) then
				transpositions += 1
			end
			k += 1
		end

		local similarity = ((matches / original_len) + (matches / target_len) + ((matches - transpositions / 2) / matches)) / 3

		return similarity
	end

	function Function.JaroDistance(original: string, target: string): number
		return 1 - Function.JaroSimilarity(original, target)
	end
	
	function Function.getExtension(filename)
		return filename:match("%.([^%.]+)$") or ""
	end

	function Function.AttachmentCreate(Character)
		for Attach, ParentName in pairs(AttachmentParent) do
			local Base = Character:FindFirstChild(ParentName)

			if Base and not Base:FindFirstChild(Attach) then
				local Attachment = Instance.new("Attachment", Base)
				Attachment.Name = Attach
				Attachment.CFrame = AttachmentCFrame[Attach]
			end
		end
	end

	function Function.HeadMesh(Part)
		local SpecialMesh = Instance.new("SpecialMesh", Part)
		SpecialMesh.MeshType = Enum.MeshType.Head
		SpecialMesh.Scale = Vector3.new(1.25, 1.25, 1.25)
	end

	function Function.Dummy(CF)
		local DummyModel = Instance.new("Model")
		DummyModel.Archivable = not hidden
		DummyModel:AddTag("RoClothes")
		local DummyHumanoid = Instance.new("Humanoid", DummyModel)

		local RootPart = Instance.new("Part", DummyModel)
		RootPart.Name = "HumanoidRootPart"
		RootPart.Size = Vector3.new(2,2,1)
		RootPart.Anchored = true
		RootPart.Transparency = 1

		DummyModel.PrimaryPart = RootPart

		for Name, Property in pairs(DummyMesh) do
			local Part = Instance.new("Part", DummyModel)
			Part.Size = Property.Size
			Part.CFrame = RootPart.CFrame * Property.Offset
			Part.Anchored = true
			Part.Name = Name

			if Name == "Head" then
				Function.HeadMesh(Part)
			end
		end

		Function.AttachmentCreate(DummyModel)

		return DummyModel
	end

	function Function.CharacterPreview(Data)
		if CharacterPreviewLoading == false then
			CharacterPreviewLoading = true
			GUIObject.ViewportFrame:ClearAllChildren()

			local Dummy = Function.Dummy()

			local DataCharacter = PS:FindFirstChild(Data)

			if DataCharacter then
				for _, v in pairs(DataCharacter.Character:GetChildren()) do
					if v:IsA("Shirt") or v:IsA("Pants") or v:IsA("ShirtGraphic") or v:IsA("Accessory") or v:IsA("BodyColors") then
						local cv = v:Clone()

						cv.Parent = Dummy

						if cv:IsA("Accessory") then
							local Handle = cv:FindFirstChildOfClass("Part") or v:FindFirstChildOfClass("MeshPart")

							if Handle then
								local Weld = Handle:FindFirstChildOfClass("Weld")

								if Weld and Weld.Part0 then
									Weld.Part0 = Dummy:FindFirstChild(Weld.Part0.Name)
								end
							end
						end
					elseif v:IsA("Part") then
						local Base = Dummy:FindFirstChild(v.Name)

						if Base then
							Base.Color = v.Color
						end
					end
				end
			end

			local DummyRoot = Dummy:FindFirstChild("HumanoidRootPart") or Dummy:FindFirstChildOfClass("Part")
			if DummyRoot then
				DummyRoot.CFrame = CFrame.new(0, -10000, 0)
			end
			Dummy.Parent = game.Workspace
			Function.CharacterReset(SelectPlayer, Data)
			local ExecOk, ExecErr = pcall(Function.CharacterExecute, Dummy, Data)

			task.wait()

			if not ExecOk then
				if Dummy and Dummy.Parent then
					Dummy:Destroy()
				end
				CharacterPreviewLoading = false
				warn("[RoC] CharacterPreview execute:", ExecErr)
				return nil
			end

			Dummy.Parent = GUIObject.ViewportFrame

			CharacterPreviewLoading = false

			return Dummy
		end
	end

	function Function.SpringCreate(Object, Base, Target, Velocity, Speed, Damper, PositionOffset, Position, RotationOffset, Rotation, Data)

		local Weld = Object:FindFirstChildOfClass("Weld")
		if Weld then
			--[[
			if Base.Name == "Torso" and Weld.Part0 == Base then
				local invert0 = Weld.Part1.CFrame:ToObjectSpace(Weld.Part1.CFrame:ToWorldSpace(Weld.C1))
				local invert1 = Weld.Part1.CFrame:ToObjectSpace(Weld.Part1.CFrame:ToWorldSpace(Weld.C0))
				PlayerData[Data].CurrentPartList.RealtimeUpdateList.Mesh[Object].CFrame = invert0
				PlayerData[Data].CurrentPartList.RealtimeUpdateList.Mesh[Object].CFrame1 = invert1
				Weld.Part0 = Object
				Weld.Part1 = Base
				Weld.C0 = invert0
				Weld.C1 = invert1
				
			end
			]]
			local CF = Weld.C0
			local CF1 = Weld.C1

			local Spring = Function.Spring.new(Vector3.new(0,0,0))
			Spring.Target = Target;
			Spring.Velocity = Velocity;
			Spring.Speed = Speed;
			Spring.Damper = Damper;


			PlayerData[Data].CurrentPartList.BodyPartPhysics[Object] = {
				Spring = Spring,
				Base = Base,
				Weld = Weld,
				CF = CF,
				CF1 = CF1,
				OriginCFrame = Base.CFrame,
				PositionOffset = PositionOffset,
				Position = Position,
				RotationOffset = RotationOffset,
				Rotation = Rotation,
				BreastsType = PlayerData[Data].BreastsType
			}
		end
	end

	function Function.MinMaxCalulate(Base, Min, Max)
		return math.max(math.min(Base, Max), Min)
	end

	function Function.CFrameOrientation(CF)
		local x, y, z = CF:ToOrientation()
		return Vector3.new(math.deg(x), math.deg(y), math.deg(z))
	end

	function Function.MultiplyCalculate(Base, Default)
		local X = Base.X / Default.X
		local Y = Base.Y / Default.Y
		local Z = Base.Z / Default.Z

		return X,Y,Z
	end

