	function Function.UIStrokeCreate(Parent)
		local UIStroke = Instance.new("UIStroke")
		UIStroke.Color = Function.MenuTheme.Accent
		UIStroke.Thickness = 1.5
		UIStroke.Transparency = 0.35
		UIStroke.Parent = Parent
		return UIStroke
