	-- cartão 3D Flat para frame que só mostra texto (TextLabel 1x1, ex.: "Bundle: X").
	-- O frame fica transparente; superfície e degrau vão em camadas próprias, como no ModernStyle.
	function Function.FlatCard(Frame)
		if not (Frame and Frame:IsA("Frame")) or Frame:FindFirstChild("ModernSurface") then return end
		local Label
		for _, Child in ipairs(Frame:GetChildren()) do
			if Child:IsA("TextLabel") and Child.Size == UDim2.new(1, 0, 1, 0) then
				Label = Child
				break
			end
		end
		if not Label then return end
		local Theme = Function.MenuTheme
		local St = Theme.Style
		for _, Child in ipairs(Frame:GetChildren()) do
			if Child:IsA("UIGradient") then Child.Enabled = false end
			if Child:IsA("UIStroke") then Child:Destroy() end
		end
		Frame.BackgroundTransparency = 1
		Frame.BorderSizePixel = 0
		local Radius = UDim.new(0, St.Radius)
		Function.ModernCorner(Frame, Radius)
		Label.ZIndex = math.max(Label.ZIndex, 3)

		local Surface = Instance.new("Frame")
		Surface.Name = "ModernSurface"
		Surface.Size = UDim2.fromScale(1, 1)
		Surface.BackgroundColor3 = Theme.Categories.accent.A
		Surface.BorderSizePixel = 0
		Surface.ZIndex = Label.ZIndex - 1
		Surface.Parent = Frame
		Function.ModernCorner(Surface, Radius)
		local Shade = Instance.new("UIGradient")
		Shade.Name = "ModernShade"
		Shade.Color = ColorSequence.new(St.ShadeTop, St.ShadeBottom)
		Shade.Rotation = 90
		Shade.Parent = Surface

		local Stroke = Instance.new("UIStroke")
		Stroke.Name = "ModernStroke"
		Stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
		Stroke.Color = Theme.Accent
		Stroke.Thickness = 1
		Stroke.Transparency = St.StrokeHover
		Stroke.Parent = Frame

		Function.ModernDepthSync(Frame)

		Label.Font = Enum.Font.GothamBold
		Label.TextColor3 = Function.ModernText
		Label.TextStrokeTransparency = 1
		Label.TextScaled = true
		local Limit = Label:FindFirstChildOfClass("UITextSizeConstraint") or Instance.new("UITextSizeConstraint")
		Limit.MaxTextSize = 18
		Limit.MinTextSize = 8
		Limit.Parent = Label
		local Pad = Label:FindFirstChild("ModernPad") or Instance.new("UIPadding")
		Pad.Name = "ModernPad"
		Pad.PaddingTop = UDim.new(0.18, 0)
		Pad.PaddingBottom = UDim.new(0.18, 0)
		Pad.PaddingLeft = UDim.new(0, 10)
		Pad.PaddingRight = UDim.new(0, 10)
		Pad.Parent = Label
	end

	-- // PASSE 3D FLAT GERAL // telas montadas fora do ModernStyle (EDIT+RECOLOR, loja do
	-- Catalog, Bundles, aba Menu). Não troca cor de estado nem posição: só fonte, sombreado,
	-- raio, contorno e degrau. Idempotente (atributo Flat3D) e segue itens criados depois.
	local FlatFontBold = {[Enum.Font.Code] = true, [Enum.Font.SourceSans] = true, [Enum.Font.SourceSansBold] = true, [Enum.Font.Arial] = true, [Enum.Font.ArialBold] = true, [Enum.Font.Legacy] = true}

	local function FlatSkip(Obj)
		if Obj:GetAttribute("Flat3D") then return true end
		local Name = Obj.Name
		if Name == "ModernSurface" or Name == "ModernDepth" or Name == "FlatDepth" or Name == "FlatRow" then return true end
		local Parent = Obj.Parent
		while Parent and Parent ~= GUIObject.PageFrame do
			if Parent == GUIObject.ButtonFrame or Function.Modern.Styled[Parent] or Parent.Name == "ModernSurface" then
				return true
			end
			Parent = Parent.Parent
		end
		return Function.Modern.Styled[Obj.Parent] ~= nil
	end

	local function FlatHasLayout(Parent)
		return Parent and (Parent:FindFirstChildOfClass("UIListLayout") or Parent:FindFirstChildOfClass("UIGridLayout")
			or Parent:FindFirstChildOfClass("UITableLayout") or Parent:FindFirstChildOfClass("UIPageLayout")) ~= nil
	end

	-- degrau como irmão atrás do botão (filho sempre desenharia por cima do texto)
	local function FlatSiblingDepth(Button)
		local Theme = Function.MenuTheme
		local Px = Theme.Style.Depth or 0
		local Parent = Button.Parent
		if Px <= 0 or not Parent or FlatHasLayout(Parent) or Parent:IsA("ScrollingFrame") then return end
		local Base = Instance.new("Frame")
		Base.Name = "FlatDepth"
		Base.BorderSizePixel = 0
		Base.Active = false
		Base.BackgroundColor3 = Theme.Edge
		local BaseCorner = Instance.new("UICorner")
		BaseCorner.Parent = Base
		local function Sync()
			if not Button.Parent then Base:Destroy() return end
			Base.Parent = Button.Parent
			Base.AnchorPoint = Button.AnchorPoint
			Base.Size = Button.Size
			Base.Position = Button.Position + UDim2.fromOffset(0, Px)
			Base.ZIndex = Button.ZIndex - 1
			Base.Visible = Button.Visible and Button.BackgroundTransparency < 0.95
			Base.LayoutOrder = Button.LayoutOrder
			local C = Button:FindFirstChildOfClass("UICorner")
			BaseCorner.CornerRadius = C and C.CornerRadius or UDim.new(0, 8)
		end
		Sync()
		for _, Prop in ipairs({"Position", "Size", "AnchorPoint", "Visible", "ZIndex", "BackgroundTransparency", "Parent"}) do
			table.insert(AllConnect, Button:GetPropertyChangedSignal(Prop):Connect(Sync))
		end
		Button.Destroying:Connect(function() Base:Destroy() end)
	end

	function Function.FlatStyleObject(Obj)
		if not Obj:IsA("GuiObject") or FlatSkip(Obj) then return end
		local Theme = Function.MenuTheme
		local St = Theme.Style
		local IsText = Obj:IsA("TextButton") or Obj:IsA("TextBox") or Obj:IsA("TextLabel")
		if not IsText then return end
		Obj:SetAttribute("Flat3D", true)

		if FlatFontBold[Obj.Font] then
			Obj.Font = Obj:IsA("TextLabel") and Enum.Font.GothamMedium or Enum.Font.GothamBold
			if Obj.TextStrokeTransparency < 1 and Obj.TextStrokeColor3 == Color3.new(1, 1, 1) then
				Obj.TextStrokeTransparency = 1
			end
		end
		if Obj:IsA("TextLabel") or Obj.BackgroundTransparency >= 0.95 then return end

		Function.ModernCorner(Obj, Obj:FindFirstChildOfClass("UICorner") and Obj:FindFirstChildOfClass("UICorner").CornerRadius or UDim.new(0, 8))
		local Stroke = Obj:FindFirstChildOfClass("UIStroke")
		if not Stroke then
			Stroke = Instance.new("UIStroke")
			Stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
			Stroke.Color = Theme.Accent
			Stroke.Thickness = 1
			Stroke.Transparency = St.StrokeRest
			Stroke.Parent = Obj
		end

		if Obj:IsA("TextButton") then
			-- botão sem texto = amostra de cor/ícone: sem sombreado pra não alterar a cor mostrada
			if Obj.Text ~= "" and not Obj:FindFirstChildOfClass("UIGradient") then
				local Shade = Instance.new("UIGradient")
				Shade.Name = "ModernShade"
				Shade.Color = ColorSequence.new(St.ShadeTop, St.ShadeBottom)
				Shade.Rotation = 90
				Shade.Parent = Obj
			end
			FlatSiblingDepth(Obj)
		end
	end

	function Function.FlatSweep(Root)
		if not Root then return end
		for _, Obj in ipairs(Root:GetDescendants()) do
			Function.FlatStyleObject(Obj)
		end
		if Root:GetAttribute("FlatWatch") then return end
		Root:SetAttribute("FlatWatch", true)
		table.insert(AllConnect, Root.DescendantAdded:Connect(function(Obj)
			task.defer(function()
				if Obj.Parent then Function.FlatStyleObject(Obj) end
			end)
		end))
	end

	function Function.ApplyFlatEverywhere()
		Function.FlatCard(GUIObject.BundleFrame)
		for _, Root in ipairs({GUIObject.Menu, GUIObject.Bundles, GUIObject.RecolorFrame, GUIObject.Catalog_3}) do
			local Ok, Err = pcall(Function.FlatSweep, Root)
			if not Ok then warn("[RoC] 3D Flat geral:", Root and Root.Name, Err) end
		end
	end

	-- parte estrutural do 3D Flat (relevo, raios, contornos): botões/cartões e a janela
	function Function.ApplyFlatStyle()
		local Theme = Function.MenuTheme
		local St = Theme.Style

		-- aba Menu: cartões de texto fixo (Bundle: X) e cabeçalho fora da fonte Code
		if GUIObject.Menu then
			for _, Obj in ipairs(GUIObject.Menu:GetChildren()) do
				if Obj:IsA("Frame") and not Function.Modern.Styled[Obj] then
					Function.FlatCard(Obj)
				end
			end
		end
		if GUIObject.NameText then GUIObject.NameText.Font = Enum.Font.GothamBold end
		if GUIObject.VersionText then GUIObject.VersionText.Font = Enum.Font.GothamMedium end

		for Obj in pairs(Function.Modern.Styled) do
			if typeof(Obj) == "Instance" and Obj.Parent and Obj:IsA("Frame") then
				local Surface = Obj:FindFirstChild("ModernSurface")
				if Surface then
					local IsTab = Obj.Parent == GUIObject.ButtonFrame
					local Radius = UDim.new(0, IsTab and St.TabRadius or St.Radius)
					Function.ModernCorner(Obj, Radius)
					Function.ModernCorner(Surface, Radius)
					local Shade = Surface:FindFirstChild("ModernShade")
					if Shade then
						Shade.Color = ColorSequence.new(St.ShadeTop, St.ShadeBottom)
					end
					local Stroke = Obj:FindFirstChild("ModernStroke")
					if Stroke and not Obj:GetAttribute("ModernSelected") then
						Stroke.Transparency = St.StrokeRest
					end
					Function.ModernDepthSync(Obj)
				end
			end
		end

		local Page = GUIObject.PageFrame
		if Page then
			local PageStroke = Page:FindFirstChildOfClass("UIStroke")
			if PageStroke then
				PageStroke.Thickness = St.PageStroke
				PageStroke.Transparency = St.PageStrokeT
			end
			local Mirror = GUIObject.CharacterPreviewFrame
			local MirrorStroke = Mirror and Mirror:FindFirstChildOfClass("UIStroke")
			if MirrorStroke then
				MirrorStroke.Thickness = St.PageStroke
				MirrorStroke.Transparency = St.PageStrokeT
			end

			-- "degrau" 3D da janela
			local Holder = Page.Parent
			if Holder then
				local Base = Holder:FindFirstChild("ModernWindowDepth")
				if St.WindowDepth > 0 then
					if not Base then
						Base = Instance.new("Frame")
						Base.Name = "ModernWindowDepth"
						Base.BorderSizePixel = 0
						Base.Active = false
						local Corner = Instance.new("UICorner")
						Corner.Parent = Base
						Base.Parent = Holder
					end
					Base.Visible = true
					Base.AnchorPoint = Page.AnchorPoint
					Base.Size = Page.Size
					Base.Position = Page.Position + UDim2.fromOffset(0, St.WindowDepth)
					Base.ZIndex = Page.ZIndex - 1
					Base.BackgroundColor3 = Theme.Edge
					Base.BackgroundTransparency = 0
					local PageCorner = Page:FindFirstChildOfClass("UICorner")
					local BaseCorner = Base:FindFirstChildOfClass("UICorner")
					if PageCorner and BaseCorner then
						BaseCorner.CornerRadius = PageCorner.CornerRadius
					end
				elseif Base then
					Base.Visible = false
				end
			end

			-- "degrau" 3D do espelho
			local Mirror2 = GUIObject.CharacterPreviewFrame
			if Mirror2 and Mirror2.Parent then
				local MBase = Mirror2.Parent:FindFirstChild("MirrorWindowDepth")
				if St.WindowDepth > 0 then
					if not MBase then
						MBase = Instance.new("Frame")
						MBase.Name = "MirrorWindowDepth"
						MBase.BorderSizePixel = 0
						MBase.Active = false
						Instance.new("UICorner", MBase)
						MBase.Parent = Mirror2.Parent
					end
					MBase.Visible = true
					MBase.AnchorPoint = Mirror2.AnchorPoint
					MBase.Size = Mirror2.Size
					MBase.Position = Mirror2.Position + UDim2.fromOffset(0, St.WindowDepth)
					MBase.ZIndex = Mirror2.ZIndex - 1
					MBase.BackgroundColor3 = Theme.Edge
					MBase.BackgroundTransparency = 0
					local MirrorCorner = Mirror2:FindFirstChildOfClass("UICorner")
					local MBaseCorner = MBase:FindFirstChildOfClass("UICorner")
					if MirrorCorner and MBaseCorner then
						MBaseCorner.CornerRadius = MirrorCorner.CornerRadius
					end
				elseif MBase then
					MBase.Visible = false
				end
			end
		end
	end

	-- ====================================================================================
