	-- ====================================================================================
	Function.TypePicker = {Token = 0, Gui = nil, Conn = nil}

	Function.TypePicker.Categories = {
		Breasts = {Key = "BreastsType", Max = MaxBreastsType, Title = "BREASTS SET", Focus = Vector3.new(0, 0.7, -0.5), Dist = 4.6, Height = 0.4, Side = -1},
		Torso = {Key = "TorsoType", Max = MaxTorsoType, Title = "TORSO SET", Focus = Vector3.new(0, 0.3, 0), Dist = 6.6, Height = 0.6, Side = -1},
		Arm = {Key = "ArmType", Max = MaxArmType, Title = "ARM SET", Focus = Vector3.new(0, 0.2, 0), Dist = 8.4, Height = 0.6, Side = -1},
		Legs = {Key = "LegsType", Max = MaxLegsType, Title = "LEGS SET", Focus = Vector3.new(0, -2, 0), Dist = 7.2, Height = 0.6, Side = -1},
		Butt = {Key = "ButtType", Max = MaxButtType, Title = "BUTT SET", Focus = Vector3.new(0, -1, 0.3), Dist = 5.4, Height = 0.6, Side = 1},
	}

	-- ====================== NOMES DAS OPÇÕES (edite aqui) ======================
	-- Quem não tiver nome aqui aparece como "Type N".
	Function.TypePicker.Names = {
		Breasts = {[1] = "Default", [6] = "VNS (static)"},
		Torso = {[1] = "Default", [3] = "Rudolph", [5] = "Roblox", [6] = "Buff", [9] = "VNS (static)"},
		Arm = {[1] = "Default", [2] = "Rudolph", [3] = "Roblox", [4] = "Buff", [5] = "VNS (static)"},
		Legs = {[1] = "Default", [2] = "Thicc", [3] = "Rudolph", [4] = "Roblox", [8] = "VNS (static)"},
		Butt = {[1] = "Default", [3] = "Thicc", [6] = "VNS (static)"},
	}

	function Function.TypePicker.NameOf(Category, N)
		local List = Function.TypePicker.Names[Category]
		return (List and List[N]) or ("Type " .. tostring(N))
	end

	-- [DripSync port] tipo escondido: sem dados no arquivo, ou VNS sem os .mesh no workspace
	function Function.TypePicker.IsAvailable(Category, N)
		if Function.TypesNoData[Category] and Function.TypesNoData[Category][N] then
			return false
		end
		return Function.VnsPresent(Category, N)
	end

	function Function.TypePicker.CountAvailable(Category)
		local Count = 0
		for I = 1, Function.TypePicker.Categories[Category].Max do
			if Function.TypePicker.IsAvailable(Category, I) then
				Count += 1
			end
		end
		return math.max(Count, 1)
	end

	-- nomes das partes (dentro do PartList) que formam cada Set
	function Function.TypePicker.PartNames(Category, N)
		local CatInfo = Function.TypePicker.Categories[Category]
		if CatInfo and CatInfo.Group then
			return Function.BodyGenitalParts(CatInfo.Group, N)
		end
		if Category == "Breasts" then
			local Sets = {
				[1] = {"Left Breast", "Right Breast", "Left Nipple", "Right Nipple"},
				[2] = {"Left Breast Type 2", "Right Breast Type 2"},
				[3] = {"Left Breast Type 3", "Right Breast Type 3", "Left Nipple Type 3", "Right Nipple Type 3"},
				[4] = {"Left Breast Type 4", "Right Breast Type 4", "Left Areola Type 4", "Right Areola Type 4", "Left Nipple Type 4", "Right Nipple Type 4"},
				[5] = {"Left Breast Type 5", "Right Breast Type 5", "Left Nipple Type 5", "Right Nipple Type 5"},
				[6] = {"Left Breast SB1", "Right Breast SB1", "Left Nipple SB1", "Right Nipple SB1"},
			}
			return Sets[N] or {}
		elseif Category == "Torso" then
			return {N == 1 and "Torso" or ("Torso" .. N)}
		end

		if Category == "Butt" and N == 6 then
			return {"Left Butt SB1", "Right Butt SB1"}
		end

		local Side = ({Arm = "Arm", Legs = "Leg", Butt = "Butt"})[Category]
		local Suffix = N == 1 and "" or tostring(N)
		return {"Left " .. Side .. Suffix, "Right " .. Side .. Suffix}
	end

	-- pega o personagem real de quem está selecionado
	function Function.TypePicker.GetCharacter()
		local Plr = game:GetService("Players"):FindFirstChild(SelectPlayer)
		local Char = Plr and Plr.Character
		if typeof(Char) == "Instance" and Char.Parent then
			return Char
		end
		local Data = PlayerData[SelectPlayer]
		Char = Data and Data.Character
		if typeof(Char) == "Instance" then
			return Char
		end
		return nil
	end

	function Function.TypePicker.SkinColor()
		return Function.TypePicker.LimbColors().Torso or Color3.fromRGB(234, 184, 146)
	end

	-- cor real de cada membro do seu boneco (R6 ou R15)
	function Function.TypePicker.LimbColors()
		local Colors = {}
		local Char = Function.TypePicker.GetCharacter()
		if not Char then return Colors end
		local Map = {
			["Torso"] = {"Torso", "UpperTorso"},
			["Head"] = {"Head"},
			["Left Arm"] = {"Left Arm", "LeftUpperArm"},
			["Right Arm"] = {"Right Arm", "RightUpperArm"},
			["Left Leg"] = {"Left Leg", "LeftUpperLeg"},
			["Right Leg"] = {"Right Leg", "RightUpperLeg"},
		}
		for Name, Options in pairs(Map) do
			for _, Opt in ipairs(Options) do
				local Part = Char:FindFirstChild(Opt)
				if Part and Part:IsA("BasePart") then
					Colors[Name] = Part.Color
					break
				end
			end
		end
		return Colors
	end

	-- remove só o que é lixo (scripts, welds, sons...) e mantém bones/FaceControls/SurfaceAppearance
	-- (necessários pra cabeça dinâmica e roupas em camadas renderizarem certo)
	function Function.TypePicker.CleanClone(Obj)
		for _, C in ipairs(Obj:GetDescendants()) do
			if C:IsA("LuaSourceContainer") or C:IsA("JointInstance") or C:IsA("WeldConstraint")
				or C:IsA("Sound") or C:IsA("ParticleEmitter") or C:IsA("Light")
				or C:IsA("BodyMover") or C:IsA("Constraint") or C:IsA("Humanoid") then
				C:Destroy()
			end
		end
		Obj.Anchored = true
		Obj.CanCollide = false
		Obj.CanQuery = false
		Obj.CanTouch = false
	end

	-- clona a cabeça (com rosto) e os acessórios de cabeça do seu boneco
	function Function.TypePicker.CloneHeadAndHats(Model)
		local Char = Function.TypePicker.GetCharacter()
		local Head = Char and Char:FindFirstChild("Head")
		if not (Head and Head:IsA("BasePart")) then return false end

		local ok, HeadClone = pcall(function() return Head:Clone() end)
		if not ok or not HeadClone then return false end

		Function.TypePicker.CleanClone(HeadClone)
		HeadClone.Transparency = 0
		HeadClone.CFrame = CFrame.new(0, 1.5, 0)
		HeadClone.Parent = Model

		for _, Acc in ipairs(Char:GetChildren()) do
			if Acc:IsA("Accessory") then
				local Handle = Acc:FindFirstChild("Handle")
				local Att = Handle and Handle:FindFirstChildOfClass("Attachment")
				local HeadAtt = Att and Head:FindFirstChild(Att.Name)
				if Handle and HeadAtt and HeadAtt:IsA("Attachment") and Handle.Transparency < 1 then
					local ok2, HandleClone = pcall(function() return Handle:Clone() end)
					if ok2 and HandleClone then
						Function.TypePicker.CleanClone(HandleClone)
						HandleClone.CFrame = HeadClone.CFrame * HeadAtt.CFrame * Att.CFrame:Inverse()
						HandleClone.Parent = Model
					end
				end
			end
		end
		return true
	end

	-- monta o boneco + o Set dentro de um ViewportFrame (pode yieldar por causa do mesh)
	function Function.TypePicker.Build(Category, N, Viewport)
		local TP = Function.TypePicker
		local Info = TP.Categories[Category]
		local List = Function.PartListDefault()
		local Data = PlayerData[SelectPlayer]
		local Colors = TP.LimbColors()
		local Skin = Colors.Torso or Color3.fromRGB(234, 184, 146)

		local Model = Instance.new("Model")
		local Base = {}

		-- Humanoid no preview (cabeça dinâmica / roupas em camadas esperam um rig)
		pcall(function()
			local Hum = Instance.new("Humanoid")
			Hum.RigType = Enum.HumanoidRigType.R6
			Hum.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
			Hum.HealthDisplayType = Enum.HumanoidHealthDisplayType.AlwaysOff
			Hum.Parent = Model
		end)
		local Built = {}

		local function Block(Name, Size, Pos, Shape)
			local P = Instance.new("Part")
			P.Name = Name
			P.Size = Size
			P.CFrame = CFrame.new(Pos)
			P.Anchored = true
			P.CanCollide = false
			P.CanQuery = false
			P.CanTouch = false
			P.Color = Colors[Name] or Skin
			P.Material = Enum.Material.SmoothPlastic
			if Shape then
				P.Shape = Shape
			end
			P.Parent = Model
			Base[Name] = P
		end

		Block("Torso", Vector3.new(2, 2, 1), Vector3.new(0, 0, 0))
		if not TP.CloneHeadAndHats(Model) then
			Block("Head", Vector3.new(1.2, 1.2, 1.2), Vector3.new(0, 1.7, 0), Enum.PartType.Ball)
		end
		Block("Left Arm", Vector3.new(1, 2, 1), Vector3.new(-1.5, 0, 0))
		Block("Right Arm", Vector3.new(1, 2, 1), Vector3.new(1.5, 0, 0))
		Block("Left Leg", Vector3.new(1, 2, 1), Vector3.new(-0.5, -2, 0))
		Block("Right Leg", Vector3.new(1, 2, 1), Vector3.new(0.5, -2, 0))

		-- contexto (os outros Sets atuais do corpo) + o Set que está sendo previsto
		local Names = {}
		local function Add(C, T)
			for _, Nm in ipairs(TP.PartNames(C, T)) do
				table.insert(Names, Nm)
			end
		end
		for _, C in ipairs({"Torso", "Arm", "Legs"}) do
			if C ~= Category then
				Add(C, (Data and Data[TP.Categories[C].Key]) or 1)
			end
		end
		Add(Category, N)
		if Info.Under then
			for _, UnderGroup in ipairs(Info.Under) do
				Add(UnderGroup, Function.BodyGenitalCurrent(UnderGroup))
			end
		end

		for _, Nm in ipairs(Names) do
			local D = List[Nm]
			if D and D.Parent then
				local Chain = D.Parent
				local ParentName = Chain[#Chain]
				local ParentPart = Built[ParentName] or Base[ParentName]

				if ParentPart then
					local Size = D.Size
					if typeof(Size) == "string" then
						local Off = Size == "Overlay" and 0.003 or -0.003
						Size = ParentPart.Size + Vector3.new(Off, Off, Off)
					end

					local Obj
					if D.Instance == "Mesh" then
						local Id = D.MeshId
						if Id == "Parent" then
							Id = ParentPart:IsA("MeshPart") and ParentPart.MeshId or nil
						end
						if Id then
							local ok, Mesh = pcall(CreateMeshPartAsync, Id, Enum.CollisionFidelity.Box, Enum.RenderFidelity.Performance)
							if ok and typeof(Mesh) == "Instance" then
								Obj = Mesh
								if typeof(D.TextureId) == "string" and D.TextureId ~= "" then
									pcall(function() Obj.TextureID = D.TextureId end)
								end
								if D.DoubleSided then
									pcall(function() Obj.DoubleSided = true end)
								end
							end
						end
					else
						Obj = Instance.new("Part")
						if D.Shape then
							Obj.Shape = D.Shape
						end
					end

					if Obj then
						Obj.Name = D.Name or Nm
						Obj.Anchored = true
						Obj.CanCollide = false
						Obj.CanQuery = false
						Obj.CanTouch = false
						Obj.Size = Size
						Obj.Material = D.Material or Enum.Material.SmoothPlastic
						Obj.Transparency = D.Transparency or 0

						local Color = Skin
						local Col = D.Color
						if Col then
							if Col.Color == "Parent" then
								Color = ParentPart.Color
							elseif typeof(Col.Color) == "Color3" then
								Color = Col.Color
							end
							if Col.Tone == "Darker" or Col.Tone == "Darker2" then
								local Percent = Col.Tone == "Darker" and DarkerColorPercentage or (Darker2ColorPercentage or 30)
								local H, S, V = Color:ToHSV()
								Color = Color3.fromHSV(H, S, V + (-Percent * V / 100))
							end
						end
						Obj.Color = Color

						Obj.CFrame = ParentPart.CFrame * (D.CFrame or CFrame.new()) * (D.CFrame1 or CFrame.new()):Inverse()
						Obj.Parent = ParentPart

						if D.ParentTransparency ~= nil and Base[ParentName] then
							Base[ParentName].Transparency = D.ParentTransparency
						end

						-- só roda as funções que criam a malha (SpecialMesh), com escala neutra
						local Fn = D.Function
						local Fns = typeof(Fn) == "table" and Fn or {Fn}
						for _, FnName in ipairs(Fns) do
							if typeof(FnName) == "string" and string.find(FnName, "Mesh$") and Function[FnName] then
								local OldScale = Data and Data.BreastsScale
								if Data then
									Data.BreastsScale = 1
								end
								pcall(Function[FnName], Obj, nil, nil, SelectPlayer)
								if Data then
									Data.BreastsScale = OldScale
								end
							end
						end

						Built[Obj.Name] = Obj
					end
				end
			end
		end

		-- pernas semi transparentes (Info.GhostLegs): o Pussy fica entre as pernas e elas escondiam o resultado
		if Info.GhostLegs then
			local GhostAlpha = 0.65
			for _, LegName in ipairs({"Left Leg", "Right Leg"}) do
				local Leg = Base[LegName]
				if Leg then
					Leg.Transparency = math.max(Leg.Transparency, GhostAlpha)
					for _, Child in ipairs(Leg:GetDescendants()) do
						if Child:IsA("BasePart") then
							Child.Transparency = math.max(Child.Transparency, GhostAlpha)
						end
					end
				end
			end
		end

		local Cam = Instance.new("Camera")
		Cam.FieldOfView = 38
		Viewport.CurrentCamera = Cam
		Cam.Parent = Viewport
		Model.Parent = Viewport

		return Model, Cam
	end

	function Function.TypePicker.Orbit(Card, Angle)
		if not Card.Cam then return end
		local Info = Card.Info
		local Offset = CFrame.Angles(0, Angle, 0) * Vector3.new(0, Info.Height, Info.Side * Info.Dist)
		Card.Cam.CFrame = CFrame.lookAt(Info.Focus + Offset, Info.Focus)
	end

	function Function.TypePicker.Close(Instant)
		local TP = Function.TypePicker
		TP.Token += 1

		if TP.Conn then
			TP.Conn:Disconnect()
			TP.Conn = nil
		end

		local Gui = TP.Gui
		TP.Gui = nil
		if Gui and Gui.Root and Gui.Root.Parent then
			if Instant then
				Gui.Root:Destroy()
			else
				Gui.Root.Active = false
				TS:Create(Gui.Scale, TweenInfo.new(0.12, Enum.EasingStyle.Quad, Enum.EasingDirection.In), {Scale = 0.9}):Play()
				TS:Create(Gui.Root, TweenInfo.new(0.12), {BackgroundTransparency = 1}):Play()
				task.delay(0.13, function()
					if Gui.Root then
						Gui.Root:Destroy()
					end
				end)
			end
		end
	end

	function Function.TypePicker.Open(Category)
		local TP = Function.TypePicker
		local Info = TP.Categories[Category]
		if not Info or not GUIObject.Screen.Parent then return end

		TP.Close(true)
		local Token = TP.Token

		local Theme = Function.MenuTheme
		local Data = PlayerData[SelectPlayer]
		local Current = (Info.Group and Function.BodyGenitalCurrent(Info.Group)) or (Data and Data[Info.Key]) or 1

		local function New(Class, Props, Parent)
			local Obj = Instance.new(Class)
			for k, v in pairs(Props) do
				Obj[k] = v
			end
			Obj.Parent = Parent
			return Obj
		end

		-- fundo escurecido (clicar fora fecha)
		local Root = New("TextButton", {
			Name = "TypePicker",
			Size = UDim2.fromScale(1, 1),
			BackgroundColor3 = Color3.new(0, 0, 0),
			BackgroundTransparency = 0.6,
			BorderSizePixel = 0,
			Text = "",
			AutoButtonColor = false,
			Active = true,
			ZIndex = 800,
		}, GUIObject.Screen)

		local Cols = 3
		local CellW, CellH, Gap, Pad = 108, 132, 8, 10
		local Rows = math.ceil(TP.CountAvailable(Category) / Cols)
		local Width = Cols * CellW + (Cols - 1) * Gap + Pad * 2 + 8
		local Height = 50 + Rows * CellH + (Rows - 1) * Gap + Pad * 2
		-- [v26 scroll] cap: máximo 2 linhas visíveis; com 3+ types o scroll aparece
		local MaxH = 50 + 2 * CellH + 1 * Gap + Pad * 2
		local Limit = math.floor(Root.AbsoluteSize.Y * 0.9)
		if Limit > 0 then
			Height = math.min(Height, math.min(MaxH, Limit))
		end

		-- abre ao lado do menu principal; se não couber, centraliza
		local PosX, PosY = 0.5, 0.5
		local OffX, OffY = 0, 0
		local Main = GUIObject.MainFrame
		if Main and Main.Parent and Root.AbsoluteSize.X > 0 then
			local Wanted = (Main.AbsolutePosition.X - Root.AbsolutePosition.X) - Width / 2 - 10
			if Wanted - Width / 2 >= 8 then
				PosX, OffX = 0, Wanted
				local MidY = (Main.AbsolutePosition.Y - Root.AbsolutePosition.Y) + Main.AbsoluteSize.Y / 2
				local MinY, MaxY = Height / 2 + 8, Root.AbsoluteSize.Y - Height / 2 - 8
				PosY, OffY = 0, math.clamp(MidY, MinY, math.max(MinY, MaxY))
			end
		end

		local Panel = New("Frame", {
			Name = "Panel",
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.new(PosX, OffX, PosY, OffY),
			Size = UDim2.fromOffset(Width, Height),
			BackgroundColor3 = Theme.Panel,
			BorderSizePixel = 0,
			Active = true,
			ZIndex = 801,
		}, Root)
		New("UICorner", {CornerRadius = UDim.new(0, 12)}, Panel)
		New("UIStroke", {Color = Theme.Accent, Thickness = 1.5, Transparency = 0.2}, Panel)
		New("UIGradient", {
			Rotation = 90,
			Color = ColorSequence.new(Theme.Categories.neutral.B, Theme.Deep),
		}, Panel)
		local Scale = New("UIScale", {Scale = 0.9}, Panel)

		New("TextLabel", {
			Name = "Title",
			Position = UDim2.fromOffset(14, 6),
			Size = UDim2.new(1, -60, 0, 24),
			BackgroundTransparency = 1,
			Font = Enum.Font.Code,
			Text = Info.Title,
			TextColor3 = Theme.Mint,
			TextSize = 17,
			TextXAlignment = Enum.TextXAlignment.Left,
			ZIndex = 802,
		}, Panel)
		New("TextLabel", {
			Name = "Sub",
			Position = UDim2.fromOffset(14, 28),
			Size = UDim2.new(1, -60, 0, 16),
			BackgroundTransparency = 1,
			Font = Enum.Font.Code,
			Text = "Tap a preview to equip  (hover = rotate)",
			TextColor3 = Theme.Soft,
			TextSize = 11,
			TextXAlignment = Enum.TextXAlignment.Left,
			ZIndex = 802,
		}, Panel)

		local CloseBtn = New("TextButton", {
			Name = "Close",
			AnchorPoint = Vector2.new(1, 0),
			Position = UDim2.new(1, -10, 0, 10),
			Size = UDim2.fromOffset(28, 28),
			BackgroundColor3 = Theme.Deep,
			AutoButtonColor = false,
			Font = Enum.Font.Code,
			Text = "X",
			TextColor3 = Theme.Danger,
			TextSize = 14,
			ZIndex = 803,
		}, Panel)
		New("UICorner", {CornerRadius = UDim.new(0, 8)}, CloseBtn)
		local CloseStroke = New("UIStroke", {Color = Theme.Danger, Thickness = 1.2, Transparency = 0.5}, CloseBtn)
		CloseBtn.MouseEnter:Connect(function() CloseStroke.Transparency = 0 end)
		CloseBtn.MouseLeave:Connect(function() CloseStroke.Transparency = 0.5 end)
		CloseBtn.Activated:Connect(function() TP.Close() end)

		local Scroll = New("ScrollingFrame", {
			Name = "Sets",
			Position = UDim2.fromOffset(0, 50),
			Size = UDim2.new(1, 0, 1, -50),
			BackgroundTransparency = 1,
			BorderSizePixel = 0,
			-- [v26 scroll] barra mais grossa e visível; elastic = bounce no topo/fundo
			ScrollBarThickness = 6,
			ScrollBarImageColor3 = Theme.Accent,
			TopImage = "rbxasset://textures/ui/Scroll/scroll-middle.png",
			MidImage = "rbxasset://textures/ui/Scroll/scroll-middle.png",
			BottomImage = "rbxasset://textures/ui/Scroll/scroll-middle.png",
			ElasticBehavior = Enum.ElasticBehavior.WhenScrollable,
			CanvasSize = UDim2.new(),
			AutomaticCanvasSize = Enum.AutomaticSize.Y,
			ScrollingDirection = Enum.ScrollingDirection.Y,
			ZIndex = 802,
		}, Panel)
		-- [v26 scroll] fade gradient no fundo: indica visualmente que tem mais conteúdo
		local FadeGrad = New("Frame", {
			Name = "ScrollFade",
			AnchorPoint = Vector2.new(0, 1),
			Position = UDim2.new(0, 0, 1, 0),
			Size = UDim2.new(1, -8, 0, 32),
			BackgroundColor3 = Theme.Panel,
			BackgroundTransparency = 0,
			BorderSizePixel = 0,
			ZIndex = 820,
			Active = false,
			ClipsDescendants = false,
		}, Panel)
		New("UIGradient", {
			Rotation = 90,
			Transparency = NumberSequence.new({
				NumberSequenceKeypoint.new(0, 1),
				NumberSequenceKeypoint.new(1, 0),
			}),
		}, FadeGrad)
		-- oculta o fade quando o scroll chegou ao fundo
		Scroll:GetPropertyChangedSignal("CanvasPosition"):Connect(function()
			local MaxScroll = Scroll.AbsoluteCanvasSize.Y - Scroll.AbsoluteSize.Y
			FadeGrad.Visible = MaxScroll > 4 and Scroll.CanvasPosition.Y < MaxScroll - 4
		end)
		Scroll:GetPropertyChangedSignal("AbsoluteCanvasSize"):Connect(function()
			local MaxScroll = Scroll.AbsoluteCanvasSize.Y - Scroll.AbsoluteSize.Y
			FadeGrad.Visible = MaxScroll > 4
		end)
		New("UIPadding", {
			PaddingLeft = UDim.new(0, Pad), PaddingRight = UDim.new(0, Pad + 6), -- [v26 scroll] +6 = largura da scrollbar
			PaddingTop = UDim.new(0, 2), PaddingBottom = UDim.new(0, Pad),
		}, Scroll)
		New("UIGridLayout", {
			CellSize = UDim2.fromOffset(CellW, CellH),
			CellPadding = UDim2.fromOffset(Gap, Gap),
			SortOrder = Enum.SortOrder.LayoutOrder,
		}, Scroll)

		local Cards = {}
		for I = 1, Info.Max do
			if not TP.IsAvailable(Category, I) and I ~= Current then
				continue
			end
			local Selected = I == Current

			local CardBtn = New("TextButton", {
				Name = "Set" .. I,
				LayoutOrder = I,
				BackgroundColor3 = Theme.Deep,
				BorderSizePixel = 0,
				AutoButtonColor = false,
				Text = "",
				ClipsDescendants = true,
				ZIndex = 803,
			}, Scroll)
			New("UICorner", {CornerRadius = UDim.new(0, 8)}, CardBtn)
			local Stroke = New("UIStroke", {
				Color = Selected and Theme.Mint or Theme.Accent,
				Thickness = Selected and 2.5 or 1.5,
				Transparency = Selected and 0 or 0.45,
			}, CardBtn)

			local View = New("ViewportFrame", {
				Name = "Preview",
				Position = UDim2.fromOffset(4, 4),
				Size = UDim2.new(1, -8, 0, 96),
				BackgroundColor3 = Color3.fromRGB(10, 18, 34),
				BorderSizePixel = 0,
				Ambient = Color3.fromRGB(190, 190, 200),
				LightColor = Color3.fromRGB(255, 255, 255),
				LightDirection = Vector3.new(-0.4, -0.7, 0.6),
				ZIndex = 804,
			}, CardBtn)
			New("UICorner", {CornerRadius = UDim.new(0, 6)}, View)

			local Loading = New("TextLabel", {
				Size = UDim2.fromScale(1, 1),
				BackgroundTransparency = 1,
				Font = Enum.Font.Code,
				Text = "...",
				TextColor3 = Theme.Soft,
				TextSize = 16,
				ZIndex = 806,
			}, View)

			local NameLabel = New("TextLabel", {
				Name = "NameLabel",
				Position = UDim2.new(0, 0, 0, 102),
				Size = UDim2.new(1, 0, 0, 24),
				BackgroundTransparency = 1,
				Font = Enum.Font.Code,
				Text = TP.NameOf(Category, I),
				TextScaled = true,
				TextColor3 = Selected and Theme.Mint or Color3.fromRGB(255, 255, 255),
				TextSize = 14,
				ZIndex = 805,
			}, CardBtn)
			New("UITextSizeConstraint", {MaxTextSize = 14, MinTextSize = 8}, NameLabel)

			if Selected then
				local Badge = New("TextLabel", {
					AnchorPoint = Vector2.new(1, 0),
					Position = UDim2.new(1, -8, 0, 8),
					Size = UDim2.fromOffset(46, 15),
					BackgroundColor3 = Theme.Mint,
					Font = Enum.Font.Code,
					Text = "CURRENT",
					TextColor3 = Theme.Deep,
					TextSize = 9,
					ZIndex = 807,
				}, CardBtn)
				New("UICorner", {CornerRadius = UDim.new(0, 5)}, Badge)
			end

			local Card = {Index = I, Info = Info, Button = CardBtn, View = View, Loading = Loading, Angle = 0, Hover = false, Cam = nil}
			Cards[I] = Card

			CardBtn.MouseEnter:Connect(function()
				Card.Hover = true
				if not Selected then
					TS:Create(Stroke, TweenInfo.new(0.12), {Color = Theme.Mint, Transparency = 0.05}):Play()
				end
			end)
			CardBtn.MouseLeave:Connect(function()
				Card.Hover = false
				if not Selected then
					TS:Create(Stroke, TweenInfo.new(0.12), {Color = Theme.Accent, Transparency = 0.45}):Play()
				end
			end)
			CardBtn.Activated:Connect(function()
				local PData = PlayerData[SelectPlayer]
				if Info.Group then
					if I ~= Current then -- re-clicar o atual nao reequipa (preserva recolor)
						Function.BodyGenitalSet(Info.Group, I)
					end
				elseif PData then
					PData[Info.Key] = I
					Function.GUIUpdate()
				end
				TP.Close()
			end)
		end

		-- giro suave no card sob o mouse; ao sair volta pro ângulo inicial
		TP.Conn = game:GetService("RunService").RenderStepped:Connect(function(dt)
			for _, Card in ipairs(Cards) do
				if Card.Cam then
					if Card.Hover then
						Card.Angle += dt * 1.8
						TP.Orbit(Card, Card.Angle)
					elseif Card.Angle ~= 0 then
						local A = ((Card.Angle + math.pi) % (math.pi * 2)) - math.pi
						A = A * (1 - math.min(1, dt * 8))
						Card.Angle = math.abs(A) < 0.01 and 0 or A
						TP.Orbit(Card, Card.Angle)
					end
				end
			end
		end)
		table.insert(AllConnect, TP.Conn)

		TP.Gui = {Root = Root, Panel = Panel, Scale = Scale}
		Root.Activated:Connect(function() TP.Close() end)

		TS:Create(Scale, TweenInfo.new(0.18, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Scale = 1}):Play()

		-- monta os previews um por vez (sem travar o jogo)
		task.spawn(function()
			for I = 1, Info.Max do
				if TP.Token ~= Token then return end
				local Card = Cards[I]
				if not Card then
					continue
				end
				local ok, Model, Cam = pcall(TP.Build, Category, I, Card.View)
				if TP.Token ~= Token then return end
				if ok and typeof(Model) == "Instance" then
					Card.Cam = Cam
					TP.Orbit(Card, 0)
					Card.Loading.Visible = false
				else
					Card.Loading.Text = "N/A"
				end
				task.wait()
			end
		end)
	end

	function Function.MenuCategory(Color)
		local R, G, B = Color.R * 255, Color.G * 255, Color.B * 255
		if R > G + 25 and R > B + 25 then
			return "danger"
		elseif R >= 20 and G >= 20 and B < R * 0.5 and B < G * 0.5 then
			return "amber"
		elseif G > R + 20 and G >= B then
			return "mint"
		elseif math.abs(R - G) < 12 and math.abs(G - B) < 12 then
			return "neutral"
		end
		return "accent"
	end

	-- Aplica o visual 3D Flat no menu já montado. Só mexe em aparência: nomes, posições,
	-- hierarquia e lógica continuam exatamente os mesmos que GUIFunc/GUIUpdate usam.
	function Function.ApplyMenuTheme()
		local Theme = Function.MenuTheme

		for _, Obj in ipairs(GUIObject.MainFrame:GetDescendants()) do
			if Obj:IsA("UIGradient") then
				local Keys = Obj.Color.Keypoints
				local First, Last = Keys[1].Value, Keys[#Keys].Value
				local Owner = Obj.Parent
				local Stroke = Owner and Owner:FindFirstChildOfClass("UIStroke")
				if Owner == GUIObject.PageFrame then
					Obj.Color = ColorSequence.new(Theme.Grad, Theme.Deep)
					Obj.Rotation = 45
					if Stroke then
						Stroke.Color = Theme.Accent
						Stroke.Thickness = 2
						Stroke.Transparency = 0.25
					end
				elseif (Last.R + Last.G + Last.B) / 3 > 0.78 then
					Obj.Color = ColorSequence.new(Color3.fromRGB(168, 168, 168), Color3.fromRGB(255, 255, 255))
					if Stroke then
						Stroke.Color = Theme.Accent
						Stroke.Thickness = 1.5
						Stroke.Transparency = 0.35
					end
				else
					local Cat = Theme.Categories[Function.MenuCategory(First)]
					Obj.Color = ColorSequence.new(Cat.A, Cat.B)
					if Owner then
						Owner:SetAttribute("MenuStroke", Cat.Stroke)
						if Stroke then
							Stroke.Color = Cat.Stroke
							Stroke.Thickness = 1.5
							Stroke.Transparency = 0.35
						end
					end
				end
			elseif Obj:IsA("ScrollingFrame") then
				Obj.ScrollBarImageColor3 = Theme.Accent
			end
		end

		GUIObject.NameText.TextColor3 = Theme.Accent
		GUIObject.VersionText.TextColor3 = Theme.Soft

		-- brilho ao passar o mouse nos botões fixos do menu
		for _, Obj in ipairs(GUIObject.MainFrame:GetDescendants()) do
			if Obj:IsA("TextButton") and Obj.Parent:IsA("Frame") then
				local Stroke = Obj.Parent:FindFirstChildOfClass("UIStroke")
				if Stroke then
					table.insert(AllConnect, Obj.MouseEnter:Connect(function()
						TS:Create(Stroke, TweenInfo.new(0.15), {Transparency = 0}):Play()
					end))
					table.insert(AllConnect, Obj.MouseLeave:Connect(function()
						TS:Create(Stroke, TweenInfo.new(0.15), {Transparency = 0.35}):Play()
					end))
				end
			end
		end

		-- aba ativa (coluna de botões da direita) fica com borda verde-neon mais grossa
		local function refreshTabs()
			for _, Tab in ipairs(GUIObject.ButtonFrame:GetChildren()) do
				if Tab:IsA("Frame") then
					local Stroke = Tab:FindFirstChildOfClass("UIStroke")
					if Stroke then
						local Page = GUIObject.PageFrame:FindFirstChild(Tab.Name)
						if Page and Page.Visible then
							Stroke.Color = Theme.Mint
							Stroke.Thickness = 2.5
						else
							Stroke.Color = Tab:GetAttribute("MenuStroke") or Theme.Accent
							Stroke.Thickness = 1.5
						end
					end
				end
			end
		end
		for _, Page in ipairs(GUIObject.PageFrame:GetChildren()) do
			if Page:IsA("GuiObject") then
				table.insert(AllConnect, Page:GetPropertyChangedSignal("Visible"):Connect(refreshTabs))
			end
		end
		refreshTabs()

		-- listas criadas depois (catálogo, HP etc.) ganham a barra de rolagem no mesmo estilo
		table.insert(AllConnect, GUIObject.MainFrame.DescendantAdded:Connect(function(Obj)
			if Obj:IsA("ScrollingFrame") then
				Obj.ScrollBarImageColor3 = Theme.Accent
			end
		end))
	end

	-- // ESPELHO: preview ao vivo do boneco com as alterações, antes de executar // --
	-- Roda o CharacterExecute do próprio script num boneco separado, usando uma CÓPIA isolada das
	-- configurações (chave "RoCMirror"). O avatar real e PlayerData[SelectPlayer] não são alterados.
	Function.MirrorKey = "RoCMirror"
	Function.MirrorState = {Busy = false, Pending = false, Last = nil, Settling = false, Dummy = nil}
	Function.MirrorRuntimeKeys = {
		Character = true, CurrentPartList = true, Cooldown = true, updateCooldown = true,
		SavedPreviousHP = true, SavedTopHP = true, SavedBottomHP = true, Healing = true,
		HealProgress = true, TopRipped = true, BottomRipped = true, OldTransparency = true,
		OldestClothings = true, PreviousHP = true, VnsRigs = true, -- [v26] o espelho nunca pode apontar para os rigs reais do jogador
	}

	function Function.MirrorSetStatus(Text)
		local Label = Function.MirrorLabel
		if Label and Label.Parent then
			local Theme = Function.MenuTheme
			local Short, Color = Text, Theme.Soft
			if string.sub(Text, 1, 4) == "erro" then
				Short, Color = "erro", Theme.Danger
			elseif Text == "ao vivo" then
				Color = Theme.Mint
			elseif string.sub(Text, 1, 10) == "atualizand" then
				Short, Color = "atualizando", Theme.Amber
			end
			Label.Text = Short
			Label.TextColor3 = Color
			local Dot = Function.MirrorDot
			if Dot and Dot.Parent then
				Dot.BackgroundColor3 = Color
			end
		end
	end

	function Function.MirrorDeepCopy(Value, Seen)
		if type(Value) ~= "table" then
			return Value
		end
		Seen = Seen or {}
		if Seen[Value] then
			return Seen[Value]
		end
		local Copy = {}
		Seen[Value] = Copy
		for K, V in pairs(Value) do
			Copy[K] = Function.MirrorDeepCopy(V, Seen)
		end
		return Copy
	end

	function Function.MirrorSignature()
		local Source = PlayerData[SelectPlayer]
		if not Source then
			return ""
		end
		local Parts = {"Method", tostring(Method)}
		local Skip = Function.MirrorRuntimeKeys
		local function Walk(Value, Depth)
			if Depth > 6 then
				return
			end
			for K, V in pairs(Value) do
				if not (Depth == 0 and Skip[K]) then
					Parts[#Parts + 1] = tostring(K)
					if type(V) == "table" then
						Walk(V, Depth + 1)
					else
						Parts[#Parts + 1] = tostring(V)
					end
				end
			end
		end
		Walk(Source, 0)
		return table.concat(Parts, "|")
	end

	function Function.MirrorBuild()
		local Key = Function.MirrorKey
		local Source = PlayerData[SelectPlayer]
		if not Source then
			return
		end

		local Old = PlayerData[Key]
		if Old and Old.CurrentPartList and Old.CurrentPartList.CurrentConnections then
			for _, Conn in pairs(Old.CurrentPartList.CurrentConnections) do
				if typeof(Conn) == "RBXScriptConnection" then
					Conn:Disconnect()
				end
			end
		end
		GUIObject.ViewportFrame:ClearAllChildren()
		if Method2CharacterFolder then
			local OldModel = Method2CharacterFolder:FindFirstChild(Key)
			if OldModel then
				OldModel:Destroy()
			end
		end

		local Data = Function.PlayerDataDefault()
		for K, V in pairs(Source) do
			if not Function.MirrorRuntimeKeys[K] then
				Data[K] = Function.MirrorDeepCopy(V)
			end
		end
		Data.AutoExecute = false
		Data.FPerson = false
		Data.FPsnap = false
		Data.HeadTracking = false
		Data.HardcoreHP = false
		Data.TopHP = ""
		Data.BottomHP = ""
		Data.ClothesHP = {}
		Data.LinkedHeal = false
		PlayerData[Key] = Data

		local Dummy = Function.Dummy()
		Function.MirrorState.Dummy = Dummy

		local Owner = PS:FindFirstChild(SelectPlayer)
		local OwnerCharacter = Owner and Owner.Character
		if OwnerCharacter then
			for _, v in pairs(OwnerCharacter:GetChildren()) do
				if v:IsA("Shirt") or v:IsA("Pants") or v:IsA("ShirtGraphic") or v:IsA("Accessory") or v:IsA("BodyColors") then
					local cv = v:Clone()
					cv.Parent = Dummy
					if cv:IsA("Accessory") then
						local Handle = cv:FindFirstChildOfClass("Part") or v:FindFirstChildOfClass("MeshPart")
						if Handle then
							local Weld = Handle:FindFirstChildOfClass("Weld")
							if Weld and Weld.Part0 then
								Weld.Part0 = Dummy:FindFirstChild(Weld.Part0.Name)
							end
						end
					end
				elseif v:IsA("Part") then
					local Base = Dummy:FindFirstChild(v.Name)
					if Base then
						Base.Color = v.Color
					end
				end
			end
		end

		-- Dummy vai pro Workspace (Method 2 precisa de CFrame real para os welds),
		-- mas teleportado pra fora do mapa pra não aparecer na cena do jogador.
		local DummyRoot = Dummy:FindFirstChild("HumanoidRootPart") or Dummy:FindFirstChildOfClass("Part")
		if DummyRoot then
			DummyRoot.CFrame = CFrame.new(0, -10000, 0)
		end
		Dummy.Parent = game.Workspace
		local ExecOk, ExecErr = pcall(Function.CharacterExecute, Dummy, Key)
		task.wait()

		if not ExecOk then
			if Dummy and Dummy.Parent then
				Dummy:Destroy()
			end
			Function.MirrorState.Dummy = nil
			error(ExecErr, 0)
		end

		-- Method 2 gera as malhas num modelo separado dentro de Method2CharacterFolder
		local Generated = Method2CharacterFolder and Method2CharacterFolder:FindFirstChild(Key)
		if Generated then
			Generated.Parent = GUIObject.ViewportFrame
		end
		Dummy.Parent = GUIObject.ViewportFrame
		Function.MirrorState.Dummy = nil
	end

	function Function.MirrorRefresh()
		local State = Function.MirrorState
		if State.Busy then
			State.Pending = true
			return
		end
		State.Busy = true
		Function.MirrorSetStatus("atualizando...")
		local Ok, Err = pcall(Function.MirrorBuild)
		if not Ok then
			warn("[RoC] espelho:", Err)
			if State.Dummy and State.Dummy.Parent then
				State.Dummy:Destroy()
			end
			State.Dummy = nil
			Function.MirrorSetStatus("erro (veja o Output)")
		else
			Function.MirrorSetStatus("ao vivo")
		end
		State.Busy = false
		if State.Pending then
			State.Pending = false
			task.defer(Function.MirrorRefresh)
		end
	end

	function Function.MirrorTick()
		local State = Function.MirrorState
		if not GUIObject.Screen.Enabled then
			return
		end
		local Sig = Function.MirrorSignature()
		if Sig ~= State.Last then
			State.Last = Sig
			State.Settling = true
		elseif State.Settling then
			-- [RoC fix] no maximo uma reconstrucao do espelho a cada 2s (cada uma roda o CharacterExecute inteiro)
			if os.clock() - (State.LastBuildAt or 0) < 2 then
				return
			end
			State.LastBuildAt = os.clock()
			State.Settling = false
			Function.MirrorRefresh()
		end
	end

	function Function.MirrorStart()
		task.spawn(function()
			while GUIObject.Screen.Parent do
				task.wait(0.3)
				local Ok, Err = pcall(Function.MirrorTick)
				if not Ok then
					warn("[RoC] espelho (tick):", Err)
				end
			end
		end)
	end

	-- ===================================================================================== --
	-- // ANIMAÇÕES // --
	-- 1) abrir/fechar o menu: "pula" do centro (escala 0.9 -> 1) com fade; some do mesmo jeito
	-- 2) troca de aba: a página nova entra deslizando ~20px da direita com fade
	-- 3) balão com o valor em cima do knob enquanto o slider é arrastado
	-- Tudo é cosmético: se algo falhar, o menu volta a abrir/fechar direto (veja SetMenu).
	-- ===================================================================================== --
	RoCLoad.Step(54, "Carregando animações")
	Function.Anim = {
		Menu = {Open = false, Session = nil},
		Pages = {},
		PageHooked = setmetatable({}, {__mode = "k"}),
		PageStopped = setmetatable({}, {__mode = "k"}),
		PageConn = nil,
		Bubble = nil,
		PivotCache = nil,
		MenuScaleFrom = 0.9,
		MenuOpenTime = 0.22,
		MenuCloseTime = 0.16,
		PageSlide = 20,
		PageTime = 0.22,
		FadeCap = 900,
	}

	-- junta as propriedades de transparência de tudo que está VISÍVEL dentro de Root.
	-- devolve nil se passar do limite (aí a animação fica só no movimento, sem fade).
	function Function.Anim.Collect(Root, Cap)
		local Entries = {}
		local Count = 0
		local Overflow = false

		local function Add(Inst, Prop)
			local Base = Inst[Prop]
			if Base >= 0.999 then return end
			Count += 1
			Entries[Count] = {Inst = Inst, Prop = Prop, Base = Base, Last = nil, Foreign = false}
		end

		local function AddGui(Inst)
			Add(Inst, "BackgroundTransparency")
			if Inst:IsA("TextLabel") or Inst:IsA("TextButton") or Inst:IsA("TextBox") then
				Add(Inst, "TextTransparency")
				Add(Inst, "TextStrokeTransparency")
			elseif Inst:IsA("ImageLabel") or Inst:IsA("ImageButton") or Inst:IsA("ViewportFrame") then
				Add(Inst, "ImageTransparency")
			elseif Inst:IsA("ScrollingFrame") then
				Add(Inst, "ScrollBarImageTransparency")
			end
		end

		local function Walk(Parent)
			for _, Child in ipairs(Parent:GetChildren()) do
				if Count > Cap then
					Overflow = true
					return
				end
				if Child:IsA("GuiObject") then
					if Child.Visible then
						AddGui(Child)
						Walk(Child)
						if Overflow then return end
					end
				elseif Child:IsA("UIStroke") then
					Add(Child, "Transparency")
				end
			end
		end

		AddGui(Root)
		Walk(Root)
		if Overflow then
			return nil
		end
		return Entries
	end

	-- Shown: 0 = invisível, 1 = como era. Se outra coisa mexer na propriedade durante a
	-- animação (ex.: tween de hover), a entrada é largada e o valor dela fica como está.
	function Function.Anim.Apply(Entries, Shown)
		local Hide = 1 - math.clamp(Shown, 0, 1)
		for i = 1, #Entries do
			local E = Entries[i]
			if not E.Foreign then
				local Inst = E.Inst
				local Current = Inst[E.Prop]
				if E.Last ~= nil and math.abs(Current - E.Last) > 0.02 then
					E.Foreign = true
				else
					local Value = E.Base + (1 - E.Base) * Hide
					E.Last = Value
					Inst[E.Prop] = Value
				end
			end
		end
	end

	function Function.Anim.Restore(Entries)
		if not Entries then return end
		for i = 1, #Entries do
			local E = Entries[i]
			if not E.Foreign and E.Last ~= nil then
				E.Inst[E.Prop] = E.Base
			end
		end
	end

	-- // MENU // --
	-- ponto central do conjunto (painel + abas + nome + espelho), relativo ao canto do MainFrame
	function Function.Anim.MenuPivot()
		local Anim = Function.Anim
		local Origin = GUIObject.MainFrame.AbsolutePosition
		local MinX, MinY, MaxX, MaxY = math.huge, math.huge, -math.huge, -math.huge
		local Found = false
		for _, Name in ipairs({"PageFrame", "ButtonFrame", "NameFrame", "CharacterPreviewFrame"}) do
			local Obj = GUIObject[Name]
			if Obj and Obj:IsA("GuiObject") and Obj.Visible then
				local P = Obj.AbsolutePosition
				local S = Obj.AbsoluteSize
				if S.X > 0 and S.Y > 0 then
					MinX = math.min(MinX, P.X)
					MinY = math.min(MinY, P.Y)
					MaxX = math.max(MaxX, P.X + S.X)
					MaxY = math.max(MaxY, P.Y + S.Y)
					Found = true
				end
			end
		end
		if not Found then
			return Anim.PivotCache or Vector2.zero, false
		end
		local Pivot = Vector2.new((MinX + MaxX) / 2 - Origin.X, (MinY + MaxY) / 2 - Origin.Y)
		Anim.PivotCache = Pivot
		return Pivot, true
	end

	function Function.Anim.MenuApply(Session)
		local Anim = Function.Anim
		local Main = GUIObject.MainFrame
		local Scale = Anim.MenuScaleFrom + (1 - Anim.MenuScaleFrom) * Session.Shown
		Session.Pop.Scale = Scale
		-- UIScale cresce a partir do canto do MainFrame; compensamos a posição para o pivô ficar parado
		local OffX = math.round(Session.Pivot.X * (1 - Scale))
		local OffY = math.round(Session.Pivot.Y * (1 - Scale))
		local DX = OffX - Session.OffX
		local DY = OffY - Session.OffY
		if DX ~= 0 or DY ~= 0 then
			Main.Position = Main.Position + UDim2.fromOffset(DX, DY)
		end
		Session.OffX = OffX
		Session.OffY = OffY
		if Session.Entries then
			Anim.Apply(Session.Entries, Session.Shown)
		end
	end

	function Function.Anim.MenuFinish(Session, Aborted)
		local Anim = Function.Anim
		if Session.Conn then
			Session.Conn:Disconnect()
			Session.Conn = nil
		end
		if Anim.Menu.Session == Session then
			Anim.Menu.Session = nil
		end
		local Main = GUIObject.MainFrame
		if Main.Parent then
			Main.Position = Main.Position - UDim2.fromOffset(Session.OffX, Session.OffY)
		end
		Session.Pop:Destroy()
		if not Aborted and Session.Target == 0 and GUIObject.Screen.Parent then
			GUIObject.Screen.Enabled = false
		end
		Anim.Restore(Session.Entries)
	end

	function Function.Anim.MenuStep(Session)
		local Anim = Function.Anim
		if Anim.Menu.Session ~= Session then
			if Session.Conn then
				Session.Conn:Disconnect()
				Session.Conn = nil
			end
			return
		end
		if not GUIObject.Screen.Parent or not GUIObject.MainFrame.Parent then
			Anim.MenuFinish(Session, true)
			return
		end
		if Session.PivotPending then
			local Pivot, Found = Anim.MenuPivot()
			if Found then
				Session.Pivot = Pivot
				Session.PivotPending = false
			end
		end
		local T = math.clamp((os.clock() - Session.Start) / Session.Duration, 0, 1)
		local Style = Session.Target == 1 and Enum.EasingStyle.Back or Enum.EasingStyle.Quad
		local Eased = TS:GetValue(T, Style, Enum.EasingDirection.Out)
		Session.Shown = Session.From + (Session.Target - Session.From) * Eased
		Anim.MenuApply(Session)
		if T >= 1 then
			Anim.MenuFinish(Session, false)
		end
	end

	function Function.Anim.StartMenu(Open)
		local Anim = Function.Anim
		local Menu = Anim.Menu
		local Screen = GUIObject.Screen
		local Main = GUIObject.MainFrame
		Menu.Open = Open

		local Session = Menu.Session
		if not Session then
			if Screen.Enabled == Open then
				return
			end
			local Pivot, Found = Anim.MenuPivot()
			local Pop = Instance.new("UIScale")
			Pop.Name = "MenuPop"
			Session = {
				Shown = Open and 0 or 1,
				OffX = 0,
				OffY = 0,
				Pivot = Pivot,
				PivotPending = not Found,
				Pop = Pop,
				Entries = Anim.Collect(Main, Anim.FadeCap),
			}
			Menu.Session = Session
			Pop.Parent = Main
			Anim.MenuApply(Session)
			if Open then
				Screen.Enabled = true
			end
		end

		Session.Target = Open and 1 or 0
		Session.From = Session.Shown
		Session.Start = os.clock()
		Session.Duration = math.max((Open and Anim.MenuOpenTime or Anim.MenuCloseTime) * math.abs(Session.Target - Session.From), 0.05)
		if not Session.Conn then
			Session.Conn = RS.RenderStepped:Connect(function()
				Anim.MenuStep(Session)
			end)
		end
	end

	-- se a animação der erro por qualquer motivo, abre/fecha direto como antes
	function Function.Anim.SetMenu(Open)
		local Anim = Function.Anim
		local Ok, Err = pcall(Anim.StartMenu, Open == true)
		if not Ok then
			warn("[RoC] animação do menu:", Err)
			local Session = Anim.Menu.Session
			if Session then
				pcall(Anim.MenuFinish, Session, true)
			end
			Anim.Menu.Open = Open == true
			GUIObject.Screen.Enabled = Open == true
		end
	end

	function Function.Anim.ToggleMenu()
		local Anim = Function.Anim
		local IsOpen
		if Anim.Menu.Session then
			IsOpen = Anim.Menu.Open
		else
			IsOpen = GUIObject.Screen.Enabled
		end
		Anim.SetMenu(not IsOpen)
	end

	-- // ABAS // --
	function Function.Anim.StopJob(Page)
		local Anim = Function.Anim
		local Job = Anim.Pages[Page]
		if not Job then return end
		Anim.Pages[Page] = nil
		Page.Position = Job.Base
		Anim.Restore(Job.Entries)
	end

	function Function.Anim.PageTick()
		local Anim = Function.Anim
		local Now = os.clock()
		local Any = false
		for Page, Job in pairs(Anim.Pages) do
			if not Page.Parent then
				Anim.Pages[Page] = nil
			else
				local T = math.clamp((Now - Job.Start) / Anim.PageTime, 0, 1)
				local Eased = TS:GetValue(T, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
				Page.Position = Job.Base + UDim2.fromOffset(math.round(Anim.PageSlide * (1 - Eased)), 0)
				if Job.Entries then
					Anim.Apply(Job.Entries, Eased)
				end
				if T >= 1 then
					Page.Position = Job.Base
					Anim.Pages[Page] = nil
					Anim.Restore(Job.Entries)
				else
					Any = true
				end
			end
		end
		if not Any and Anim.PageConn then
			Anim.PageConn:Disconnect()
			Anim.PageConn = nil
		end
	end

	function Function.Anim.PageIn(Page)
		local Anim = Function.Anim
		-- clicar na aba que já estava aberta desliga e religa a página no mesmo instante: sem replay
		local StoppedAt = Anim.PageStopped[Page]
		if StoppedAt and os.clock() - StoppedAt < 0.05 then return end
		if not GUIObject.Screen.Enabled or Anim.Menu.Session then return end
		Anim.StopJob(Page)
		Anim.Pages[Page] = {
			Base = Page.Position,
			Entries = Anim.Collect(Page, Anim.FadeCap),
			Start = os.clock(),
		}
		if not Anim.PageConn then
			Anim.PageConn = RS.RenderStepped:Connect(Anim.PageTick)
		end
		Anim.PageTick()
	end

	function Function.Anim.SetupPages()
		local Anim = Function.Anim
		local function Hook(Page)
			if not Page:IsA("GuiObject") or Anim.PageHooked[Page] ~= nil then return end
			Anim.PageHooked[Page] = Page.Visible
			table.insert(AllConnect, Page:GetPropertyChangedSignal("Visible"):Connect(function()
				local Was = Anim.PageHooked[Page]
				local Now = Page.Visible
				Anim.PageHooked[Page] = Now
				if Now and not Was then
					local Ok, Err = pcall(Anim.PageIn, Page)
					if not Ok then warn("[RoC] animação da aba:", Err) end
				elseif not Now then
					Anim.PageStopped[Page] = os.clock()
					Anim.StopJob(Page)
				end
			end))
		end
		for _, Page in ipairs(GUIObject.PageFrame:GetChildren()) do
			Hook(Page)
		end
		table.insert(AllConnect, GUIObject.PageFrame.ChildAdded:Connect(Hook))
	end

	-- // BALÃO DO SLIDER // --
	-- um balão só (só um slider fica preso por vez), no ScreenGui para nenhuma página cortar ele
	function Function.Anim.GetBubble()
		local Anim = Function.Anim
		local Bubble = Anim.Bubble
		if Bubble and Bubble.Frame.Parent then
			return Bubble
		end
		if not GUIObject.Screen.Parent then
			return nil
		end
		local Theme = Function.MenuTheme

		local Frame = Instance.new("Frame")
		Frame.Name = "SliderValueBubble"
		Frame.AnchorPoint = Vector2.new(0.5, 1)
		Frame.Size = UDim2.fromOffset(40, 26)
		Frame.BackgroundColor3 = Theme.Panel
		Frame.BackgroundTransparency = 1
		Frame.BorderSizePixel = 0
		Frame.Visible = false
		Frame.ZIndex = 1000

		local Corner = Instance.new("UICorner")
		Corner.CornerRadius = UDim.new(0, 8)
		Corner.Parent = Frame

		local Stroke = Instance.new("UIStroke")
		Stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
		Stroke.Color = Theme.Mint
		Stroke.Thickness = 1.5
		Stroke.Transparency = 1
		Stroke.Parent = Frame

		local Scale = Instance.new("UIScale")
		Scale.Scale = 0.6
		Scale.Parent = Frame

		local Pointer = Instance.new("Frame")
		Pointer.Name = "Pointer"
		Pointer.AnchorPoint = Vector2.new(0.5, 0.5)
		Pointer.Position = UDim2.new(0.5, 0, 1, -2)
		Pointer.Size = UDim2.fromOffset(9, 9)
		Pointer.Rotation = 45
		Pointer.BackgroundColor3 = Theme.Panel
		Pointer.BackgroundTransparency = 1
		Pointer.BorderSizePixel = 0
		Pointer.ZIndex = 1000
		Pointer.Parent = Frame

		local Label = Instance.new("TextLabel")
		Label.Name = "Value"
		Label.Size = UDim2.fromScale(1, 1)
		Label.BackgroundTransparency = 1
		Label.Font = Enum.Font.Code
		Label.TextSize = 14
		Label.TextColor3 = Theme.Mint
		Label.TextTransparency = 1
		Label.TextStrokeTransparency = 1
		Label.TextXAlignment = Enum.TextXAlignment.Center
		Label.Text = ""
		Label.ZIndex = 1001
		Label.Parent = Frame

		Frame.Parent = GUIObject.Screen

		Bubble = {Token = 0, Frame = Frame, Stroke = Stroke, Scale = Scale, Pointer = Pointer, Label = Label}
		Anim.Bubble = Bubble
		return Bubble
	end

	function Function.Anim.BubbleShowRaw()
		local Bubble = Function.Anim.GetBubble()
		if not Bubble then return end
		Bubble.Token += 1
		Bubble.Frame.Visible = true
		TS:Create(Bubble.Scale, TweenInfo.new(0.18, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Scale = 1}):Play()
		local Fade = TweenInfo.new(0.12, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
		TS:Create(Bubble.Frame, Fade, {BackgroundTransparency = 0.05}):Play()
		TS:Create(Bubble.Pointer, Fade, {BackgroundTransparency = 0.05}):Play()
		TS:Create(Bubble.Stroke, Fade, {Transparency = 0.1}):Play()
		TS:Create(Bubble.Label, Fade, {TextTransparency = 0}):Play()
	end

	function Function.Anim.BubbleHideRaw()
		local Bubble = Function.Anim.Bubble
		if not Bubble or not Bubble.Frame.Parent then return end
		Bubble.Token += 1
		local Token = Bubble.Token
		TS:Create(Bubble.Scale, TweenInfo.new(0.12, Enum.EasingStyle.Quad, Enum.EasingDirection.In), {Scale = 0.6}):Play()
		local Fade = TweenInfo.new(0.12, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
		TS:Create(Bubble.Frame, Fade, {BackgroundTransparency = 1}):Play()
		TS:Create(Bubble.Pointer, Fade, {BackgroundTransparency = 1}):Play()
		TS:Create(Bubble.Stroke, Fade, {Transparency = 1}):Play()
		TS:Create(Bubble.Label, Fade, {TextTransparency = 1}):Play()
		task.delay(0.14, function()
			if Bubble.Token == Token and Bubble.Frame.Parent then
				Bubble.Frame.Visible = false
			end
		end)
	end

	-- Fraction: posição do valor no trilho (0..1); Text: valor já formatado
	function Function.Anim.BubbleMoveRaw(Track, Knob, Fraction, Text)
		local Bubble = Function.Anim.GetBubble()
		if not Bubble then return end
		Bubble.Label.Text = Text
		Bubble.Frame.Size = UDim2.fromOffset(math.max(40, math.ceil(Bubble.Label.TextBounds.X) + 20), 26)
		local X = Track.AbsolutePosition.X + Fraction * Track.AbsoluteSize.X
		local Y = Track.AbsolutePosition.Y + Track.AbsoluteSize.Y / 2 - Knob.AbsoluteSize.Y / 2 - 10
		local ScreenWidth = GUIObject.Screen.AbsoluteSize.X
		X = math.clamp(X, 32, math.max(ScreenWidth - 32, 32))
		Y = math.max(Y, 36)
		Bubble.Frame.Position = UDim2.fromOffset(math.round(X), math.round(Y))
	end

	function Function.Anim.BubbleShow()
		local Ok, Err = pcall(Function.Anim.BubbleShowRaw)
		if not Ok then warn("[RoC] balão:", Err) end
	end

	function Function.Anim.BubbleHide()
		local Ok, Err = pcall(Function.Anim.BubbleHideRaw)
		if not Ok then warn("[RoC] balão:", Err) end
	end

	function Function.Anim.BubbleMove(Track, Knob, Fraction, Text)
		local Ok, Err = pcall(Function.Anim.BubbleMoveRaw, Track, Knob, Fraction, Text)
		if not Ok then warn("[RoC] balão:", Err) end
	end

	function Function.SetupAnimations()
		Function.Anim.SetupPages()
	end

	-- // LAYOUT: espelho à esquerda, abas em cima, conteúdo à direita // --
	-- ===================================================================================== --
	-- // SLIDERS // --
	-- Transformam as caixinhas de valor em: [ RÓTULO ]  [====●------]  [ caixinha ]
	-- A caixinha é a MESMA TextBox original (todos os handlers antigos continuam valendo).
	-- Trava global: só um slider por vez. Enquanto segurar, o slider continua preso ao dedo/mouse
	-- em qualquer lugar da tela; outro slider só responde depois que você soltar.
	-- ===================================================================================== --
	Function.SliderLock = {Active = nil, Input = nil, Hooked = false, Scrolls = nil, FramePos = nil}

	function Function.SliderFormat(Value, Step)
		local StepText = tostring(Step)
		local Dot = string.find(StepText, ".", 1, true)
		local Decimals = Dot and (#StepText - Dot) or 0
		if Decimals <= 0 then
			return tostring(math.round(Value))
		end
		local Text = string.format("%." .. Decimals .. "f", Value)
		Text = string.gsub(Text, "0+$", "")
		Text = string.gsub(Text, "%.$", "")
		if Text == "-0" then Text = "0" end
		return Text
	end

	function Function.SliderRelease()
		local Lock = Function.SliderLock
		local Slider = Lock.Active
		if not Slider then return end
		Lock.Active = nil
		Lock.Input = nil
		GUIObject.Dragger.Enabled = true
		if Lock.Scrolls then
			for Scroll, Was in pairs(Lock.Scrolls) do
				if Scroll.Parent then
					Scroll.ScrollingEnabled = Was
				end
			end
		end
		Lock.Scrolls = nil
		Lock.FramePos = nil
		pcall(Slider.Finish)
	end

	function Function.SliderHook()
		local Lock = Function.SliderLock
		if Lock.Hooked then return end
		Lock.Hooked = true

		-- movimento em QUALQUER lugar da tela vai para o slider travado
		table.insert(AllConnect, UIS.InputChanged:Connect(function(Input)
			local Slider = Lock.Active
			if not Slider or not Lock.Input then return end
			local Type = Input.UserInputType
			if Lock.Input.UserInputType == Enum.UserInputType.Touch then
				if Type ~= Enum.UserInputType.Touch or Input ~= Lock.Input then return end
			elseif Type ~= Enum.UserInputType.MouseMovement then
				return
			end
			if Lock.FramePos then
				GUIObject.MainFrame.Position = Lock.FramePos
			end
			Slider.Move(Input.Position.X)
		end))

		-- só solta quando o MESMO dedo/botão que segurou for solto
		table.insert(AllConnect, UIS.InputEnded:Connect(function(Input)
			if not Lock.Active or not Lock.Input then return end
			local Held = Lock.Input.UserInputType
			if Input == Lock.Input
				or (Held == Enum.UserInputType.MouseButton1 and Input.UserInputType == Enum.UserInputType.MouseButton1) then
				Function.SliderRelease()
			end
		end))

		table.insert(AllConnect, UIS.WindowFocusReleased:Connect(Function.SliderRelease))
	end

	-- Box    = TextBox original da caixinha
	-- Config = {Label, Min, Max, Step, Stack (layout empilhado p/ células quadradas), Commit(valor)}
	function Function.MenuSlider(Box, Config)
		local Theme = Function.MenuTheme
		local Frame = Box and Box.Parent
		if not Frame or Frame:FindFirstChild("MenuSlider") then return end
		Function.SliderHook()

		local Min = Config.Min or 0
		local Max = Config.Max or 1
		local Step = Config.Step or 0.01
		local BaseMax = Max
		local Stack = Config.Stack == true
		local Z = Box.ZIndex + 1

		local Tween = function(Obj, Time, Goal)
			TS:Create(Obj, TweenInfo.new(Time, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), Goal):Play()
		end

		-- // estrutura // --
		local Holder = Instance.new("Frame")
		Holder.Name = "MenuSlider"
		Holder.BackgroundTransparency = 1
		Holder.Size = UDim2.fromScale(1, 1)
		Holder.ZIndex = Z
		Holder.Parent = Frame

		local Label = Instance.new("TextLabel")
		Label.Name = "SliderLabel"
		Label.BackgroundTransparency = 1
		Label.Font = Enum.Font.Code
		Label.Text = string.upper(Config.Label or Box.PlaceholderText or "")
		Label.TextColor3 = Theme.Soft
		Label.TextScaled = true
		Label.TextStrokeTransparency = 1
		Label.ZIndex = Z
		Label.Parent = Holder

		local Hit = Instance.new("TextButton")
		Hit.Name = "SliderHit"
		Hit.BackgroundTransparency = 1
		Hit.AutoButtonColor = false
		Hit.Active = true
		Hit.Text = ""
		Hit.ZIndex = Z
		Hit.Parent = Holder

		local Track = Instance.new("Frame")
		Track.Name = "Track"
		Track.AnchorPoint = Vector2.new(0, 0.5)
		Track.Position = UDim2.new(0.05, 0, 0.5, 0)
		Track.BackgroundColor3 = Theme.Deep
		Track.BorderSizePixel = 0
		Track.ZIndex = Z
		Track.Parent = Hit
		local TrackCorner = Instance.new("UICorner")
		TrackCorner.CornerRadius = UDim.new(1, 0)
		TrackCorner.Parent = Track
		local TrackStroke = Instance.new("UIStroke")
		TrackStroke.Color = Theme.Accent
		TrackStroke.Thickness = 1
		TrackStroke.Transparency = 0.55
		TrackStroke.Parent = Track

		-- marcas de escala (25% / 50% / 75%)
		for _, Mark in ipairs({0.25, 0.5, 0.75}) do
			local Tick = Instance.new("Frame")
			Tick.Name = "Tick"
			Tick.AnchorPoint = Vector2.new(0.5, 0.5)
			Tick.Position = UDim2.new(Mark, 0, 0.5, 0)
			Tick.Size = UDim2.new(0, 1, 0.5, 0)
			Tick.BackgroundColor3 = Theme.Soft
			Tick.BackgroundTransparency = 0.6
			Tick.BorderSizePixel = 0
			Tick.ZIndex = Z
			Tick.Parent = Track
		end

		local Fill = Instance.new("Frame")
		Fill.Name = "Fill"
		Fill.BackgroundColor3 = Color3.new(1, 1, 1)
		Fill.BorderSizePixel = 0
		Fill.Size = UDim2.new(0, 0, 1, 0)
		Fill.ZIndex = Z + 1
		Fill.Parent = Track
		local FillCorner = Instance.new("UICorner")
		FillCorner.CornerRadius = UDim.new(1, 0)
		FillCorner.Parent = Fill
		local FillGradient = Instance.new("UIGradient")
		FillGradient.Color = ColorSequence.new(Theme.Accent, Theme.Mint)
		FillGradient.Parent = Fill

		local Knob = Instance.new("Frame")
		Knob.Name = "Knob"
		Knob.AnchorPoint = Vector2.new(0.5, 0.5)
		Knob.Position = UDim2.new(0, 0, 0.5, 0)
		Knob.SizeConstraint = Enum.SizeConstraint.RelativeYY
		Knob.Size = UDim2.new(2.3, 0, 2.3, 0)
		Knob.BackgroundColor3 = Theme.Panel
		Knob.BorderSizePixel = 0
		Knob.ZIndex = Z + 2
		Knob.Parent = Track
		local KnobCorner = Instance.new("UICorner")
		KnobCorner.CornerRadius = UDim.new(1, 0)
		KnobCorner.Parent = Knob
		local KnobStroke = Instance.new("UIStroke")
		KnobStroke.Color = Theme.Accent
		KnobStroke.Thickness = 2
		KnobStroke.Transparency = 0
		KnobStroke.Parent = Knob
		local KnobScale = Instance.new("UIScale")
		KnobScale.Parent = Knob
		local Core = Instance.new("Frame")
		Core.Name = "Core"
		Core.AnchorPoint = Vector2.new(0.5, 0.5)
		Core.Position = UDim2.fromScale(0.5, 0.5)
		Core.Size = UDim2.fromScale(0.42, 0.42)
		Core.BackgroundColor3 = Theme.Accent
		Core.BorderSizePixel = 0
		Core.ZIndex = Z + 3
		Core.Parent = Knob
		local CoreCorner = Instance.new("UICorner")
		CoreCorner.CornerRadius = UDim.new(1, 0)
		CoreCorner.Parent = Core

		-- // caixinha pequena (a TextBox original reaproveitada) // --
		Box.ClearTextOnFocus = false
		Box.BackgroundColor3 = Theme.Deep
		Box.BackgroundTransparency = 0.1
		Box.TextColor3 = Theme.Mint
		Box.TextStrokeTransparency = 1
		Box.PlaceholderText = "-"
		Box.PlaceholderColor3 = Theme.Soft
		Box.ZIndex = Z + 1
		Box.TextXAlignment = Enum.TextXAlignment.Center
		local BoxCorner = Box:FindFirstChild("SliderBoxCorner") or Instance.new("UICorner")
		BoxCorner.Name = "SliderBoxCorner"
		BoxCorner.CornerRadius = UDim.new(0.3, 0)
		BoxCorner.Parent = Box
		local BoxStroke = Box:FindFirstChild("SliderBoxStroke") or Instance.new("UIStroke")
		BoxStroke.Name = "SliderBoxStroke"
		BoxStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
		BoxStroke.Color = Theme.Accent
		BoxStroke.Thickness = 1.2
		BoxStroke.Transparency = 0.3
		BoxStroke.Parent = Box
		local BoxPad = Box:FindFirstChild("SliderBoxPad") or Instance.new("UIPadding")
		BoxPad.Name = "SliderBoxPad"
		BoxPad.PaddingTop = UDim.new(0.12, 0)
		BoxPad.PaddingBottom = UDim.new(0.12, 0)
		BoxPad.PaddingLeft = UDim.new(0.08, 0)
		BoxPad.PaddingRight = UDim.new(0.08, 0)
		BoxPad.Parent = Box

		-- // layout // --
		if Stack then
			-- célula quadrada: rótulo em cima, trilho no meio, caixinha embaixo
			Label.TextXAlignment = Enum.TextXAlignment.Center
			Label.Position = UDim2.new(0.06, 0, 0.06, 0)
			Label.Size = UDim2.new(0.88, 0, 0.22, 0)
			Hit.Position = UDim2.new(0.04, 0, 0.32, 0)
			Hit.Size = UDim2.new(0.92, 0, 0.3, 0)
			Track.Size = UDim2.new(0.9, 0, 0.26, 0)
			Box.AnchorPoint = Vector2.new(0.5, 0)
			Box.Position = UDim2.new(0.5, 0, 0.68, 0)
			Box.Size = UDim2.new(0.62, 0, 0.24, 0)
		else
			-- linha: [RÓTULO] [==●--] [caixinha]
			Label.TextXAlignment = Enum.TextXAlignment.Left
			Label.Position = UDim2.new(0.035, 0, 0.18, 0)
			Label.Size = UDim2.new(0.27, 0, 0.64, 0)
			Hit.Position = UDim2.new(0.31, 0, 0, 0)
			Hit.Size = UDim2.new(0.47, 0, 1, 0)
			Track.Size = UDim2.new(0.9, 0, 0.2, 0)
			Box.AnchorPoint = Vector2.new(0, 0.5)
			Box.Position = UDim2.new(0.8, 0, 0.5, 0)
			Box.Size = UDim2.new(0.175, 0, 0.72, 0)
		end

		-- // lógica // --
		local Current = tonumber(Box.Text) or Min
		local Dragging = false
		local LastPush = 0
		local Pending = nil
		local Scheduled = false

		local function Alpha(Value)
			if Max <= Min then return 0 end
			return math.clamp((Value - Min) / (Max - Min), 0, 1)
		end

		local function Render(Value, Instant)
			local A = Alpha(Value)
			if Instant then
				Fill.Size = UDim2.new(A, 0, 1, 0)
				Knob.Position = UDim2.new(A, 0, 0.5, 0)
			else
				Tween(Fill, 0.18, {Size = UDim2.new(A, 0, 1, 0)})
				Tween(Knob, 0.18, {Position = UDim2.new(A, 0, 0.5, 0)})
			end
		end

		local function Snap(Value)
			Value = math.clamp(Value, Min, Max)
			Value = Min + math.round((Value - Min) / Step) * Step
			return math.clamp(Value, Min, Max)
		end

		-- escreve na caixinha => dispara os handlers originais do script
		local function Flush()
			if Pending == nil then return end
			local Text = Function.SliderFormat(Pending, Step)
			Pending = nil
			LastPush = os.clock()
			if Box.Text ~= Text then
				Box.Text = Text
			end
		end

		local function SetVisualActive(On)
			Tween(KnobScale, 0.15, {Scale = On and 1.3 or 1})
			Tween(KnobStroke, 0.15, {Color = On and Theme.Mint or Theme.Accent, Thickness = On and 3 or 2})
			Tween(Core, 0.15, {BackgroundColor3 = On and Theme.Mint or Theme.Accent})
			Tween(TrackStroke, 0.15, {Transparency = On and 0.1 or 0.55, Color = On and Theme.Mint or Theme.Accent})
			Tween(BoxStroke, 0.15, {Transparency = On and 0 or 0.3, Color = On and Theme.Mint or Theme.Accent})
			Tween(Label, 0.15, {TextColor3 = On and Theme.Mint or Theme.Soft})
		end

		local Slider = {}

		function Slider.Move(X)
			local Left = Track.AbsolutePosition.X
			local Width = Track.AbsoluteSize.X
			if Width <= 0 then return end
			local Value = Snap(Min + (X - Left) / Width * (Max - Min))
			Current = Value
			Render(Value, true)
			Function.Anim.BubbleMove(Track, Knob, Alpha(Value), Function.SliderFormat(Value, Step))
			Pending = Value
			-- limita a ~16 escritas/s para não travar o menu (GUIUpdate é pesado)
			if os.clock() - LastPush >= 0.06 then
				Flush()
			elseif not Scheduled then
				Scheduled = true
				task.delay(0.06, function()
					Scheduled = false
					Flush()
				end)
			end
		end

		function Slider.Finish()
			Dragging = false
			Pending = Current
			Flush()
			SetVisualActive(false)
			Function.Anim.BubbleHide()
			if Config.Commit then
				task.spawn(Config.Commit, Current)
			end
		end

		Hit.InputBegan:Connect(function(Input)
			local Type = Input.UserInputType
			if Type ~= Enum.UserInputType.MouseButton1 and Type ~= Enum.UserInputType.Touch then return end
			local Lock = Function.SliderLock
			if Lock.Active then return end -- outro slider já está sendo segurado

			Lock.Active = Slider
			Lock.Input = Input
			Lock.FramePos = GUIObject.MainFrame.Position
			Dragging = true

			-- trava arrastar o menu e rolar listas enquanto segura
			GUIObject.Dragger.Enabled = false
			Lock.Scrolls = {}
			local Parent = Frame.Parent
			while Parent do
				if Parent:IsA("ScrollingFrame") then
					Lock.Scrolls[Parent] = Parent.ScrollingEnabled
					Parent.ScrollingEnabled = false
				end
				Parent = Parent.Parent
			end

			if Box:IsFocused() then
				Box:ReleaseFocus()
			end
			SetVisualActive(true)
			Function.Anim.BubbleShow()
			Slider.Move(Input.Position.X)
		end)

		-- caixinha -> slider (digitação manual, GUIUpdate, troca de player etc.)
		local function SyncFromBox(Instant)
			if Dragging then return end
			local Number = tonumber(Box.Text)
			if Number then
				if Number > Max then
					Max = Number -- valor digitado acima do limite: a escala acompanha
				elseif Number <= BaseMax then
					Max = BaseMax
				end
				Current = Number
				Render(Number, Instant)
			else
				Current = Min
				Render(Min, Instant)
			end
		end

		Box:GetPropertyChangedSignal("Text"):Connect(function()
			SyncFromBox(false)
		end)
		Box.Focused:Connect(function()
			Tween(BoxStroke, 0.15, {Transparency = 0, Color = Theme.Mint})
		end)
		Box.FocusLost:Connect(function()
			Tween(BoxStroke, 0.15, {Transparency = 0.3, Color = Theme.Accent})
			SyncFromBox(false)
		end)

		Hit.MouseEnter:Connect(function()
			if Function.SliderLock.Active ~= Slider then
				Tween(TrackStroke, 0.15, {Transparency = 0.25})
			end
		end)
		Hit.MouseLeave:Connect(function()
			if Function.SliderLock.Active ~= Slider then
				Tween(TrackStroke, 0.15, {Transparency = 0.55})
			end
		end)

		SyncFromBox(true)
		return Slider
	end

	function Function.SetupMenuSliders()
		local Commit = function(Key)
			return function(Value)
				if PlayerData[SelectPlayer] then
					PlayerData[SelectPlayer][Key] = Value
					Function.GUIUpdate()
				end
			end
		end

		-- [v26] sliders do SmartBone: grava, atualiza a tela e reaplica o tuning com debounce
		local CommitSB = function(Key)
			return function(Value)
				if PlayerData[SelectPlayer] then
					PlayerData[SelectPlayer][Key] = Value
					Function.GUIUpdate()
					Function.QueueSmartBoneTuning()
				end
			end
		end

		local List = {
			{GUIObject.DelayTimeText, {Label = "Delay", Min = 0, Max = 10, Step = 0.1}},
			{GUIObject.PositionPhysicsMultiplyText, {Label = "Pos Physics", Min = 0, Max = 10, Step = 0.1}},
			{GUIObject.RotationPhysicsMultiplyText, {Label = "Rot Physics", Min = 0, Max = 20, Step = 0.1}},
			{GUIObject.BreastsScaleText, {Label = "Breasts", Min = 0, Max = 3, Step = 0.01}},
			{GUIObject.ButtsScaleText, {Label = "Butts", Min = 0, Max = 3, Step = 0.01}},
			{GUIObject.LegsScaleText, {Label = "Legs", Min = 0, Max = 3, Step = 0.01}},
			{GUIObject.CockScaleText, {Label = "Cock", Min = 0, Max = 3, Step = 0.01}},
			{GUIObject.TopHPText, {Label = "Shirt HP", Min = 0, Max = 1000, Step = 1, Commit = Commit("TopHP")}},
			{GUIObject.BottomHPText, {Label = "Pants HP", Min = 0, Max = 1000, Step = 1, Commit = Commit("BottomHP")}},
			{GUIObject.VolumeText, {Label = "Volume", Min = 0, Max = 10, Step = 0.1, Commit = Commit("Volume")}},
			{GUIObject.SBStiffnessText, {Label = "SB Stiffness", Min = 0, Max = 3, Step = 0.01, Commit = CommitSB("SBStiffness")}},
			{GUIObject.SBDampingText, {Label = "SB Damping", Min = 0, Max = 3, Step = 0.01, Commit = CommitSB("SBDamping")}},
			{GUIObject.SBElasticityText, {Label = "SB Elasticity", Min = 0, Max = 3, Step = 0.01, Commit = CommitSB("SBElasticity")}},
			{GUIObject.SBGravityText, {Label = "SB Gravity", Min = 0, Max = 3, Step = 0.01, Commit = CommitSB("SBGravity")}},
		}

		for _, Item in ipairs(List) do
			xpcall(Function.MenuSlider, function(Err) warn("[RoC] slider:", Err) end, Item[1], Item[2])
		end
	end

	-- ===================================================================================== --
	-- // VISUAL MODERNO: BOTÕES, ABAS, SWITCHES, SELETORES E CATÁLOGOS SEM RECORTE // --
	-- Só aparência + encaixe. Nomes, hierarquia, eventos e lógica originais ficam intactos.
	--  • Botões de ação  -> superfície escura, faixa colorida da categoria, hover e clique com mola
	--  • Liga/desliga    -> switch animado (lê o TextStrokeColor3 verde/vermelho que o script já usa)
	--  • "Nome: Valor"   -> rótulo à esquerda + chip de valor com › à direita
	--  • Abas            -> texto centralizado com sublinhado neon na aba ativa
	--  • Catálogos       -> grade recalculada em pixels, com respiro interno: nada corta nas bordas
	--  • Páginas         -> tudo que vaza da página é empurrado/encolhido para dentro
	-- ===================================================================================== --
	Function.Modern = {Styled = setmetatable({}, {__mode = "k"})}
	Function.ModernText = Color3.fromRGB(232, 242, 255)

	function Function.ModernTween(Obj, Time, Goal, Style)
		TS:Create(Obj, TweenInfo.new(Time, Style or Enum.EasingStyle.Quint, Enum.EasingDirection.Out), Goal):Play()
	end

	function Function.ModernCorner(Parent, Radius)
		local Corner = Parent:FindFirstChildOfClass("UICorner") or Instance.new("UICorner")
		Corner.CornerRadius = Radius
		Corner.Parent = Parent
		return Corner
	end

	-- devolve a TextButton/TextBox "principal" de um frame-botão (ou nil se não for um)
	function Function.ModernIsButtonFrame(Obj)
		if not Obj:IsA("Frame") then return nil end
		if Obj:FindFirstChild("MenuSlider") then
			return Obj:FindFirstChildOfClass("TextBox")
		end
		for _, Child in ipairs(Obj:GetChildren()) do
			if (Child:IsA("TextButton") or Child:IsA("TextBox")) and Child.Size == UDim2.new(1, 0, 1, 0) then
				return Child
			end
		end
		return nil
	end

	-- verde = ligado, vermelho = desligado, outra cor = não é liga/desliga
	function Function.ModernToggleState(Button)
		local C = Button.TextStrokeColor3
		if C.G > C.R + 0.5 then
			return true
		elseif C.R > C.G + 0.5 then
			return false
		end
		return nil
	end

	function Function.ModernRefresh(Frame, Button, Tint)
		local Theme = Function.MenuTheme
		local Tween = Function.ModernTween
		local W, H = Frame.AbsoluteSize.X, Frame.AbsoluteSize.Y
		local Pad = Button:FindFirstChild("ModernPad")
		local Bar = Frame:FindFirstChild("ModernBar")
		local State = Function.ModernToggleState(Button)
		local Switch = Frame:FindFirstChild("ModernSwitch")
		local Cycle = Frame:FindFirstChild("ModernCycle")
		local Z = Button.ZIndex + 1

		Button.TextXAlignment = (H > 0 and W < H * 1.8) and Enum.TextXAlignment.Center or Enum.TextXAlignment.Left

		-- // liga/desliga -> switch // --
		if State ~= nil then
			if Cycle then Cycle:Destroy() end
			Button.TextTransparency = 0
			if not Switch then
				Switch = Instance.new("Frame")
				Switch.Name = "ModernSwitch"
				Switch.AnchorPoint = Vector2.new(1, 0.5)
				Switch.Position = UDim2.new(1, -10, 0.5, 0)
				Switch.Size = UDim2.new(0, 0, 0.46, 0)
				Switch.BackgroundColor3 = Theme.Deep
				Switch.BorderSizePixel = 0
				Switch.ZIndex = Z
				Switch.Parent = Frame
				local Ratio = Instance.new("UIAspectRatioConstraint")
				Ratio.AspectRatio = 1.85
				Ratio.DominantAxis = Enum.DominantAxis.Height
				Ratio.Parent = Switch
				Function.ModernCorner(Switch, UDim.new(1, 0))
				local SwitchStroke = Instance.new("UIStroke")
				SwitchStroke.Name = "SwitchStroke"
				SwitchStroke.Thickness = 1
				SwitchStroke.Parent = Switch
				local Knob = Instance.new("Frame")
				Knob.Name = "Knob"
				Knob.SizeConstraint = Enum.SizeConstraint.RelativeYY
				Knob.Size = UDim2.new(0.72, 0, 0.72, 0)
				Knob.BorderSizePixel = 0
				Knob.ZIndex = Z + 1
				Knob.Parent = Switch
				Function.ModernCorner(Knob, UDim.new(1, 0))
				Switch:SetAttribute("On", State)
				Knob.AnchorPoint = State and Vector2.new(1, 0.5) or Vector2.new(0, 0.5)
				Knob.Position = State and UDim2.new(1, -3, 0.5, 0) or UDim2.new(0, 3, 0.5, 0)
			end
			local Knob = Switch.Knob
			local SwitchStroke = Switch.SwitchStroke
			Tween(Knob, 0.22, {
				AnchorPoint = State and Vector2.new(1, 0.5) or Vector2.new(0, 0.5),
				Position = State and UDim2.new(1, -3, 0.5, 0) or UDim2.new(0, 3, 0.5, 0),
				BackgroundColor3 = State and Theme.Mint or Color3.fromRGB(110, 124, 150),
			}, Enum.EasingStyle.Back)
			Tween(Switch, 0.22, {BackgroundColor3 = State and Theme.Mint:Lerp(Theme.Deep, 0.7) or Theme.Deep})
			Tween(SwitchStroke, 0.22, {Color = State and Theme.Mint or Theme.Soft, Transparency = State and 0.1 or 0.6})
			if Bar then
				Tween(Bar, 0.22, {BackgroundColor3 = State and Theme.Mint or Theme.Danger})
			end
			if Pad then
				Pad.PaddingRight = UDim.new(0, math.floor(H * 0.46 * 1.85) + 18)
			end
			return
		end

		if Switch then Switch:Destroy() end
		if Pad then Pad.PaddingRight = UDim.new(0, 10) end
		if Bar then Bar.BackgroundColor3 = Frame:GetAttribute("ModernSelected") and Theme.Mint or Tint end

		-- // "Nome: Valor" -> rótulo + chip // --
		local Name, Value = string.match(Button.Text, "^(.-):%s*(.+)$")
		if Name and Name ~= "" and Value and Value ~= "" and H > 0 and W >= H * 2.6 then
			Button.TextTransparency = 1
			if not Cycle then
				Cycle = Instance.new("Frame")
				Cycle.Name = "ModernCycle"
				Cycle.BackgroundTransparency = 1
				Cycle.Size = UDim2.fromScale(1, 1)
				Cycle.ZIndex = Z
				Cycle.Parent = Frame

				local NameLabel = Instance.new("TextLabel")
				NameLabel.Name = "NameLabel"
				NameLabel.BackgroundTransparency = 1
				NameLabel.Position = UDim2.new(0, 16, 0.22, 0)
				NameLabel.Size = UDim2.new(0.52, -16, 0.56, 0)
				NameLabel.Font = Enum.Font.GothamMedium
				NameLabel.TextColor3 = Theme.Soft
				NameLabel.TextScaled = true
				NameLabel.TextXAlignment = Enum.TextXAlignment.Left
				NameLabel.ZIndex = Z
				NameLabel.Parent = Cycle
				local NameLimit = Instance.new("UITextSizeConstraint")
				NameLimit.MaxTextSize = 15
				NameLimit.Parent = NameLabel

				local Chip = Instance.new("Frame")
				Chip.Name = "Chip"
				Chip.AnchorPoint = Vector2.new(1, 0.5)
				Chip.Position = UDim2.new(1, -8, 0.5, 0)
				Chip.Size = UDim2.new(0.44, 0, 0.68, 0)
				Chip.BackgroundColor3 = Theme.Deep
				Chip.BorderSizePixel = 0
				Chip.ZIndex = Z
				Chip.Parent = Cycle
				Function.ModernCorner(Chip, UDim.new(0, 6))
				local ChipStroke = Instance.new("UIStroke")
				ChipStroke.Color = Tint
				ChipStroke.Transparency = 0.5
				ChipStroke.Thickness = 1
				ChipStroke.Parent = Chip

				local ValueLabel = Instance.new("TextLabel")
				ValueLabel.Name = "ValueLabel"
				ValueLabel.BackgroundTransparency = 1
				ValueLabel.AnchorPoint = Vector2.new(0.5, 0.5)
				ValueLabel.Position = UDim2.fromScale(0.5, 0.5)
				ValueLabel.Size = UDim2.new(1, -12, 0.72, 0)
				ValueLabel.Font = Enum.Font.GothamBold
				ValueLabel.TextColor3 = Theme.Mint
				ValueLabel.TextScaled = true
				ValueLabel.ZIndex = Z + 1
				ValueLabel.Parent = Chip
				local ValueLimit = Instance.new("UITextSizeConstraint")
				ValueLimit.MaxTextSize = 15
				ValueLimit.Parent = ValueLabel

				-- botões de Type abrem submenu: seta (chevron) DESENHADA com 2 barras, sem depender de fonte
				if string.find(Frame.Name, "TypeFrame$") then
					ValueLabel.Position = UDim2.new(0.5, -9, 0.5, 0)
					ValueLabel.Size = UDim2.new(1, -32, 0.72, 0)

					local Chevron = Instance.new("Frame")
					Chevron.Name = "Chevron"
					Chevron.AnchorPoint = Vector2.new(1, 0.5)
					Chevron.Position = UDim2.new(1, -9, 0.5, 1)
					Chevron.Size = UDim2.fromOffset(10, 6)
					Chevron.BackgroundTransparency = 1
					Chevron.ZIndex = Z + 1
					Chevron.Parent = Chip
					for _, Bar in ipairs({{X = 2.9, Rot = 45}, {X = 7.1, Rot = -45}}) do
						local Arm = Instance.new("Frame")
						Arm.Name = "Arm"
						Arm.AnchorPoint = Vector2.new(0.5, 0.5)
						Arm.Position = UDim2.fromOffset(Bar.X, 2.9)
						Arm.Size = UDim2.fromOffset(6, 2)
						Arm.Rotation = Bar.Rot
						Arm.BackgroundColor3 = Theme.Mint
						Arm.BorderSizePixel = 0
						Arm.ZIndex = Z + 1
						Arm.Parent = Chevron
						Function.ModernCorner(Arm, UDim.new(1, 0))
					end
				end
			end
			local ValueLabel = Cycle.Chip.ValueLabel
			local Suffix = Cycle.Chip:FindFirstChild("Chevron") and "" or "  ›"
			local Changed = ValueLabel.Text ~= "" and ValueLabel.Text ~= (Value .. Suffix)
			Cycle.NameLabel.Text = string.upper(Name)
			ValueLabel.Text = Value .. Suffix
			if Changed then
				-- pulinho no chip quando o valor troca
				local Pop = Cycle.Chip:FindFirstChild("Pop") or Instance.new("UIScale")
				Pop.Name = "Pop"
				Pop.Parent = Cycle.Chip
				Pop.Scale = 1.12
				Tween(Pop, 0.3, {Scale = 1}, Enum.EasingStyle.Back)
			end
			return
		end

		if Cycle then Cycle:Destroy() end
		Button.TextTransparency = 0
	end

	-- degrau 3D embaixo do botão/cartão (a base escura dá o relevo).
	function Function.ModernDepthSync(Frame)
		local Surface = Frame:FindFirstChild("ModernSurface")
		if not Surface then return end
		local Theme = Function.MenuTheme
		local Px = Theme.Style.Depth or 0
		local Base = Frame:FindFirstChild("ModernDepth")
		if Px <= 0 then
			if Base then Base.Visible = false end
			return
		end
		if not Base then
			Base = Instance.new("Frame")
			Base.Name = "ModernDepth"
			Base.BorderSizePixel = 0
			Base.Active = false
			Base.Size = UDim2.fromScale(1, 1)
			local Corner = Instance.new("UICorner")
			Corner.Parent = Base
			Base.Parent = Frame
		end
		local FrameCorner = Frame:FindFirstChildOfClass("UICorner")
		local BaseCorner = Base:FindFirstChildOfClass("UICorner")
		if FrameCorner and BaseCorner then
			BaseCorner.CornerRadius = FrameCorner.CornerRadius
		end
		Base.Visible = true
		Base.ZIndex = Surface.ZIndex - 1
		Base.BackgroundColor3 = Theme.Edge
		Base.BackgroundTransparency = 0
		Base.Position = UDim2.fromOffset(0, Px)
	end

	function Function.ModernStyle(Frame)
		if Function.Modern.Styled[Frame] then return end
		local Button = Function.ModernIsButtonFrame(Frame)
		if not Button then return end
		Function.Modern.Styled[Frame] = true

		local Theme = Function.MenuTheme
		local Tween = Function.ModernTween
		local IsTab = Frame.Parent == GUIObject.ButtonFrame
		local IsSlider = Frame:FindFirstChild("MenuSlider") ~= nil
		local IsBox = Button:IsA("TextBox")

		-- cores sempre lidas na hora
		local function TintNow()
			return Frame:GetAttribute("MenuStroke") or Theme.Accent
		end
		local function RestNow()
			if IsBox then return Theme.Deep end
			return Theme.Panel:Lerp(TintNow(), 0.08)
		end
		local function HoverNow()
			if IsBox then return Theme.Deep:Lerp(TintNow(), 0.12) end
			return Theme.Panel:Lerp(TintNow(), 0.2)
		end
		local function PickedNow()
			return Theme.Accent:Lerp(Theme.Panel, 0.6)
		end
		local Tint = TintNow()

		local InList = Frame:FindFirstAncestorOfClass("ScrollingFrame") ~= nil
		local IsTile = InList and Frame.Parent ~= nil and Frame.Parent:GetAttribute("ModernTile") == true

		-- // superfície // --
		-- O script usa o BackgroundColor3 do frame como ESTADO (ex.: item selecionado = ciano),
		-- então o frame fica transparente e intacto e o visual vai numa camada própria.
		Frame.BackgroundTransparency = 1
		Frame.BorderSizePixel = 0
		local Radius = UDim.new(0, IsTab and Theme.Style.TabRadius or (IsTile and 8 or Theme.Style.Radius))
		Function.ModernCorner(Frame, Radius)
		local BaseZ = Button.ZIndex
		if not IsSlider then
			Button.ZIndex = BaseZ + 1
		end
		local Surface = Instance.new("Frame")
		Surface.Name = "ModernSurface"
		Surface.Size = UDim2.fromScale(1, 1)
		Surface.BackgroundColor3 = RestNow()
		Surface.BorderSizePixel = 0
		Surface.ZIndex = IsSlider and 1 or BaseZ
		Surface.Parent = Frame
		Function.ModernCorner(Surface, Radius)
		local Shade = Instance.new("UIGradient")
		Shade.Name = "ModernShade"
		Shade.Color = ColorSequence.new(Theme.Style.ShadeTop, Theme.Style.ShadeBottom)
		Shade.Rotation = 90
		Shade.Parent = Surface

		-- contorno novo (o antigo tinha tweens de hover que brigariam com estes)
		local Old = Frame:FindFirstChildOfClass("UIStroke")
		if Old then Old:Destroy() end
		local Stroke = Instance.new("UIStroke")
		Stroke.Name = "ModernStroke"
		Stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
		Stroke.Color = Tint
		Stroke.Thickness = 1
		Stroke.Transparency = Theme.Style.StrokeRest
		Stroke.Parent = Frame

		local Scale = Frame:FindFirstChild("ModernScale") or Instance.new("UIScale")
		Scale.Name = "ModernScale"
		Scale.Parent = Frame

		-- relevo 3D (degrau escuro embaixo)
		Function.ModernDepthSync(Frame)

		if IsSlider then
			local Label = Frame.MenuSlider:FindFirstChild("SliderLabel")
			if Label then Label.Font = Enum.Font.GothamBold end
			Button.Font = Enum.Font.GothamBold
			return
		end

		-- // texto // --
		Button.Font = (IsTab or IsTile) and Enum.Font.GothamBold or Enum.Font.GothamMedium
		Button.TextStrokeTransparency = 1
		Button.TextScaled = true
		Button.TextWrapped = true
		if not IsBox or Button.TextColor3 == Color3.new(1, 1, 1) then
			Button.TextColor3 = Function.ModernText
		end
		local Limit = Button:FindFirstChildOfClass("UITextSizeConstraint") or Instance.new("UITextSizeConstraint")
		Limit.MaxTextSize = IsTab and 14 or (IsTile and 18 or 16)
		Limit.MinTextSize = IsTile and 9 or 6
		Limit.Parent = Button
		local Pad = Button:FindFirstChild("ModernPad") or Instance.new("UIPadding")
		Pad.Name = "ModernPad"
		Pad.PaddingTop = UDim.new(IsTile and 0.06 or 0.2, 0)
		Pad.PaddingBottom = UDim.new(IsTile and 0.2 or 0.2, 0) -- tile: sobra espaço embaixo pra faixa de cor
		Pad.PaddingLeft = UDim.new(0, (IsTab or IsTile) and 4 or 10)
		Pad.PaddingRight = UDim.new(0, (IsTab or IsTile) and 4 or 10)
		Pad.Parent = Button

		if IsBox then
			-- campo de digitação: fundo mais fundo, contorno acende no foco
			Surface.BackgroundColor3 = Theme.Deep
			Button.TextXAlignment = Enum.TextXAlignment.Left
			Button.Focused:Connect(function()
				Tween(Stroke, 0.15, {Transparency = 0, Color = Theme.Mint})
			end)
			Button.FocusLost:Connect(function()
				Tween(Stroke, 0.15, {Transparency = Theme.Style.StrokeRest, Color = TintNow()})
			end)
		elseif IsTab then
			Button.TextXAlignment = Enum.TextXAlignment.Center
			local Line = Instance.new("Frame")
			Line.Name = "ModernTabLine"
			Line.AnchorPoint = Vector2.new(0.5, 1)
			Line.Position = UDim2.new(0.5, 0, 1, -3)
			Line.Size = UDim2.new(0, 0, 0, 2)
			Line.BackgroundColor3 = Theme.Mint
			Line.BorderSizePixel = 0
			Line.ZIndex = Button.ZIndex + 1
			Line.Parent = Frame
			Function.ModernCorner(Line, UDim.new(1, 0))
			local Page = GUIObject.PageFrame:FindFirstChild(Frame.Name)
			local function Sync()
				local On = Page and Page.Visible
				Tween(Line, 0.25, {Size = On and UDim2.new(0.55, 0, 0, 2) or UDim2.new(0, 0, 0, 2)})
				Tween(Button, 0.25, {TextColor3 = On and Theme.Mint or Function.ModernText})
			end
			if Page then
				table.insert(AllConnect, Page:GetPropertyChangedSignal("Visible"):Connect(Sync))
			end
			Sync()
		else
			-- faixa colorida da categoria
			local Bar = Instance.new("Frame")
			Bar.Name = "ModernBar"
			if IsTile then
				Bar.AnchorPoint = Vector2.new(0.5, 1)
				Bar.Position = UDim2.new(0.5, 0, 1, -5)
				Bar.Size = UDim2.new(0.28, 0, 0, 3)
			else
				Bar.AnchorPoint = Vector2.new(0, 0.5)
				Bar.Position = UDim2.new(0, 6, 0.5, 0)
				Bar.Size = UDim2.new(0, 3, 0.5, 0)
			end
			Bar.BackgroundColor3 = Tint
			Bar.BorderSizePixel = 0
			Bar.ZIndex = Button.ZIndex + 1
			Bar.Parent = Frame
			Function.ModernCorner(Bar, UDim.new(1, 0))
			if not IsTile then
				Pad.PaddingLeft = UDim.new(0, 16)
			end

			local function Refresh()
				Function.ModernRefresh(Frame, Button, TintNow())
			end
			Button:GetPropertyChangedSignal("TextStrokeColor3"):Connect(Refresh)
			Button:GetPropertyChangedSignal("Text"):Connect(Refresh)
			Frame:GetPropertyChangedSignal("AbsoluteSize"):Connect(Refresh)
			Refresh()
		end

		-- // hover + clique com mola // --
		-- item de catálogo selecionado = o script pintou o frame de ciano
		local function IsPicked()
			if not InList then return false end
			local C = Frame.BackgroundColor3
			local Pick = Function.PickColor -- cor de "selecionado" que o script pinta (não muda com o tema)
			return math.abs(C.R - Pick.R) < 0.03 and math.abs(C.G - Pick.G) < 0.03 and math.abs(C.B - Pick.B) < 0.03
		end
		local Hovering = false
		local function Lift(On)
			Hovering = On
			local Sel = IsPicked()
			Frame:SetAttribute("ModernSelected", Sel)
			local Picked = PickedNow()
			Tween(Surface, 0.15, {BackgroundColor3 = Sel and (On and Picked:Lerp(Theme.Accent, 0.15) or Picked) or (On and HoverNow() or RestNow())})
			if not (IsBox and Button:IsFocused()) then
				Tween(Stroke, 0.15, {
					Transparency = Sel and 0 or (On and Theme.Style.StrokeHover or Theme.Style.StrokeRest),
					Color = Sel and Theme.Mint or TintNow(),
					Thickness = Sel and 1.6 or 1,
				})
			end
			local Bar = Frame:FindFirstChild("ModernBar")
			if Bar then
				if Sel then
					Tween(Bar, 0.15, {BackgroundColor3 = Theme.Mint})
				elseif not Frame:FindFirstChild("ModernSwitch") then
					Tween(Bar, 0.15, {BackgroundColor3 = TintNow()})
				end
				if IsTile then
					Tween(Bar, 0.2, {Size = (On or Sel) and UDim2.new(0.62, 0, 0, 3) or UDim2.new(0.28, 0, 0, 3)}, Enum.EasingStyle.Back)
				else
					Tween(Bar, 0.15, {Size = (On or Sel) and UDim2.new(0, 4, 0.66, 0) or UDim2.new(0, 3, 0.5, 0)})
				end
			end
		end
		Frame:GetPropertyChangedSignal("BackgroundColor3"):Connect(function()
			Lift(Hovering)
		end)
		Lift(false)
		Button.MouseEnter:Connect(function() Lift(true) end)
		Button.MouseLeave:Connect(function() Lift(false) end)
		Button.InputBegan:Connect(function(Input)
			local Type = Input.UserInputType
			if Type == Enum.UserInputType.MouseButton1 or Type == Enum.UserInputType.Touch then
				Tween(Scale, 0.08, {Scale = Theme.Style.PressScale})
				local Base = Frame:FindFirstChild("ModernDepth")
				if Base and Base.Visible then
					Tween(Base, 0.08, {Position = UDim2.fromOffset(0, 1)})
				end
			end
		end)
		Button.InputEnded:Connect(function(Input)
			local Type = Input.UserInputType
			if Type == Enum.UserInputType.MouseButton1 or Type == Enum.UserInputType.Touch then
				Tween(Scale, 0.4, {Scale = 1}, Enum.EasingStyle.Back)
				local Base = Frame:FindFirstChild("ModernDepth")
				if Base and Base.Visible then
					Tween(Base, 0.4, {Position = UDim2.fromOffset(0, Theme.Style.Depth)}, Enum.EasingStyle.Back)
				end
				if Type == Enum.UserInputType.Touch then
					Lift(false) -- no celular não existe "mouse saiu"
				end
			end
		end)
	end

	-- escala atual do controle "Menu Size" (1 = 100%)
	function Function.MenuSizeValue()
		local Scale = GUIObject.MenuSizeScale
		return Scale and Scale.Scale or 1
	end

	-- fator total de UIScale que o MainFrame recebe: Menu Size x animação de abrir/fechar (MenuPop).
	-- AbsoluteSize vem JÁ multiplicado por esse fator; CellSize em offset é multiplicado de novo na tela.
	-- Por isso as grades dividem o AbsoluteSize por este fator antes de calcular as células.
	function Function.MenuLocalScale()
		local Factor = Function.MenuSizeValue()
		local Main = GUIObject.MainFrame
		local Pop = Main and Main:FindFirstChild("MenuPop")
		if Pop and Pop:IsA("UIScale") then
			Factor *= Pop.Scale
		end
		return math.max(Factor, 0.05)
	end

	-- quantas colunas (ou linhas) cabem quando o menu está em Size = Scale: mantém o tamanho da célula na tela
	function Function.ScaledCount(Base, Scale)
		return math.max(1, math.floor(Base * Scale + 0.5))
	end

	-- grade de catálogo em pixels + respiro interno => nenhum botão corta na borda
	-- Adaptive = true: o número de colunas/linhas acompanha o Menu Size (sempre preenche a largura, sem sobra)
	function Function.ModernList(Scroll, Columns, Ratio, Rows, Tile, Adaptive)
		if not Scroll or Scroll:GetAttribute("ModernList") then return end
		local Grid = Scroll:FindFirstChildOfClass("UIGridLayout")
		if not Grid then return end
		Scroll:SetAttribute("ModernList", true)
		Scroll:SetAttribute("ModernTile", Tile == true) -- Tile = botões em formato de azulejo (grade compacta)

		local Theme = Function.MenuTheme
		local Gap = 6
		local Pad = Scroll:FindFirstChild("ModernListPad") or Instance.new("UIPadding")
		Pad.Name = "ModernListPad"
		Pad.PaddingTop = UDim.new(0, Gap)
		Pad.PaddingBottom = UDim.new(0, Gap)
		Pad.PaddingLeft = UDim.new(0, Gap)
		Pad.PaddingRight = UDim.new(0, Gap)
		Pad.Parent = Scroll

		Scroll.ClipsDescendants = true
		Scroll.ScrollBarThickness = 3
		Scroll.ScrollBarImageColor3 = Theme.Accent
		Scroll.ScrollBarImageTransparency = 0.25
		Scroll.VerticalScrollBarInset = Enum.ScrollBarInset.ScrollBar
		Scroll.ScrollingDirection = Enum.ScrollingDirection.Y
		Scroll.CanvasSize = UDim2.new(0, 0, 0, 0)
		Scroll.AutomaticCanvasSize = Enum.AutomaticSize.Y

		Grid.CellPadding = UDim2.fromOffset(Gap, Gap)
		Grid.HorizontalAlignment = Enum.HorizontalAlignment.Left
		Grid.FillDirection = Enum.FillDirection.Horizontal

		local function Resize()
			local Local = Function.MenuLocalScale()
			local Inner = Scroll.AbsoluteSize.X / Local - Gap * 2 - Scroll.ScrollBarThickness - 2
			if Inner <= 0 then return end
			local Size = Function.MenuSizeValue()
			local Cols = Adaptive and Function.ScaledCount(Columns, Size) or Columns
			local W = math.floor((Inner - Gap * (Cols - 1)) / Cols)
			local H = math.max(math.floor(W / Ratio), 24)
			-- Rows: força N linhas visíveis por tela (ex.: 6x6), altura sai do espaço disponível
			if Rows and Scroll.AbsoluteSize.Y > 0 then
				local RowCount = Adaptive and Function.ScaledCount(Rows, Size) or Rows
				local InnerY = Scroll.AbsoluteSize.Y / Local - Gap * 2
				H = math.max(math.floor((InnerY - Gap * (RowCount - 1)) / RowCount), 18)
			end
			Grid.CellSize = UDim2.fromOffset(W, H)
		end
		table.insert(AllConnect, Scroll:GetPropertyChangedSignal("AbsoluteSize"):Connect(Resize))
		Resize()

		local function Adopt(Child)
			if not Child:IsA("Frame") then return end
			task.defer(function()
				if not Child.Parent then return end
				for _, C in ipairs(Child:GetChildren()) do
					if C:IsA("UIAspectRatioConstraint") then
						C:Destroy() -- a célula da grade já define o tamanho certo
					end
				end
				Function.ModernStyle(Child)
			end)
		end
		for _, Child in ipairs(Scroll:GetChildren()) do
			Adopt(Child)
		end
		table.insert(AllConnect, Scroll.ChildAdded:Connect(Adopt))
	end

	-- empurra/encolhe para dentro da página tudo que vaza da borda
	function Function.ModernFitPage(Page)
		local Items = {}
		for _, Obj in ipairs(Page:GetChildren()) do
			-- o seletor do boneco tem posição própria (não deixa o encaixe empurrar ele pra cima do Mesh Lock)
			if Obj:IsA("GuiObject") and Obj ~= GUIObject.CharacterFrame then
				if Obj:GetAttribute("ModernPos") == nil then
					Obj:SetAttribute("ModernPos", Obj.Position)
					Obj:SetAttribute("ModernSize", Obj.Size)
				end
				table.insert(Items, Obj)
			end
		end

		local Busy = false
		local function Fit()
			if Busy or Page.AbsoluteSize.X <= 0 then return end
			Busy = true
			for _, Obj in ipairs(Items) do
				if Obj.Parent == Page then
					Obj.Position = Obj:GetAttribute("ModernPos")
					Obj.Size = Obj:GetAttribute("ModernSize")
				end
			end
			RS.Heartbeat:Wait() -- deixa o layout recalcular

			local PL, PT = Page.AbsolutePosition.X, Page.AbsolutePosition.Y
			local PW, PH = Page.AbsoluteSize.X, Page.AbsoluteSize.Y
			local M = math.max(4, math.floor(PW * 0.025))

			local function Axis(Start, Size, Total, Anchor, Locked)
				-- objeto totalmente fora da página = escondido de propósito, não mexe
				local Center = Start + Size / 2
				if Center < 0 or Center > Total then return 0, 0 end
				local NewSize = Size
				if not Locked and Size > Total - M * 2 then
					NewSize = Total - M * 2
				end
				local NewStart = math.clamp(Start, M, math.max(M, Total - M - NewSize))
				local Move = (NewStart + Anchor * NewSize) - (Start + Anchor * Size)
				return math.round(Move), math.round(NewSize - Size)
			end

			for _, Obj in ipairs(Items) do
				if Obj.Parent == Page and Obj.AbsoluteSize.X > 0 and Obj.Rotation == 0 then
					local Locked = Obj:FindFirstChildOfClass("UIAspectRatioConstraint") ~= nil
					local DX, DW = Axis(Obj.AbsolutePosition.X - PL, Obj.AbsoluteSize.X, PW, Obj.AnchorPoint.X, Locked)
					local DY, DH = Axis(Obj.AbsolutePosition.Y - PT, Obj.AbsoluteSize.Y, PH, Obj.AnchorPoint.Y, Locked)
					if DX ~= 0 or DY ~= 0 then
						Obj.Position = Obj.Position + UDim2.fromOffset(DX, DY)
					end
					if DW ~= 0 or DH ~= 0 then
						Obj.Size = Obj.Size + UDim2.fromOffset(DW, DH)
					end
				end
			end
			Busy = false
		end

		table.insert(AllConnect, Page:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
			task.spawn(Fit)
		end))
		task.spawn(Fit)
	end

	-- caixas de busca soltas (sem frame em volta), ex.: busca de roupas/bundles
	function Function.ModernInput(Box)
		if Function.Modern.Styled[Box] then return end
		Function.Modern.Styled[Box] = true
		local Theme = Function.MenuTheme
		local Tween = Function.ModernTween
		Box.BackgroundColor3 = Theme.Deep
		Box.BackgroundTransparency = 0
		Box.BorderSizePixel = 0
		local Gradient = Box:FindFirstChildOfClass("UIGradient")
		if Gradient then
			Gradient.Color = ColorSequence.new(Color3.new(1, 1, 1), Color3.fromRGB(210, 218, 235))
			Gradient.Rotation = 90
		end
		Function.ModernCorner(Box, UDim.new(0, 8))
		local Old = Box:FindFirstChildOfClass("UIStroke")
		if Old then Old:Destroy() end
		local Stroke = Instance.new("UIStroke")
		Stroke.Name = "ModernStroke"
		Stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
		Stroke.Color = Theme.Accent
		Stroke.Thickness = 1
		Stroke.Transparency = 0.55
		Stroke.Parent = Box
		Box.Font = Enum.Font.GothamMedium
		Box.TextStrokeTransparency = 1
		Box.TextScaled = true
		Box.TextXAlignment = Enum.TextXAlignment.Left
		Box.ClearTextOnFocus = false
		if Box.TextColor3 == Color3.new(1, 1, 1) then
			Box.TextColor3 = Function.ModernText
		end
		Box.PlaceholderColor3 = Theme.Soft
		local Limit = Box:FindFirstChildOfClass("UITextSizeConstraint") or Instance.new("UITextSizeConstraint")
		Limit.MaxTextSize = 15
		Limit.Parent = Box
		local Pad = Box:FindFirstChild("ModernPad") or Instance.new("UIPadding")
		Pad.Name = "ModernPad"
		Pad.PaddingTop = UDim.new(0.2, 0)
		Pad.PaddingBottom = UDim.new(0.2, 0)
		Pad.PaddingLeft = UDim.new(0, 12)
		Pad.PaddingRight = UDim.new(0, 12)
		Pad.Parent = Box
		Box.Focused:Connect(function()
			Tween(Stroke, 0.15, {Transparency = 0, Color = Theme.Mint})
		end)
		Box.FocusLost:Connect(function()
			Tween(Stroke, 0.15, {Transparency = 0.55, Color = Theme.Accent})
		end)
	end

	-- botões que não seguem o padrão "frame + botão": seletor de corpo, espelho, engrenagem, fechar
	function Function.ModernExtras()
		local Theme = Function.MenuTheme
		local Tween = Function.ModernTween

		local function Stroke(Parent, Color, Transparency)
			local Old = Parent:FindFirstChildOfClass("UIStroke")
			if Old then Old:Destroy() end
			local S = Instance.new("UIStroke")
			S.Name = "ModernStroke"
			S.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
			S.Color = Color
			S.Thickness = 1
			S.Transparency = Transparency
			S.Parent = Parent
			return S
		end

		local function Bounce(Button, Target)
			Target = Target or Button
			local Scale = Target:FindFirstChild("ModernScale") or Instance.new("UIScale")
			Scale.Name = "ModernScale"
			Scale.Parent = Target
			Button.InputBegan:Connect(function(Input)
				local Type = Input.UserInputType
				if Type == Enum.UserInputType.MouseButton1 or Type == Enum.UserInputType.Touch then
					Tween(Scale, 0.08, {Scale = 0.92})
				end
			end)
			Button.InputEnded:Connect(function(Input)
				local Type = Input.UserInputType
				if Type == Enum.UserInputType.MouseButton1 or Type == Enum.UserInputType.Touch then
					Tween(Scale, 0.4, {Scale = 1}, Enum.EasingStyle.Back)
				end
			end)
		end

		-- // seletor de partes do corpo (cartão + peças que acendem) // --
		local Card = GUIObject.CharacterFrame
		if Card then
			Card.BackgroundColor3 = Theme.Deep
			Card.BackgroundTransparency = 0
			Card.BorderSizePixel = 0
			Function.ModernCorner(Card, UDim.new(0, 10))
			Stroke(Card, Theme.Accent, 0.55)
			local CardPad = Card:FindFirstChild("ModernPad") or Instance.new("UIPadding")
			CardPad.Name = "ModernPad"
			for _, Side in ipairs({"PaddingTop", "PaddingBottom", "PaddingLeft", "PaddingRight"}) do
				CardPad[Side] = UDim.new(0, 4)
			end
			CardPad.Parent = Card

			for _, Part in ipairs({GUIObject.HeadButton, GUIObject.TorsoButton, GUIObject.LeftArmButton, GUIObject.RightArmButton, GUIObject.LeftLegButton, GUIObject.RightLegButton}) do
				if Part then
					Part.BorderSizePixel = 0
					Part.AutoButtonColor = false
					Function.ModernCorner(Part, UDim.new(0, 6))
					local PartStroke = Stroke(Part, Theme.Accent, 0.4)
					-- o script marca ligado = transparência 0 e desligado = 0.5;
					-- desligado vira 0.02 na tela para o próximo "0" do script ainda disparar o evento
					local Guard = false
					local function Paint()
						if Guard then return end
						local On = Part.BackgroundTransparency < 0.01
						Guard = true
						Part.BackgroundTransparency = On and 0 or 0.02
						Guard = false
						Tween(Part, 0.2, {BackgroundColor3 = On and Theme.Mint:Lerp(Theme.Deep, 0.25) or Theme.Panel})
						Tween(PartStroke, 0.2, {Color = On and Theme.Mint or Theme.Accent, Transparency = On and 0 or 0.45})
					end
					Part:GetPropertyChangedSignal("BackgroundTransparency"):Connect(Paint)
					Paint()
					Part.MouseEnter:Connect(function()
						Tween(PartStroke, 0.15, {Thickness = 2})
					end)
					Part.MouseLeave:Connect(function()
						Tween(PartStroke, 0.15, {Thickness = 1})
					end)
					Bounce(Part)
				end
			end
			Card.ClipsDescendants = true
			-- formas do boneco R6: cabeça arredondada, torso/braços/pernas quadrados
			local PartRadius = {
				[GUIObject.HeadButton] = UDim.new(0.3, 0),
				[GUIObject.TorsoButton] = UDim.new(0, 0),
				[GUIObject.LeftArmButton] = UDim.new(0, 0),
				[GUIObject.RightArmButton] = UDim.new(0, 0),
				[GUIObject.LeftLegButton] = UDim.new(0, 0),
				[GUIObject.RightLegButton] = UDim.new(0, 0),
			}
			for Part, Radius in pairs(PartRadius) do
				Function.ModernCorner(Part, Radius)
			end
			for _, Icon in ipairs({GUIObject.HatButton, GUIObject.TailButton}) do
				if Icon then
					Icon.AutoButtonColor = false
					Icon.ImageColor3 = Theme.Soft
					Icon.MouseEnter:Connect(function()
						Tween(Icon, 0.15, {ImageColor3 = Theme.Mint})
					end)
					Icon.MouseLeave:Connect(function()
						Tween(Icon, 0.15, {ImageColor3 = Theme.Soft})
					end)
					Bounce(Icon)
				end
			end
		end

		-- // botão de fechar no celular // --
		local Close = GUIObject.MobileCloseButton
		if Close then
			Close.BackgroundColor3 = Theme.Panel
			Close.BackgroundTransparency = 0.05
			Close.BorderSizePixel = 0
			Close.ImageColor3 = Theme.Accent
			Function.ModernCorner(Close, UDim.new(1, 0))
			Stroke(Close, Theme.Accent, 0.3)
			local Pad = Close:FindFirstChild("ModernPad") or Instance.new("UIPadding")
			Pad.Name = "ModernPad"
			for _, Side in ipairs({"PaddingTop", "PaddingBottom", "PaddingLeft", "PaddingRight"}) do
				Pad[Side] = UDim.new(0.2, 0)
			end
			Pad.Parent = Close
			Bounce(Close)
		end
	end

	function Function.ApplyModernUI()
		-- catálogos / listas: colunas e proporção de cada célula (largura / altura)
		Function.ModernList(GUIObject.ClothesButtonFrame, 5, 1, 5, true, true) -- Clothes: grade 5x5 (base, a 100%) + botões tile; colunas/linhas seguem o Menu Size
		Function.ModernList(GUIObject.BundlesButtonFrame, 2, 3.1, nil, nil, true)
		Function.ModernList(GUIObject.RecolorListFrame, 1, 7)
		Function.ModernList(GUIObject.HPListFrame, 1, 6)
		for _, Child in ipairs(GUIObject.Catalog_3:GetChildren()) do
			if Child:IsA("ScrollingFrame") then
				Function.ModernList(Child, 2, 3.1, nil, nil, true)
			end
		end
		table.insert(AllConnect, GUIObject.Catalog_3.ChildAdded:Connect(function(Child)
			if Child:IsA("ScrollingFrame") then
				task.defer(Function.ModernList, Child, 2, 3.1, nil, nil, true)
			end
		end))

		-- botões fixos, campos e abas
		for _, Obj in ipairs(GUIObject.MainFrame:GetDescendants()) do
			if Obj:IsA("Frame") and not Obj:FindFirstAncestorOfClass("ScrollingFrame") then
				local Ok, Err = pcall(Function.ModernStyle, Obj)
				if not Ok then warn("[RoC] estilo:", Obj:GetFullName(), Err) end
			elseif Obj:IsA("TextBox") and Obj:FindFirstChildOfClass("UIGradient") and not Obj:FindFirstAncestorOfClass("ScrollingFrame") then
				pcall(Function.ModernInput, Obj)
			end
		end

		local Ok, Err = pcall(Function.ModernExtras)
		if not Ok then warn("[RoC] extras:", Err) end

		-- encaixe perfeito dentro de cada página
		for _, Page in ipairs(GUIObject.PageFrame:GetChildren()) do
			if Page:IsA("GuiObject") then
				Function.ModernFitPage(Page)
			end
		end
	end

	-- botão pequeno com degrau 3D (usado nos cartões da aba Body). Fora do padrão "frame + botão" de propósito.
	function Function.MiniButton(Parent, Name, Text, Anchor, Position, Size, OnClick)
		local Theme = Function.MenuTheme
		local Base = Instance.new("Frame")
		Base.Name = Name .. "Base"
		Base.AnchorPoint = Anchor
		Base.Position = Position
		Base.Size = Size
		Base.BackgroundColor3 = Theme.Edge
		Base.BorderSizePixel = 0
		Base.ZIndex = 6
		Base.Parent = Parent
		local BaseCorner = Instance.new("UICorner")
		BaseCorner.CornerRadius = UDim.new(0, 5)
		BaseCorner.Parent = Base

		local Button = Instance.new("TextButton")
		Button.Name = Name
		Button.AutoButtonColor = false
		Button.BackgroundColor3 = Theme.Panel
		Button.BorderSizePixel = 0
		Button.Size = UDim2.new(1, 0, 1, -2)
		Button.Font = Enum.Font.GothamBold
		Button.Text = Text
		Button.TextColor3 = Theme.Soft
		Button.TextScaled = true
		Button.ZIndex = 7
		Button.Parent = Base
		local ButtonCorner = Instance.new("UICorner")
		ButtonCorner.CornerRadius = UDim.new(0, 5)
		ButtonCorner.Parent = Button
		local ButtonStroke = Instance.new("UIStroke")
		ButtonStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
		ButtonStroke.Color = Theme.Accent
		ButtonStroke.Thickness = 1
		ButtonStroke.Transparency = 0.7
		ButtonStroke.Parent = Button
		local ButtonLimit = Instance.new("UITextSizeConstraint")
		ButtonLimit.MaxTextSize = 11
		ButtonLimit.MinTextSize = 5
		ButtonLimit.Parent = Button
		local ButtonPad = Instance.new("UIPadding")
		ButtonPad.PaddingTop = UDim.new(0.12, 0)
		ButtonPad.PaddingBottom = UDim.new(0.12, 0)
		ButtonPad.PaddingLeft = UDim.new(0.08, 0)
		ButtonPad.PaddingRight = UDim.new(0.08, 0)
		ButtonPad.Parent = Button

		local function Fade(Color)
			TS:Create(Button, TweenInfo.new(0.12), {BackgroundColor3 = Color}):Play()
		end
		table.insert(AllConnect, Button.MouseEnter:Connect(function()
			Fade(Theme.Panel:Lerp(Theme.Accent, 0.28))
		end))
		table.insert(AllConnect, Button.MouseLeave:Connect(function()
			Fade(Theme.Panel)
			Button.Position = UDim2.new(0, 0, 0, 0)
		end))
		table.insert(AllConnect, Button.InputBegan:Connect(function(Input)
			local Type = Input.UserInputType
			if Type == Enum.UserInputType.MouseButton1 or Type == Enum.UserInputType.Touch then
				Button.Position = UDim2.new(0, 0, 0, 2)
			end
		end))
		table.insert(AllConnect, Button.InputEnded:Connect(function(Input)
			local Type = Input.UserInputType
			if Type == Enum.UserInputType.MouseButton1 or Type == Enum.UserInputType.Touch then
				Button.Position = UDim2.new(0, 0, 0, 0)
			end
		end))
		table.insert(AllConnect, Button.MouseButton1Click:Connect(function()
			OnClick(Button)
		end))
		return Button, Base
	end

