	-- cada grupo vira uma categoria do TypePicker (submenu com preview 3D, igual Breasts/Butt/Legs...).
	-- Focus/Dist/Height/Side = camera do preview. NAO calibrado no jogo: se o enquadramento ficar ruim, ajuste so aqui.
	-- Under = grupos cujo Option atual aparece por baixo no preview (o Extra e uma camada por cima do Type).
	do
		local TP = Function.TypePicker
		local Views = {
			Cock = {Title = "COCK SET", Focus = Vector3.new(0, -1, -0.6), Dist = 3.6, Height = 0.3},
			CockExtra = {Title = "COCK EXTRA", Focus = Vector3.new(0, -1, -0.6), Dist = 3.6, Height = 0.3, Under = {"Cock"}},
			Pussy = {Title = "PUSSY SET", Focus = Vector3.new(0, -1, -0.4), Dist = 3.4, Height = 0.3, GhostLegs = true},
			PussyExtra = {Title = "PUSSY EXTRA", Focus = Vector3.new(0, -1, -0.4), Dist = 3.4, Height = 0.3, GhostLegs = true, Under = {"Pussy"}},
		}
		for Group, View in pairs(Views) do
			local Names = {}
			for Index, Option in ipairs(Function.BodyGenitals[Group].Options) do
				Names[Index] = Option.Name
			end
			TP.Names[Group] = Names
			TP.Categories[Group] = {Group = Group, Max = #Names, Title = View.Title, Focus = View.Focus, Dist = View.Dist,
				Height = View.Height, Side = -1, Under = View.Under, GhostLegs = View.GhostLegs}
		end
	end

	function Function.IsBodyGenital(Name)
		for _, Info in pairs(Function.BodyGenitals) do
			for _, Option in ipairs(Info.Options) do
				if Option.Clothes == Name then
					return true
				end
			end
		end
		return false
	end

	-- indice do Option equipado agora (1 = None)
	function Function.BodyGenitalCurrent(Group)
		local Info = Function.BodyGenitals[Group]
		local PData = PlayerData[SelectPlayer]
		if Info and PData then
			for Index, Option in ipairs(Info.Options) do
				if Option.Clothes and table.find(PData.CurrentClothes, Option.Clothes) then
					return Index
				end
			end
		end
		return 1
	end

	function Function.BodyGenitalLabel(Group)
		local Info = Function.BodyGenitals[Group]
		return Info.Label .. ": " .. Info.Options[Function.BodyGenitalCurrent(Group)].Name
	end

	-- equipa o Option (1 = None desequipa). Mesma limpeza/equip do botao da lista Clothes.
	function Function.BodyGenitalSet(Group, Index)
		local Info = Function.BodyGenitals[Group]
		local PData = PlayerData[SelectPlayer]
		local Option = Info and Info.Options[Index]
		if not (PData and Option) then return end

		for _, Other in ipairs(Info.Options) do
			local Name = Other.Clothes
			if Name then
				local Found = table.find(PData.CurrentClothes, Name)
				while Found do
					table.remove(PData.CurrentClothes, Found)
					Found = table.find(PData.CurrentClothes, Name)
				end
				if PData.ClothesXform then
					PData.ClothesXform[Name] = nil
				end
				if PData.ClothesRecolor then
					PData.ClothesRecolor[Name] = nil
				end
				if PData.ClothesMesh then
					PData.ClothesMesh[Name] = nil
				end
			end
		end

		local Name = Option.Clothes
		if Name then
			local Item = Clothes[Name]
			if not Item then
				warn("[RoC] Body " .. Group .. ": roupa '" .. Name .. "' nao existe na tabela Clothes.")
			else
				table.insert(PData.CurrentClothes, Name)

				if Item.Weld then
					Function.RecolorInitSlots(SelectPlayer, Name)

					if Item.Blacklist then
						for _, Blocked in pairs(Item.Blacklist) do
							local At = table.find(PData.CurrentClothes, Blocked)
							if At then
								table.remove(PData.CurrentClothes, At)
							end
						end
					end

					if Item.HP and PData.ClothesHP then
						if Item.HP == 1 then
							PData.ClothesHP[Name] = {["HP"] = "TopHP", ["Inverse"] = false}
						elseif Item.HP == 2 then
							PData.ClothesHP[Name] = {["HP"] = "BottomHP", ["Inverse"] = false}
						elseif Item.HP == 3 then
							PData.ClothesHP[Name] = {["HP"] = "TopHP", ["Inverse"] = true}
						elseif Item.HP == 4 then
							PData.ClothesHP[Name] = {["HP"] = "BottomHP", ["Inverse"] = true}
						elseif Item.HP == 0 then
							PData.ClothesHP[Name] = nil
						else
							PData.ClothesHP[Name] = {["HP"] = Item.HP, ["Inverse"] = false}
						end
					end
				end
			end
		end

		Function.GUIUpdate()
	end

	function Function.BodyGenitalCycle(Group)
		local Info = Function.BodyGenitals[Group]
		if not Info then return end
		Function.BodyGenitalSet(Group, Function.BodyGenitalCurrent(Group) % #Info.Options + 1)
	end

