			{Title = "BREASTS", Cat = "danger", Slider = GUIObject.BreastsScaleFrame, Types = {GUIObject.BreastsTypeFrame},
				Reset = {BreastsScale = 1, BreastsType = 1}},
			{Title = "BUTT", Cat = "amber", Slider = GUIObject.ButtsScaleFrame, Types = {GUIObject.ButtTypeFrame},
				Reset = {ButtsScale = 1, ButtType = 1}},
			{Title = "LEGS", Cat = "mint", Slider = GUIObject.LegsScaleFrame, Types = {GUIObject.LegsTypeFrame},
				Reset = {LegsScale = 1, LegsType = 1}},
			{Title = "TORSO & ARMS", Cat = "accent", Types = {GUIObject.TorsoTypeFrame, GUIObject.ArmTypeFrame},
				Reset = {TorsoType = 1, ArmType = 1}},
			-- Stack = true: o cartao fica abaixo da dobra da pagina, entao entra na pilha com scroll (atributo StackRow)
			{Title = "COCK", Cat = "danger", Slider = GUIObject.CockScaleFrame, Types = {GUIObject.CockTypeFrame, GUIObject.CockExtraTypeFrame}, Stack = true, Height = 0.29,
				Reset = {CockScale = 1}, OnReset = function()
					Function.BodyGenitalSet("Cock", 1)
					Function.BodyGenitalSet("CockExtra", 1)
				end},
			{Title = "PUSSY", Cat = "amber", Types = {GUIObject.PussyTypeFrame, GUIObject.PussyExtraTypeFrame}, Stack = true,
				Reset = {}, OnReset = function()
					Function.BodyGenitalSet("Pussy", 1)
					Function.BodyGenitalSet("PussyExtra", 1)
				end},
		}

		local CardHeight = 0.211
		local FirstY, Gap = 0.08, 0.006
		local NextY = FirstY
		local AllReset = {}

		for Index, Info in ipairs(Cards) do
			for Key, Value in pairs(Info.Reset) do
				AllReset[Key] = Value
			end
			local H = Info.Height or CardHeight
			local Y = NextY
			NextY = NextY + H + Gap
			local Forced = Info.Stack or (Y + H > 1) -- passou da dobra da pagina: entra na pilha com scroll
			local Cat = Theme.Categories[Info.Cat]

			local Card = Instance.new("Frame")
			Card.Name = "BodyCard" .. Index
			Card.AnchorPoint = Vector2.new(0.5, 0)
			Card.Position = UDim2.new(0.5, 0, Y, 0)
			local K = CardHeight / H -- cartao mais alto: titulo e RESET mantem a mesma altura em pixels
			Card.Size = UDim2.new(0.94, 0, H, 0)
			Card.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
			Card.BorderSizePixel = 0
			Card.Active = false
			Card.ZIndex = 0
			Card.Parent = Page
			if Forced then
				Card:SetAttribute("StackRow", true)
			end
			local CardCorner = Instance.new("UICorner")
			CardCorner.CornerRadius = UDim.new(0, Theme.Style.Radius)
			CardCorner.Parent = Card
			local CardGradient = Instance.new("UIGradient")
