			CardGradient.Rotation = 90
			CardGradient.Parent = Card
			local CardStroke = Instance.new("UIStroke")
			CardStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
			CardStroke.Color = Cat.Stroke
			CardStroke.Thickness = 1
			CardStroke.Transparency = 0.65
			CardStroke.Parent = Card

			local Dot = Instance.new("Frame")
			Dot.Name = "CardDot"
			Dot.AnchorPoint = Vector2.new(0, 0.5)
			Dot.Position = UDim2.new(0.05, 0, 0.156 * K, 0)
			Dot.Size = UDim2.fromOffset(6, 6)
			Dot.BackgroundColor3 = Cat.Stroke
			Dot.BorderSizePixel = 0
			Dot.Parent = Card
			local DotCorner = Instance.new("UICorner")
			DotCorner.CornerRadius = UDim.new(1, 0)
			DotCorner.Parent = Dot

			local Title = Instance.new("TextLabel")
			Title.Name = "CardTitle"
			Title.BackgroundTransparency = 1
			Title.AnchorPoint = Vector2.new(0, 0.5)
			Title.Position = UDim2.new(0.05, 11, 0.156 * K, 0)
			Title.Size = UDim2.new(0.5, 0, 0.2 * K, 0)
			Title.Font = Enum.Font.GothamBold
			Title.Text = Info.Title
			Title.TextColor3 = Theme.Soft
			Title.TextScaled = true
			Title.TextXAlignment = Enum.TextXAlignment.Left
			Title.Parent = Card
			local TitleLimit = Instance.new("UITextSizeConstraint")
			TitleLimit.MaxTextSize = 11
			TitleLimit.MinTextSize = 5
			TitleLimit.Parent = Title

			local Values = Info.Reset
			Function.MiniButton(Card, "CardReset", "RESET", Vector2.new(1, 0.5), UDim2.new(0.95, 0, 0.156 * K, 0),
				UDim2.new(0.26, 0, 0.2 * K, 0), function(Button)
					ResetKeys(Values)
					if Info.OnReset then
						Info.OnReset()
					end
					Flash(Button)
				end)

			-- posiciona os itens originais dentro do cartão (nomes, eventos e lógica não mudam)
			local Rows = {}
