				table.insert(Rows, Info.Slider)
			end
			for _, Frame in ipairs(Info.Types) do
				table.insert(Rows, Frame)
			end
			for Row, Frame in ipairs(Rows) do
				Frame.Parent = Page
				Frame.AnchorPoint = Vector2.new(0.5, 0)
				Frame.Position = UDim2.new(0.5, 0, Y + 0.062 + (Row - 1) * 0.074, 0)
				Frame.Size = UDim2.new(0.84, 0, 0.0646399707, 0)
				if Forced then
					Frame:SetAttribute("StackRow", true)
