	-- ===================================================================================== --
	-- // [v26] PILHA AUTOMATICA COM SCROLL: paginas Menu, Menu2 e Body // --
	-- Antes cada item tinha Position fixa em escala (y = 0.025, 0.11, ...), entao qualquer item novo caia em cima
	-- de outro. Agora cada pagina vira um ScrollingFrame ("AutoScroll") com UIListLayout:
	--  * itens que estavam lado a lado ou sobrepostos na vertical (ex.: seletor do boneco + 3 botoes, Body Part
	--    Physics + SmartBones Physics, cartao do Body com seus itens) formam uma "faixa" (StackBand) que mantem o
	--    layout relativo original; as faixas sao empilhadas de cima para baixo;
	--  * a altura das faixas acompanha a pagina (minimo de 470px de referencia, ~30px por linha);
	--  * o que passar da altura da pagina vira scroll (AutomaticCanvasSize).
	-- Para adicionar um item novo: Function.StackAdd(GUIObject.Menu2, MeuFrame) -> entra no fim, sem sobrepor nada.
	-- (opcional: Function.StackAdd(Pagina, Frame, LayoutOrder, AlturaEmEscala)).
	-- Itens criados no codigo ANTES do ApplyAutoStack podem ficar com Position fora da pagina (y > 1) e o atributo
	-- StackRow = true: eles entram na pilha na ordem do Y.
	-- ===================================================================================== --
	Function.Stack = {Pages = {}, BasePx = 470, GapPx = 6, PadPx = 8}

	function Function.StackBandPx(Page, Scale)
		local H = Page.AbsoluteSize.Y
		return math.max(10, math.floor(Scale * math.max(H, Function.Stack.BasePx)))
	end

	-- esconde a faixa quando todos os itens dela estao invisiveis (o UIListLayout ignora o que esta invisivel)
	function Function.StackWatch(Band, Child)
		local function Sync()
			local Any = false
			for _, C in ipairs(Band:GetChildren()) do
				if C:IsA("GuiObject") and C.Visible then
					Any = true
					break
				end
			end
			Band.Visible = Any
		end
		table.insert(AllConnect, Child:GetPropertyChangedSignal("Visible"):Connect(Sync))
		Sync()
	end

	function Function.StackBand(Page, Order, Scale)
		local State = Function.Stack.Pages[Page]
		local Band = Instance.new("Frame")
		Band.Name = "StackBand" .. tostring(Order)
		Band.BackgroundTransparency = 1
		Band.BorderSizePixel = 0
		Band.LayoutOrder = Order
		Band.ClipsDescendants = false
		Band.Size = UDim2.new(1, 0, 0, Function.StackBandPx(Page, Scale))
		Band.Parent = State.Scroll
		table.insert(State.Bands, {Frame = Band, Scale = Scale})
		return Band
	end

	function Function.StackPage(Page)
		if not Page or Function.Stack.Pages[Page] then return end
		local Theme = Function.MenuTheme
		local Stk = Function.Stack

		-- 1) le os itens soltos da pagina (posicao/tamanho originais) e a faixa vertical de cada um
		local Items = {}
		for _, Obj in ipairs(Page:GetChildren()) do
			if Obj:IsA("GuiObject") then
				local Pos, Size = Obj:GetAttribute("ModernPos"), Obj:GetAttribute("ModernSize")
				if typeof(Pos) ~= "UDim2" then Pos = Obj.Position end
				if typeof(Size) ~= "UDim2" then Size = Obj.Size end
				local H = Size.Y.Scale
				if H <= 0 then H = 0.0646399707 end
				local Y0 = Pos.Y.Scale - Obj.AnchorPoint.Y * H
				local CenterY = Y0 + H / 2
				local CenterX = Pos.X.Scale
				local Forced = Obj:GetAttribute("StackRow") == true
				-- fora da pagina de proposito (escondido) = nao mexe, a nao ser que seja linha nova (StackRow)
				if Forced or (CenterY >= 0 and CenterY <= 1 and CenterX >= 0 and CenterX <= 1) then
					table.insert(Items, {Obj = Obj, Pos = Pos, Size = Size, Y0 = Y0, Y1 = Y0 + H, X = Pos.X.Scale})
				end
			end
		end
		table.sort(Items, function(A, B)
			if A.Y0 ~= B.Y0 then return A.Y0 < B.Y0 end
			if A.X ~= B.X then return A.X < B.X end
			return A.Obj.Name < B.Obj.Name
		end)

		-- 2) agrupa em faixas: quem se sobrepoe na vertical fica na mesma faixa
		local Groups = {}
		for _, It in ipairs(Items) do
			local Last = Groups[#Groups]
			if Last and It.Y0 < Last.Y1 - 0.001 then
				table.insert(Last.Items, It)
				Last.Y1 = math.max(Last.Y1, It.Y1)
			else
				table.insert(Groups, {Items = {It}, Y0 = It.Y0, Y1 = It.Y1})
			end
		end

		-- 3) scroll + lista vertical
		local Scroll = Instance.new("ScrollingFrame")
		Scroll.Name = "AutoScroll"
		Scroll.AnchorPoint = Vector2.new(0, 0)
		Scroll.Position = UDim2.new(0, 0, 0, 0)
		Scroll.Size = UDim2.new(1, 0, 1, 0)
		Scroll.BackgroundTransparency = 1
		Scroll.BorderSizePixel = 0
		Scroll.ClipsDescendants = true
		Scroll.ScrollBarThickness = 4
		Scroll.ScrollBarImageColor3 = Theme.Accent
		Scroll.ScrollingDirection = Enum.ScrollingDirection.Y
		Scroll.ElasticBehavior = Enum.ElasticBehavior.WhenScrollable
		Scroll.VerticalScrollBarInset = Enum.ScrollBarInset.ScrollBar
		Scroll.CanvasSize = UDim2.new(0, 0, 0, 0)
		Scroll.AutomaticCanvasSize = Enum.AutomaticSize.Y
		Scroll.BottomImage = "rbxassetid://5946093983"
		Scroll.TopImage = "rbxassetid://5946093983"
		Scroll.MidImage = "rbxassetid://5946093983"
		Scroll.Parent = Page

		local Pad = Instance.new("UIPadding")
		Pad.PaddingTop = UDim.new(0, Stk.PadPx)
		Pad.PaddingBottom = UDim.new(0, Stk.PadPx + 6)
		Pad.PaddingLeft = UDim.new(0, 0)
		Pad.PaddingRight = UDim.new(0, 6)
		Pad.Parent = Scroll

		local List = Instance.new("UIListLayout")
		List.FillDirection = Enum.FillDirection.Vertical
		List.HorizontalAlignment = Enum.HorizontalAlignment.Center
		List.SortOrder = Enum.SortOrder.LayoutOrder
		List.Padding = UDim.new(0, Stk.GapPx)
		List.Parent = Scroll

		local State = {Scroll = Scroll, Bands = {}}
		Stk.Pages[Page] = State

		-- 4) uma faixa por grupo, itens com posicao relativa a faixa
		for Index, Group in ipairs(Groups) do
			local Scale = math.max(Group.Y1 - Group.Y0, 0.02)
			local Band = Function.StackBand(Page, Index, Scale)
			for _, It in ipairs(Group.Items) do
				local Obj = It.Obj
				Obj.Position = UDim2.new(It.Pos.X.Scale, It.Pos.X.Offset, (It.Pos.Y.Scale - Group.Y0) / Scale, It.Pos.Y.Offset)
				if It.Size.Y.Scale > 0 then
					Obj.Size = UDim2.new(It.Size.X.Scale, It.Size.X.Offset, It.Size.Y.Scale / Scale, It.Size.Y.Offset)
				else
					Obj.Size = It.Size
				end
				Obj.Parent = Band
				Function.StackWatch(Band, Obj)
			end
		end

		-- 5) a altura das faixas acompanha a pagina
		table.insert(AllConnect, Page:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
			for _, B in ipairs(State.Bands) do
				if B.Frame.Parent then
					B.Frame.Size = UDim2.new(1, 0, 0, Function.StackBandPx(Page, B.Scale))
				end
			end
		end))
	end

	-- Adiciona um frame novo no fim da pilha da pagina (nada fica um em cima do outro).
	function Function.StackAdd(Page, Frame, Order, Scale)
		local State = Function.Stack.Pages[Page]
		if not State then
			Frame.Parent = Page
			return Frame
		end
		Scale = Scale or 0.0646399707
		Order = Order or (#State.Bands + 1)
		local Band = Function.StackBand(Page, Order, Scale)
		Frame.AnchorPoint = Vector2.new(0.5, 0)
		Frame.Position = UDim2.new(0.5, 0, 0, 0)
		Frame.Size = UDim2.new(0.891309202, 0, 1, 0)
		Frame.Parent = Band
		Function.StackWatch(Band, Frame)
		return Frame
	end

	function Function.ApplyAutoStack()
		for _, Page in ipairs({GUIObject.Menu, GUIObject.Menu2, GUIObject.Menu3}) do
			local Ok, Err = pcall(Function.StackPage, Page)
			if not Ok then warn("[RoC] pilha:", Page and Page.Name, Err) end
		end
	end

	-- Linhas do SmartBone na aba do Menu2: titulo + RESET SB + 4 sliders (entram na pilha na ordem do Y).
