	-- aba Body: scroll vertical. Roda depois do ApplyModernUI para não perder o estilo
	-- (o ModernStyle ignora frames dentro de ScrollingFrame). Todo o conteúdo vai para um
	-- canvas com a mesma proporção da página, então nada se sobrepõe; o canvas nunca fica
	-- menor que MinCanvasPx, e o que passar da altura da página vira scroll.
	function Function.ApplyBodyScroll()
		local Theme = Function.MenuTheme
		local Page = GUIObject.Menu3
		if not Page then return end
		if Page:FindFirstChild("BodyScroll") then return end

		local MinCanvasPx = 470 -- linha = 0.0646 * altura -> ~30px mínimo
		local BarPx = 4

		local Scroll = Instance.new("ScrollingFrame")
		Scroll.Name = "BodyScroll"
		Scroll.AnchorPoint = Vector2.new(0, 0)
		Scroll.Position = UDim2.new(0, 0, 0, 0)
		Scroll.Size = UDim2.new(1, 0, 1, 0)
		Scroll.BackgroundTransparency = 1
		Scroll.BorderSizePixel = 0
		Scroll.ClipsDescendants = true
		Scroll.ScrollBarThickness = BarPx
		Scroll.ScrollBarImageColor3 = Theme.Accent
		Scroll.ScrollingDirection = Enum.ScrollingDirection.Y
		Scroll.ElasticBehavior = Enum.ElasticBehavior.WhenScrollable
		Scroll.VerticalScrollBarInset = Enum.ScrollBarInset.ScrollBar
		Scroll.AutomaticCanvasSize = Enum.AutomaticCanvasSize.None
		Scroll.CanvasSize = UDim2.new(0, 0, 0, MinCanvasPx)
		Scroll.BottomImage = "rbxassetid://5946093983"
		Scroll.TopImage = "rbxassetid://5946093983"
		Scroll.MidImage = "rbxassetid://5946093983"

		local Canvas = Instance.new("Frame")
		Canvas.Name = "BodyCanvas"
		Canvas.BackgroundTransparency = 1
		Canvas.BorderSizePixel = 0
		Canvas.Position = UDim2.new(0, 0, 0, 0)
		Canvas.Size = UDim2.new(1, 0, 0, MinCanvasPx)
		Canvas.ClipsDescendants = false
		Canvas.Parent = Scroll

		-- move tudo da página para o canvas, voltando à posição original do layout
		-- (o ModernFitPage aplica offsets em pixel calculados para a página, não para o canvas)
		for _, Obj in ipairs(Page:GetChildren()) do
			if Obj:IsA("GuiObject") then
				local Pos, Size = Obj:GetAttribute("ModernPos"), Obj:GetAttribute("ModernSize")
				if typeof(Pos) == "UDim2" then Obj.Position = Pos end
				if typeof(Size) == "UDim2" then Obj.Size = Size end
				Obj.Parent = Canvas
			end
		end
		Scroll.Parent = Page

		local function Resize()
			local H = Page.AbsoluteSize.Y
			if H <= 0 then return end
			local CanvasPx = math.max(math.floor(H), MinCanvasPx)
			Canvas.Size = UDim2.new(1, 0, 0, CanvasPx)
			Scroll.CanvasSize = UDim2.new(0, 0, 0, CanvasPx)
			local MaxY = math.max(0, CanvasPx - Scroll.AbsoluteWindowSize.Y)
			if Scroll.CanvasPosition.Y > MaxY then
				Scroll.CanvasPosition = Vector2.new(0, MaxY)
			end
		end
		table.insert(AllConnect, Page:GetPropertyChangedSignal("AbsoluteSize"):Connect(Resize))
		Resize()
	end

	-- aba Options: cartões temáticos com ScrollingFrame interno
	-- v14: SlotPx escalado pela altura real do frame; Header com AnchorPoint correto;
	--      exportBox explicitamente excluído do card Data (foi removido da aba);
	--      UITextSizeConstraint com tamanho legível (MaxTextSize 14); gap maior (8px).
	function Function.ApplyOptionsLayout()
		local Theme = Function.MenuTheme
		local Page  = GUIObject.optionsFrame
		if not Page then return end

		-- Remove qualquer scroll anterior (re-execução segura)
		local prev = Page:FindFirstChild("OptionsScroll")
		if prev then prev:Destroy() end

		-- ── ScrollingFrame que contém todos os cards ──────────────────────
		local Scroll = Instance.new("ScrollingFrame")
		Scroll.Name                  = "OptionsScroll"
		Scroll.AnchorPoint           = Vector2.new(0, 0)
		Scroll.Position              = UDim2.new(0, 0, 0, 0)
		Scroll.Size                  = UDim2.new(1, 0, 1, 0)
		Scroll.BackgroundTransparency = 1
		Scroll.BorderSizePixel       = 0
		Scroll.ScrollBarThickness    = 4
		Scroll.ScrollBarImageColor3  = Theme.Accent
		Scroll.CanvasSize            = UDim2.new(0, 0, 0, 0)
		Scroll.AutomaticCanvasSize   = Enum.AutomaticCanvasSize.Y
		Scroll.ScrollingDirection    = Enum.ScrollingDirection.Y
		Scroll.ElasticBehavior       = Enum.ElasticBehavior.WhenScrollable
		Scroll.BottomImage           = "rbxassetid://5946093983"
		Scroll.TopImage              = "rbxassetid://5946093983"
		Scroll.MidImage              = ""
		Scroll.Parent                = Page

		-- Padding interno do scroll
		local UIPad = Instance.new("UIPadding")
		UIPad.PaddingTop    = UDim.new(0, 8)
		UIPad.PaddingBottom = UDim.new(0, 12)
		UIPad.PaddingLeft   = UDim.new(0, 0)
		UIPad.PaddingRight  = UDim.new(0, 6)  -- espaço para a scrollbar
		UIPad.Parent        = Scroll

		-- UIListLayout empilha header + cards verticalmente, sem sobreposição
		local List = Instance.new("UIListLayout")
		List.FillDirection       = Enum.FillDirection.Vertical
		List.HorizontalAlignment = Enum.HorizontalAlignment.Center
		List.SortOrder           = Enum.SortOrder.LayoutOrder
		List.Padding             = UDim.new(0, 8)
		List.Parent              = Scroll

		-- SlotPx: altura de cada botão em pixels.
		-- Derivado da altura absoluta do Page multiplicada por 0.0646 (proporção original).
		-- Clampado entre 28px (mínimo legível) e 44px (telas grandes).
		-- Page.AbsoluteSize só está disponível após layout, então usamos
		-- o valor de MainFrame que já existe no momento da chamada.
		local rawSlot = math.round(GUIObject.MainFrame.AbsoluteSize.Y * 0.0646)
		local SlotPx  = math.clamp(rawSlot, 30, 46)
		local GapPx   = 8
		local TitlePx = SlotPx + 4   -- título ligeiramente maior que um slot

		-- ── helper: card ──────────────────────────────────────────────────
		local CardOrder = 0
		local function MakeCard(Name, Cat, Rows)
			CardOrder += 1
			local C = Theme.Categories[Cat]
			local H = TitlePx + (SlotPx + GapPx) * Rows + GapPx * 2
			local Card = Instance.new("Frame")
			Card.Name             = Name .. "Card"
			Card.LayoutOrder      = CardOrder
			Card.AnchorPoint      = Vector2.new(0.5, 0)
			Card.Size             = UDim2.new(0.94, 0, 0, H)
			Card.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
			Card.BorderSizePixel  = 0
			Card.ClipsDescendants = true
			Card.Parent           = Scroll
			local Crn = Instance.new("UICorner")
			Crn.CornerRadius = UDim.new(0, Theme.Style.Radius)
			Crn.Parent = Card
			local Grad = Instance.new("UIGradient")
			Grad.Color    = ColorSequence.new(C.A, Theme.Deep)
			Grad.Rotation = 90
			Grad.Parent   = Card
			local Strk = Instance.new("UIStroke")
			Strk.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
			Strk.Color           = C.Stroke
			Strk.Thickness       = 1
			Strk.Transparency    = 0.55
			Strk.Parent          = Card
			return Card, C
		end

		-- ── helper: faixa de título do card ──────────────────────────────
		local function MakeTitle(Card, Text, Cat)
			local C = Theme.Categories[Cat]
			-- linha separadora sob o título
			local Sep = Instance.new("Frame")
			Sep.Name              = "CardSep"
			Sep.AnchorPoint       = Vector2.new(0, 0)
			Sep.Position          = UDim2.new(0, 0, 0, TitlePx - 1)
			Sep.Size              = UDim2.new(1, 0, 0, 1)
			Sep.BackgroundColor3  = C.Stroke
			Sep.BackgroundTransparency = 0.7
			Sep.BorderSizePixel   = 0
			Sep.ZIndex            = 3
			Sep.Parent            = Card
			-- dot colorido
			local Dot = Instance.new("Frame")
			Dot.Name             = "CardDot"
			Dot.AnchorPoint      = Vector2.new(0, 0.5)
			Dot.Position         = UDim2.new(0, 12, 0, TitlePx // 2)
			Dot.Size             = UDim2.fromOffset(7, 7)
			Dot.BackgroundColor3 = C.Stroke
			Dot.BorderSizePixel  = 0
			Dot.ZIndex           = 4
			Dot.Parent           = Card
			local DotCrn = Instance.new("UICorner")
			DotCrn.CornerRadius = UDim.new(1, 0)
			DotCrn.Parent = Dot
			-- label do título
			local Lbl = Instance.new("TextLabel")
			Lbl.Name               = "CardTitle"
			Lbl.BackgroundTransparency = 1
			Lbl.AnchorPoint        = Vector2.new(0, 0.5)
			Lbl.Position           = UDim2.new(0, 26, 0, TitlePx // 2)
			Lbl.Size               = UDim2.new(1, -32, 0, TitlePx - 6)
			Lbl.Font               = Enum.Font.GothamBold
			Lbl.Text               = Text
			Lbl.TextColor3         = Theme.Soft
			Lbl.TextScaled         = true
			Lbl.TextXAlignment     = Enum.TextXAlignment.Left
			Lbl.ZIndex             = 4
			Lbl.Parent             = Card
			local Lim = Instance.new("UITextSizeConstraint")
			Lim.MaxTextSize = 14
			Lim.MinTextSize = 8
			Lim.Parent = Lbl
		end

		-- ── helper: encaixa um frame existente no card ────────────────────
		-- Row ≥ 1. Posição em offset absoluto abaixo da faixa de título.
		-- Garante que o filho é re-parented para o card correto e não fica
		-- em nenhum parent anterior (evita frames flutuando sobre optionsFrame).
		local function Dock(Frame, Card, Row, KeepChildren)
			if not Frame then return end
			local Y = TitlePx + GapPx + (Row - 1) * (SlotPx + GapPx)
			Frame.Parent      = Card
			Frame.AnchorPoint = Vector2.new(0.5, 0)
			Frame.Position    = UDim2.new(0.5, 0, 0, Y)
			Frame.Size        = UDim2.new(0.90, 0, 0, SlotPx)
			Frame.ZIndex      = 2
			-- KeepChildren: o frame tem vários filhos com posição própria (ex.: Menu Size  [-]  texto  [+]);
			-- só limita o tamanho do texto, sem esticar cada filho para o frame inteiro
			if KeepChildren then
				for _, child in ipairs(Frame:GetChildren()) do
					if child:IsA("TextButton") or child:IsA("TextLabel") then
						local lim = child:FindFirstChildOfClass("UITextSizeConstraint") or Instance.new("UITextSizeConstraint")
						lim.MaxTextSize = 15
						lim.MinTextSize = 9
						lim.Parent = child
					end
				end
				return
			end
			-- garante que o botão filho (se existir) preenche o frame e tem texto legível
			for _, child in ipairs(Frame:GetChildren()) do
				if child:IsA("TextButton") or child:IsA("TextLabel") or child:IsA("TextBox") then
					child.Size     = UDim2.new(1, 0, 1, 0)
					child.TextScaled = true
					local lim = child:FindFirstChildOfClass("UITextSizeConstraint")
					if not lim then
						lim = Instance.new("UITextSizeConstraint")
						lim.Parent = child
					end
					lim.MaxTextSize = 15
					lim.MinTextSize = 9
				end
			end
		end

		-- ── HEADER global da aba ──────────────────────────────────────────
		local Header = Instance.new("TextLabel")
		Header.Name               = "OptionsHeader"
		Header.LayoutOrder        = 0
		Header.AnchorPoint        = Vector2.new(0.5, 0)   -- alinhado com os cards
		Header.BackgroundTransparency = 1
		Header.Size               = UDim2.new(0.94, 0, 0, math.max(20, SlotPx - 4))
		Header.Font               = Enum.Font.GothamBold
		Header.Text               = "OPTIONS"
		Header.TextColor3         = Theme.Mint
		Header.TextScaled         = true
		Header.TextXAlignment     = Enum.TextXAlignment.Left
		Header.Parent             = Scroll
		local HeaderLim = Instance.new("UITextSizeConstraint")
		HeaderLim.MaxTextSize = 16
		HeaderLim.MinTextSize = 9
		HeaderLim.Parent = Header

		-- ── CARD: LOADUP ─────────────────────────────────────────────────
		--   Save All | Close UI on Loadup | Execute on Loadup | FPerson Loadup
		local LCard = MakeCard("Loadup", "mint", 4)
		MakeTitle(LCard, "LOADUP", "mint")
		Dock(GUIObject.saveAllFrame,  LCard, 1)
		Dock(GUIObject.closeOption,   LCard, 2)
		Dock(GUIObject.executeOption, LCard, 3)
		Dock(GUIObject.FPersonLoadup, LCard, 4)

		-- ── CARD: DANGER ZONE ────────────────────────────────────────────
		--   Clear Saved | Destroy (fecha o script)
		local ZCard = MakeCard("DangerZone", "danger", 2)
		MakeTitle(ZCard, "DANGER ZONE", "danger")
		Dock(GUIObject.clearSavedFrame, ZCard, 1)
		Dock(GUIObject.DestroyFrame,    ZCard, 2)

		-- ── CARD: KEYBIND ────────────────────────────────────────────────
		--   Keybind (tecla de toggle do menu)
		local KCard = MakeCard("Keybind", "amber", 1)
		MakeTitle(KCard, "KEYBIND", "amber")
		Dock(GUIObject.KeybindFrame, KCard, 1)

		-- ── CARD: MENU SIZE ──────────────────────────────────────────────
		--   [-]  Menu Size: 100%  [+]  (o frame é criado na montagem das opções, solto na página)
		local MCard = MakeCard("MenuSize", "neutral", 1)
		MakeTitle(MCard, "MENU SIZE", "neutral")
		Dock(Page:FindFirstChild("MenuSizeFrame", true), MCard, 1, true)
	end

	-- câmera do espelho: Yaw inicial = 3/4 frontal; AUTO gira devagar; < > giram de 45 em 45 graus
	Function.MirrorCam = {Yaw = math.pi - 0.55, Target = nil, Auto = true, Dist = nil, Clock = nil}

	function Function.ApplyMenuLayout()
		local Theme = Function.MenuTheme

		-- abas viram uma fileira no topo, cobrindo espelho + conteúdo
		local Tabs = {}
		for _, Tab in ipairs(GUIObject.ButtonFrame:GetChildren()) do
			if Tab:IsA("Frame") then
				table.insert(Tabs, Tab)
			end
		end
		local Count = math.max(#Tabs, 1)
		GUIObject.ButtonFrame.Position = UDim2.new(-0.88, 0, -0.075, 0)
		GUIObject.ButtonFrame.Size = UDim2.new(1.88, 0, 0.062, 0)
		local List = GUIObject.UIListLayout
		List.FillDirection = Enum.FillDirection.Horizontal
