		Corner.Parent = Panel
		local Stroke = Function.UIStrokeCreate(Panel)
		Stroke.Thickness = Theme.Style.PageStroke
		Stroke.Transparency = Theme.Style.PageStrokeT

		local View = GUIObject.ViewportFrame
