			Button.ZIndex = 7
			Button.Parent = Base
			local ButtonCorner = Instance.new("UICorner")
			ButtonCorner.CornerRadius = UDim.new(0, 6)
			ButtonCorner.Parent = Button
			local ButtonStroke = Instance.new("UIStroke")
			ButtonStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
			ButtonStroke.Color = Theme.Accent
			ButtonStroke.Thickness = 1
			ButtonStroke.Transparency = 0.7
			ButtonStroke.Parent = Button
			local ButtonLimit = Instance.new("UITextSizeConstraint")
			ButtonLimit.MaxTextSize = 11
			ButtonLimit.MinTextSize = 5
			ButtonLimit.Parent = Button
			local ButtonPad = Instance.new("UIPadding")
			ButtonPad.PaddingTop = UDim.new(0.15, 0)
			ButtonPad.PaddingBottom = UDim.new(0.15, 0)
			ButtonPad.PaddingLeft = UDim.new(0.1, 0)
			ButtonPad.PaddingRight = UDim.new(0.1, 0)
			ButtonPad.Parent = Button

			local function Fade(Color)
				TS:Create(Button, TweenInfo.new(0.12), {BackgroundColor3 = Color}):Play()
			end
			table.insert(AllConnect, Button.MouseEnter:Connect(function()
				Fade(Theme.Panel:Lerp(Theme.Accent, 0.28))
			end))
			table.insert(AllConnect, Button.MouseLeave:Connect(function()
				Fade(Theme.Panel)
				Button.Position = UDim2.new(0, 0, 0, 0)
			end))
			table.insert(AllConnect, Button.InputBegan:Connect(function(Input)
				local Type = Input.UserInputType
				if Type == Enum.UserInputType.MouseButton1 or Type == Enum.UserInputType.Touch then
					Button.Position = UDim2.new(0, 0, 0, 2)
				end
			end))
			table.insert(AllConnect, Button.InputEnded:Connect(function(Input)
				local Type = Input.UserInputType
				if Type == Enum.UserInputType.MouseButton1 or Type == Enum.UserInputType.Touch then
					Button.Position = UDim2.new(0, 0, 0, 0)
				end
			end))
			table.insert(AllConnect, Button.MouseButton1Click:Connect(OnClick))
			return Button
		end

		local function Turn(Step)
			Cam.Auto = false
			Cam.Target = (Cam.Target or Cam.Yaw) + Step
			RefreshAuto()
		end
		MirrorButton("MirrorTurnLeft", "<", 0.09, 0.2, function() Turn(-math.pi / 4) end)
		AutoButton = MirrorButton("MirrorAuto", "AUTO", 0.33, 0.34, function()
			Cam.Auto = not Cam.Auto
			Cam.Target = nil
			RefreshAuto()
		end)
		MirrorButton("MirrorTurnRight", ">", 0.71, 0.2, function() Turn(math.pi / 4) end)
		RefreshAuto()
	end

	-- enquadramento automático: o boneco sempre cabe inteiro (altura e largura) e centrado na área livre
	function Function.MirrorCameraStep()
		local Cam = Function.MirrorCam
		local Camera = GUIObject.ViewportCamera
		local View = GUIObject.ViewportFrame
		local Size = View.AbsoluteSize
		if Size.X < 8 or Size.Y < 8 then return end

		local Now = os.clock()
		local Dt = math.clamp(Now - (Cam.Clock or Now), 0, 0.1)
		Cam.Clock = Now

		-- giro: passo suave até o alvo, ou giro lento contínuo no AUTO
		if Cam.Target then
			local Diff = Cam.Target - Cam.Yaw
			Cam.Yaw += Diff * math.min(1, Dt * 9)
			if math.abs(Diff) < 0.004 then
				Cam.Yaw = Cam.Target
				Cam.Target = nil
			end
		elseif Cam.Auto then
			Cam.Yaw += Dt * 0.55
		end
		if not Cam.Target and Cam.Yaw > 8 * math.pi then
			Cam.Yaw -= 4 * math.pi
		end

		local Aspect = Size.X / Size.Y
		local Fov = 26
		Camera.FieldOfView = Fov
		local Tan = math.tan(math.rad(Fov / 2))

		-- medidas do boneco (torso na origem): pés, topo (com folga p/ cabelo e chapéu) e meia-largura (braços)
		local FeetY, TopY, HalfW = -3.0, 2.75, 2.35
		local BandTop, BandBottom = 0.11, 0.84 -- faixa do painel livre entre cabeçalho e controles
		local VisH = (TopY - FeetY) / (BandBottom - BandTop)
		local Want = math.max((VisH / 2) / Tan, HalfW / (Tan * Aspect))
		Cam.Dist = Cam.Dist and (Cam.Dist + (Want - Cam.Dist) * math.min(1, Dt * 8)) or Want
		local Dist = Cam.Dist
		local ActualH = 2 * Dist * Tan

		local CenterY = (TopY + FeetY) / 2
		local TargetY = CenterY + ((BandTop + BandBottom) / 2 - 0.5) * ActualH
		local Target = Vector3.new(0, TargetY, 0)
		local Pos = Target + Vector3.new(math.sin(Cam.Yaw) * Dist, 0, math.cos(Cam.Yaw) * Dist)
		Camera.CFrame = CFrame.lookAt(Pos, Target)
		View.LightDirection = Camera.CFrame:VectorToWorldSpace(Vector3.new(0.45, -0.55, -0.7)).Unit

		local function FracY(Y)
			return 0.5 + (TargetY - Y) / ActualH
		end

		local Decor = Function.MirrorDecor
		if Decor then
			local FeetF = FracY(FeetY)
			local WFrac = 3.1 / (ActualH * Aspect)
			local FloorW = Size.X * WFrac
			if Decor.Floor then
				Decor.Floor.Position = UDim2.fromScale(0.5, FeetF)
				Decor.Floor.Size = UDim2.fromOffset(FloorW, math.max(4, FloorW * 0.26))
			end
			if Decor.FloorGlow then
				Decor.FloorGlow.Position = UDim2.fromScale(0.5, FeetF)
				Decor.FloorGlow.Size = UDim2.fromOffset(FloorW * 1.5, math.max(6, FloorW * 0.42))
			end
			local HaloY = FracY(0.2)
			for _, Halo in ipairs(Decor.Halos) do
				Halo.Position = UDim2.fromScale(0.5, HaloY)
			end
		end

		local Dot = Function.MirrorDot
		local Pulse = Dot and Dot:FindFirstChild("MirrorDotPulse")
		if Pulse then
			Pulse.Scale = 1 + 0.25 * math.sin(Now * 3.2)
		end
	end

	function Function.ButtonCreate(ButtonName, ButtonParent, IsTextbox, TextboxOption)
		local Button = Instance.new("Frame")
		local Button_2

		if IsTextbox == true then
			Button_2 = Instance.new("TextBox")
		else
			Button_2 = Instance.new("TextButton")
		end

		local UIAspectRatioConstraint = Instance.new("UIAspectRatioConstraint")
		local UICorner_2 = Instance.new("UICorner")
		local UIGradient_2 = Instance.new("UIGradient")

		Button.Name = ButtonName
		Button.Parent = ButtonParent
		Button.BackgroundColor3 = Function.MenuTheme.Panel
		Button.BorderColor3 = Color3.fromRGB(0, 0, 0)
		Button.Position = UDim2.new(0.784810185, 0, 0.866666734, 0)
		Button.Size = UDim2.new(0, 200, 0, 50)

		UIAspectRatioConstraint.Parent = Button

		UICorner_2.CornerRadius = UDim.new(0.25, 0)
		UICorner_2.Parent = Button

		Button_2.Parent = Button
		Button_2.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
		Button_2.BackgroundTransparency = 1.000
		Button_2.Size = UDim2.new(1, 0, 1, 0)
		Button_2.Font = Enum.Font.Code
		Button_2.TextColor3 = Color3.fromRGB(255, 255, 255)
		Button_2.TextScaled = true
		Button_2.TextSize = 14.000
		Button_2.TextStrokeTransparency = 0.000
		Button_2.TextWrapped = true

		if IsTextbox and TextboxOption then
			Button_2.ClearTextOnFocus = false
			Button_2.PlaceholderText = TextboxOption.Text
			Button_2.PlaceholderColor3 = TextboxOption.Color
		else
			Button_2.Text = ButtonName
		end

		UIGradient_2.Color = ColorSequence.new{ColorSequenceKeypoint.new(0.00, Color3.fromRGB(168, 168, 168)), ColorSequenceKeypoint.new(1.00, Color3.fromRGB(255, 255, 255))}
		UIGradient_2.Rotation = -90
		UIGradient_2.Parent = Button

		Function.UIStrokeCreate(Button)

		if ButtonName == "nil" then
			Button.LayoutOrder = -1
		end

		return Button
	end

