	-- ====================================================================================
	-- // CATÁLOGO MARKETPLACE // loja com cartões, ícones, pesquisa e Equipar / Desequipar
	-- Os dados continuam em PlayerData[jogador].CatalogAccessory / CatalogTail / CatalogRemove /
	-- CatalogClothes (mesmo formato de antes): Save/Load e presets seguem funcionando.
	-- Abas: Loja (pesquisa) · Equipados (tudo que está no avatar) · Avatar (username, outfit, roupas).
	-- ====================================================================================
	RoCLoad.Step(58, "Carregando loja do catálogo")
	Function.CatalogShop = {
		Base = {},          -- [jogador] = {Key = "user|outfit", Ids = {}, Set = {[id] = true}} (itens do username/outfit)
		Info = {},          -- cache de nome/preço por id
		Pending = {},       -- consultas de GetProductInfo em andamento
		Cards = {},         -- cartões vivos -> função que atualiza o botão Equipar/Desequipar
		Tab = "Loja",
		Category = 1,
		Group = 1,
		-- [v43] grupos do filtro fixo: cada um abre um submenu (rolável) com as categorias (índices de Categories)
		Groups = {
			{"Acessórios", {1, 2, 3, 4, 5, 6, 7, 8, 9}},
			{"Rosto", {10}},
			{"Roupas", {11, 12, 13}},
		},
		Sort = 1,
		Query = "",
		Token = 0,
		ToastToken = 0,
		ApplyToken = 0,
		Sig = "",
		AutoApply = false,
		Built = false,
		Loaded = false,
		Categories = {
			{"Todos", {"Hat", "HairAccessory", "FaceAccessory", "NeckAccessory", "ShoulderAccessory", "FrontAccessory", "BackAccessory", "WaistAccessory"}},
			{"Chapéu", {"Hat"}},
			{"Cabelo", {"HairAccessory"}},
			{"Face", {"FaceAccessory"}},
			{"Pescoço", {"NeckAccessory"}},
			{"Ombros", {"ShoulderAccessory"}},
			{"Frente", {"FrontAccessory"}},
			{"Costas", {"BackAccessory"}},
			{"Cintura", {"WaistAccessory"}},
			-- [v42] novas categorias (nomes alternativos: o Roblox já renomeou esses enums; o que não existir é ignorado)
			{"Rosto Dinâmico", {"DynamicHead"}, {"DynamicHead", "DynamicHeadAvatar"}}, -- 3º campo: tipos de Bundle (cabeças dinâmicas vêm como bundle)
			{"Camisa Classic", {"ClassicShirt", "Shirt"}},
			{"Calça Classic", {"ClassicPants", "Pants"}},
			{"Camiseta Classic", {"ClassicTShirt", "TShirt"}},
		},
		Sorts = {
			{"Auto", nil},
			{"Mais vendidos", "Bestselling"},
			{"Relevância", "Relevance"},
