			{"Maior preço", "PriceHighToLow"},
		},
		ClothNames = {Shirt = "CAM", Pants = "CAL", ShirtGraphic = "TSH", Face = "ROS", Head = "CAB"},
		-- AssetTypeId do Roblox -> slot em CatalogClothes (11 camisa, 12 calça, 2 camiseta, 18 rosto, 17 cabeça, 79 rosto dinâmico)
		ClothTypes = {[11] = "Shirt", [12] = "Pants", [2] = "ShirtGraphic", [18] = "Face", [17] = "Head", [79] = "Head"},
	}

	-- a antiga lista de caixinhas por jogador não existe mais (a loja desenha tudo); mantida só pelos chamadores
	function Function.CatalogAccessoryFrameAdd(Data)
	end

	function Function.CatalogShop.Find(List, Id)
		if typeof(List) ~= "table" then return nil end
		for Index, Value in pairs(List) do
			if tonumber(Value) == Id then
				return Index
			end
		end
		return nil
	end

	function Function.CatalogShop.RemoveAll(List, Id)
		if typeof(List) ~= "table" then return false end
		local Removed = false
		for Index = #List, 1, -1 do
			if tonumber(List[Index]) == Id then
				table.remove(List, Index)
				Removed = true
			end
		end
		return Removed
	end

	-- texto curto de preço (cabe na faixa em cima do ícone pequeno)
	function Function.CatalogShop.PriceText(Info)
		local Theme = Function.MenuTheme
		if Info.Price == nil then
			if Info.OnSale == false or Info.PriceStatus then
				return "Off", Theme.Soft
			end
			return "—", Theme.Soft
		end
		if Info.Price == 0 then
			return "Free", Theme.Mint
		end
		if Info.Price >= 10000 then
			return "R$" .. math.floor(Info.Price / 1000) .. "k", Theme.Amber
		end
		return "R$" .. tostring(Info.Price), Theme.Amber
	end

	-- nome/preço/tipo do item (cache + fila: vários cartões pedindo o mesmo id fazem uma consulta só)
	function Function.CatalogShop.GetInfo(Id, Callback, NeedType)
		local S = Function.CatalogShop
		local Cached = S.Info[Id]
		if Cached and (not NeedType or Cached.AssetTypeId) then
			if Callback then Callback(Cached) end
			return
		end
		if S.Pending[Id] then
			if Callback then table.insert(S.Pending[Id], Callback) end
			return
		end
		S.Pending[Id] = {}
		if Callback then table.insert(S.Pending[Id], Callback) end
		task.spawn(function()
			local Ok, Result = pcall(function()
				return MPS:GetProductInfo(Id)
			end)
			local Info
			if Ok and typeof(Result) == "table" then
				Info = {
					Name = tostring(Result.Name or ("Item " .. Id)),
					Price = Result.PriceInRobux,
					OnSale = Result.IsForSale,
					AssetTypeId = Result.AssetTypeId,
					Creator = Result.Creator and Result.Creator.Name or nil,
				}
				S.Info[Id] = Info
			else
				Info = {Name = "Item " .. Id, Invalid = true}
			end
			local Waiting = S.Pending[Id] or {}
			S.Pending[Id] = nil
			for _, Cb in ipairs(Waiting) do
				pcall(Cb, Info)
			end
		end)
	end

	-- situação do item para o jogador selecionado
	function Function.CatalogShop.State(Id, Name)
		local S = Function.CatalogShop
		Name = Name or SelectPlayer
		local Result = {Equipped = false, Removed = false, Base = false, Manual = false, Tail = false, Cloth = nil}
		local Data = PlayerData[Name]
		if not Data then return Result end
		local Base = S.Base[Name]
		Result.Base = (Base ~= nil and Base.Set[Id] == true)
		Result.Removed = Result.Base and S.Find(Data.CatalogRemove, Id) ~= nil
		Result.Manual = S.Find(Data.CatalogAccessory, Id) ~= nil
		Result.Tail = S.Find(Data.CatalogTail, Id) ~= nil
		for Key in pairs(S.ClothNames) do
			if tonumber(Data.CatalogClothes[Key]) == Id then
				Result.Cloth = Key
			end
		end
		Result.Equipped = (Result.Base and not Result.Removed) or Result.Manual or Result.Tail or Result.Cloth ~= nil
		return Result
	end

	function Function.CatalogShop.Equip(Id)
		local S = Function.CatalogShop
		Id = tonumber(Id)
		local Name = SelectPlayer
		local Data = PlayerData[Name]
		if not Id or not Data then return end

		local State = S.State(Id, Name)
		if State.Removed then
			S.RemoveAll(Data.CatalogRemove, Id) -- era do avatar base e foi tirado: só restaura
			S.Toast("Item restaurado", Function.MenuTheme.Mint)
			S.Changed()
			return
		end
		if State.Equipped then return end

		S.GetInfo(Id, function(Info)
			if Info.Invalid then
				S.Toast("Não consegui carregar o item " .. Id, Function.MenuTheme.Danger)
				return
			end
			if S.State(Id, Name).Equipped then return end
			local Type = Info.AssetTypeId
			local ClothesChanged = false
			if AccessoryType[Type] then
				table.insert(Data.CatalogAccessory, Id)
			elseif S.ClothTypes[Type] then
				Data.CatalogClothes[S.ClothTypes[Type]] = tostring(Id)
				ClothesChanged = true
			else
				S.Toast("\"" .. Info.Name .. "\" não é acessório, roupa Classic, rosto nem cabeça", Function.MenuTheme.Danger)
				return
			end
			S.Toast("Equipado: " .. Info.Name, Function.MenuTheme.Mint)
			if ClothesChanged and Name == SelectPlayer then
				Function.GUIUpdate() -- atualiza as caixas de camisa/calça
			end
			S.Changed()
		end, true)
	end

	function Function.CatalogShop.Unequip(Id)
		local S = Function.CatalogShop
		Id = tonumber(Id)
		local Name = SelectPlayer
		local Data = PlayerData[Name]
		if not Id or not Data then return end

		S.RemoveAll(Data.CatalogAccessory, Id)
		S.RemoveAll(Data.CatalogTail, Id)

		local ClothesChanged = false
		for Key in pairs(S.ClothNames) do
			if tonumber(Data.CatalogClothes[Key]) == Id then
				Data.CatalogClothes[Key] = ""
				ClothesChanged = true
			end
		end

		local Base = S.Base[Name]
		if Base and Base.Set[Id] and not S.Find(Data.CatalogRemove, Id) then
			table.insert(Data.CatalogRemove, Id) -- vem do username/outfit: marca como removido (dá pra restaurar)
		end

		S.Toast("Desequipado", Function.MenuTheme.Soft)
		if ClothesChanged then
			Function.GUIUpdate()
		end
		S.Changed()
	end

	function Function.CatalogShop.Toggle(Id)
		local S = Function.CatalogShop
		if S.State(Id).Equipped then
			S.Unequip(Id)
		else
			S.Equip(Id)
		end
	end

	-- [v42] Rosto/Cabeça escolhidos na loja viram override na HumanoidDescription que o Loader usa pra trocar a cabeça.
	-- Cabeça (inclui Dinâmica) precisa de rig R15 pra vir como MeshPart; só rosto Classic continua no caminho R6.
	function Function.CatalogShop.HeadOverride(HD, Clothes)
		if typeof(Clothes) ~= "table" then return end
		local Head = tonumber(Clothes.Head)
		local Face = tonumber(Clothes.Face)
		if Head then
			pcall(function() HD.Head = Head end)
			HD:SetAttribute("RCRig", "R15")
		end
		if Face then
			pcall(function() HD.Face = Face end)
		end
	end

	function Function.CatalogShop.ClearAll()
		local S = Function.CatalogShop
		local Data = PlayerData[SelectPlayer]
		if not Data then return end
		Data.CatalogAccessory = {}
		Data.CatalogTail = {}
		Data.CatalogRemove = {}
		local Base = S.Base[SelectPlayer]
		if Base then
			for _, Id in ipairs(Base.Ids) do
				table.insert(Data.CatalogRemove, Id)
			end
		end
		for Key in pairs(S.ClothNames) do
			Data.CatalogClothes[Key] = ""
		end
		S.Toast("Tudo desequipado", Function.MenuTheme.Soft)
		Function.GUIUpdate()
		S.Changed()
	end

	-- aplica no personagem (mesma rotina do botão Execute)
	function Function.CatalogApply()
		local ExecutePlayer = PS:FindFirstChild(SelectPlayer)
		local ExecuteCharacter = ExecutePlayer and ExecutePlayer.Character
		if not ExecuteCharacter then
			return false
		end
		Function.CharacterReset(ExecutePlayer.Name)
		local Ok, Err = pcall(Function.CharacterExecute, ExecuteCharacter, ExecutePlayer.Name)
		if not Ok then
			warn("[RoClothes] CharacterExecute error:", Err)
		end
		return Ok
	end

	function Function.CatalogShop.QueueApply()
		local S = Function.CatalogShop
		S.ApplyToken += 1
		local Mine = S.ApplyToken
		task.delay(0.6, function()
			if Mine == S.ApplyToken then
				Function.CatalogApply()
			end
		end)
	end

	-- itens que vêm do username / outfit (o "avatar base")
	function Function.CatalogShop.LoadBase(Name, Force)
		local S = Function.CatalogShop
		local Data = PlayerData[Name]
		if not Data then return end
		local Username = tostring(Data.CatalogUsername or "")
		local Outfit = tostring(Data.CatalogOutfitId or "")
		local Key = Username .. "|" .. Outfit
		local Current = S.Base[Name]
		if not Force and Current and Current.Key == Key then return end

		local Mine = {Key = Key, Ids = {}, Set = {}, Loading = true}
		S.Base[Name] = Mine
		if Username == "" and Outfit == "" then
			Mine.Loading = false
			return
		end

		task.defer(function()
			local function Collect(Description)
				for _, Accessory in ipairs(Description:GetAccessories(true)) do
					local Id = tonumber(Accessory.AssetId)
					if Id and not Mine.Set[Id] then
						Mine.Set[Id] = true
						table.insert(Mine.Ids, Id)
					end
				end
			end
			if Username ~= "" then
				pcall(function()
					local UserId = PS:GetUserIdFromNameAsync(Username)
					Collect(PS:GetHumanoidDescriptionFromUserId(UserId))
				end)
			end
			if Outfit ~= "" then
				pcall(function()
					Collect(PS:GetHumanoidDescriptionFromOutfitId(tonumber(Outfit) or Outfit))
				end)
			end
			Mine.Loading = false
			if S.Base[Name] == Mine then
				S.Changed(true)
			end
		end)
	end

	function Function.CatalogShop.MakeSig()
		local Data = PlayerData[SelectPlayer]
		if not Data then return "" end
		local S = Function.CatalogShop
		local Base = S.Base[SelectPlayer]
		return table.concat({
			SelectPlayer,
			tostring(Data.CatalogUsername), tostring(Data.CatalogOutfitId),
			table.concat(Data.CatalogAccessory, ","), table.concat(Data.CatalogTail, ","), table.concat(Data.CatalogRemove, ","),
			tostring(Data.CatalogClothes.Shirt), tostring(Data.CatalogClothes.Pants), tostring(Data.CatalogClothes.ShirtGraphic),
			tostring(Data.CatalogClothes.Face), tostring(Data.CatalogClothes.Head),
			Base and #Base.Ids or -1,
		}, "|")
	end

	-- chamado pelo GUIUpdate: só redesenha quando algo mudou de verdade
	function Function.CatalogShop.OnUpdate()
		local S = Function.CatalogShop
		if not S.Built or not PlayerData[SelectPlayer] then return end
		S.LoadBase(SelectPlayer)
		local Sig = S.MakeSig()
		if Sig ~= S.Sig then
			S.Sig = Sig
			S.Render()
		end
	end

	-- algo mudou (equipou, desequipou, base carregou): redesenha e, se quiser, aplica
	function Function.CatalogShop.Changed(NoApply)
		local S = Function.CatalogShop
		S.Sig = S.MakeSig()
		S.Render()
		if S.AutoApply and not NoApply then
			S.QueueApply()
		end
	end

	function Function.CatalogShop.Render()
		local S = Function.CatalogShop
		if not S.Built then return end
		for Card, Update in pairs(S.Cards) do
			if Card.Parent then
				pcall(Update)
			else
				S.Cards[Card] = nil
			end
		end
		S.RenderEquipped()
		S.UpdateTabs()
	end

	function Function.CatalogShop.Toast(Text, Color)
		local S = Function.CatalogShop
		local Label = S.ToastLabel
		if not Label or not Label.Parent then return end
		S.ToastToken += 1
		local Mine = S.ToastToken
		Label.Text = Text
		Label.TextColor3 = Color or Function.MenuTheme.Soft
		Label.Visible = true
		Label.TextTransparency = 1
		Label.BackgroundTransparency = 1
		Function.ModernTween(Label, 0.18, {TextTransparency = 0, BackgroundTransparency = 0.08})
		task.delay(2.2, function()
			if Mine == S.ToastToken and Label.Parent then
				Function.ModernTween(Label, 0.3, {TextTransparency = 1, BackgroundTransparency = 1})
				task.delay(0.32, function()
					if Mine == S.ToastToken and Label.Parent then
						Label.Visible = false
					end
				end)
			end
		end)
	end

	function Function.CatalogShop.SetStatus(Text)
		local S = Function.CatalogShop
		if S.StatusLabel then
			S.StatusLabel.Text = Text or ""
		end
	end

	-- ---------- cartão de item compacto (cabe 6 por linha): ícone com preço em cima, nome, botão de símbolo ----------
