			Tag.TextColor3 = Theme.Deep
			Tag.ZIndex = 3
			Tag.Parent = ThumbBack
			Function.ModernCorner(Tag, UDim.new(0, 4))
			local TagPad = Instance.new("UIPadding")
			TagPad.PaddingLeft = UDim.new(0, 3)
			TagPad.PaddingRight = UDim.new(0, 3)
			TagPad.Parent = Tag
		end

		-- preço: faixa pequena em cima do ícone (embaixo, à esquerda)
