		local Button = Instance.new("TextButton")
		Button.Name = "ActionButton"
		Button.AnchorPoint = Vector2.new(0.5, 1)
		Button.Position = UDim2.new(0.5, 0, 1, -3)
		Button.Size = UDim2.new(1, -6, 0, 17)
		Button.AutoButtonColor = false
		Button.BorderSizePixel = 0
		Button.Font = Enum.Font.GothamBold
		Button.TextSize = 12
		Button.Text = "＋"
		Button.Parent = Card
		Function.ModernCorner(Button, UDim.new(0, 6))

		local function Fill(Info)
			if not Card.Parent then return end
			NameLabel.Text = Info.Name
			local Text, Color = S.PriceText(Info)
			PriceLabel.Text = Text
			PriceLabel.TextColor3 = Color
		end
		if S.Info[Id] then
			Fill(S.Info[Id])
		else
			S.GetInfo(Id, Fill)
		end

		local function Update()
			local State = S.State(Id)
			if State.Removed then
				Button.Text = "↺"
				Button.BackgroundColor3 = Theme.Amber
				Button.TextColor3 = Theme.Deep
				Stroke.Color = Theme.Amber
				Stroke.Transparency = 0.45
				Thumb.ImageTransparency = 0.6
				Badge.Visible = true
				Badge.Text = "✕"
				Badge.BackgroundColor3 = Theme.Amber
			elseif State.Equipped then
				Button.Text = "✕"
				Button.BackgroundColor3 = Theme.Categories.danger.B
				Button.TextColor3 = Color3.fromRGB(255, 255, 255)
				Stroke.Color = Theme.Mint
				Stroke.Transparency = 0.2
				Thumb.ImageTransparency = 0
				Badge.Visible = true
				Badge.Text = "✓"
				Badge.BackgroundColor3 = Theme.Mint
			else
				Button.Text = "＋"
				Button.BackgroundColor3 = Theme.Mint
				Button.TextColor3 = Theme.Deep
				Stroke.Color = Theme.Accent
				Stroke.Transparency = 0.7
				Thumb.ImageTransparency = 0
				Badge.Visible = false
			end
		end
		Update()
		S.Cards[Card] = Update
		Card.Destroying:Connect(function()
			S.Cards[Card] = nil
		end)

		table.insert(AllConnect, Button.MouseButton1Click:Connect(function()
			S.Toggle(Id)
		end))
		-- tocar no ícone mostra o nome completo, o ID e o criador (o nome no cartão é curto)
		table.insert(AllConnect, Thumb.MouseButton1Click:Connect(function()
			local Info = S.Info[Id]
			local Extra = Info and Info.Creator and (" · por " .. Info.Creator) or ""
			S.Toast((Info and Info.Name or "Item") .. " · ID " .. Id .. Extra, Theme.Accent)
		end))
		table.insert(AllConnect, Card.MouseEnter:Connect(function()
			Function.ModernTween(ThumbBack, 0.15, {BackgroundColor3 = Theme.Grad})
		end))
		table.insert(AllConnect, Card.MouseLeave:Connect(function()
			Function.ModernTween(ThumbBack, 0.15, {BackgroundColor3 = Theme.Deep})
		end))

		return Card
	end

	-- grade rolável de cartões: 6 colunas (4 se a janela ficar muito estreita); célula = largura + 44px
	function Function.CatalogShop.MakeGrid(Parent, Position, Size)
		local Theme = Function.MenuTheme
		local Scroll = Instance.new("ScrollingFrame")
		Scroll.Name = "Grid"
		Scroll.Position = Position
		Scroll.Size = Size
		Scroll.BackgroundTransparency = 1
		Scroll.BorderSizePixel = 0
		Scroll.ClipsDescendants = true
		Scroll.ScrollBarThickness = 3
		Scroll.ScrollBarImageColor3 = Theme.Accent
		Scroll.ScrollBarImageTransparency = 0.25
		Scroll.VerticalScrollBarInset = Enum.ScrollBarInset.ScrollBar
		Scroll.ScrollingDirection = Enum.ScrollingDirection.Y
		Scroll.CanvasSize = UDim2.new()
		Scroll.AutomaticCanvasSize = Enum.AutomaticSize.Y
		Scroll.Parent = Parent

		local Pad = Instance.new("UIPadding")
		Pad.PaddingTop = UDim.new(0, 4)
		Pad.PaddingBottom = UDim.new(0, 4)
		Pad.PaddingLeft = UDim.new(0, 4)
		Pad.PaddingRight = UDim.new(0, 4)
		Pad.Parent = Scroll

		local Grid = Instance.new("UIGridLayout")
		Grid.SortOrder = Enum.SortOrder.LayoutOrder
		Grid.CellPadding = UDim2.fromOffset(4, 4)
		Grid.HorizontalAlignment = Enum.HorizontalAlignment.Left
		Grid.Parent = Scroll

		local function Resize()
			-- AbsoluteSize já vem multiplicado pelo UIScale do menu: volta para a medida local antes de dividir em colunas
			local Inner = Scroll.AbsoluteSize.X / Function.MenuLocalScale() - 8 - Scroll.ScrollBarThickness - 2
			if Inner <= 0 then return end
			local BaseColumns = Inner >= 260 and 6 or 4
			local Columns = Function.ScaledCount(BaseColumns, Function.MenuSizeValue())
			local W = math.floor((Inner - 4 * (Columns - 1)) / Columns)
			Grid.CellSize = UDim2.fromOffset(W, W + 44)
		end
		table.insert(AllConnect, Scroll:GetPropertyChangedSignal("AbsoluteSize"):Connect(Resize))
		Resize()
		return Scroll
	end

	function Function.CatalogShop.ClearGrid(Grid)
		for _, Child in ipairs(Grid:GetChildren()) do
			if Child:IsA("GuiObject") then
				Child:Destroy()
			end
		end
	end

	-- ---------- aba Equipados ----------
	function Function.CatalogShop.RenderEquipped()
		local S = Function.CatalogShop
		local Theme = Function.MenuTheme
		local Grid = S.EquippedGrid
		local Data = PlayerData[SelectPlayer]
		if not Grid or not Data then return end

		local Entries = {}
		local Seen = {}
		local Equipped = 0
		local function Add(Id, Tag, Color, Order)
			Id = tonumber(Id)
			if not Id or Seen[Id] then return end
			Seen[Id] = true
			table.insert(Entries, {Id = Id, Tag = Tag, TagColor = Color, Order = Order})
		end

		for Key, Label in pairs(S.ClothNames) do
			if tonumber(Data.CatalogClothes[Key]) then
				Add(Data.CatalogClothes[Key], Label, Theme.Amber, 1)
			end
		end
		for _, Id in ipairs(Data.CatalogAccessory) do
			Add(Id, "MEU", Theme.Mint, 2)
		end
		for _, Id in ipairs(Data.CatalogTail) do
			Add(Id, "RABO", Theme.Amber, 3)
		end
		local Base = S.Base[SelectPlayer]
		local Removed = {}
		if Base then
			for _, Id in ipairs(Base.Ids) do
				if S.Find(Data.CatalogRemove, Id) then
					table.insert(Removed, Id)
				else
					Add(Id, "AVT", Theme.Accent, 4)
				end
			end
		end
		Equipped = #Entries
		for _, Id in ipairs(Removed) do
			Add(Id, "REM", Theme.Danger, 5)
		end

		-- só recria os cartões se a lista mudou (evita piscar)
		local Parts = {}
		for _, E in ipairs(Entries) do
			table.insert(Parts, E.Id .. E.Tag)
		end
		local Key = table.concat(Parts, ",")
		if Key ~= S.EquippedKey then
			S.EquippedKey = Key
			S.ClearGrid(Grid)
			for _, E in ipairs(Entries) do
				S.MakeCard(Grid, E.Id, E)
			end
		end

		S.EquippedCount = Equipped
		if S.EmptyLabel then
			S.EmptyLabel.Visible = (#Entries == 0)
			local Loading = Base and Base.Loading
			S.EmptyLabel.Text = Loading and "Carregando avatar do usuário…" or "Nada equipado ainda.\nVá na aba Loja e toque em Equipar."
		end
	end

	-- ---------- pesquisa ----------
	function Function.CatalogShop.Search(More)
		local S = Function.CatalogShop
		if not S.Built then return end
		S.Token += 1
		local Token = S.Token
		local Grid = S.ShopGrid
		local Query = S.Query

		if not More then
			S.ClearGrid(Grid)
			S.Pages = nil
			S.LoadMoreButton.Visible = false
			S.SetStatus("Buscando…")
			S.ShopCount = 0
		end

		task.spawn(function()
			local Ok, Err = pcall(function()
				local AES = game:GetService("AvatarEditorService")
				local Items

				if More then
					local Pages = S.Pages
					if not Pages or Pages.IsFinished then return end
					Pages:AdvanceToNextPageAsync()
					Items = Pages:GetCurrentPage()
				else
					-- ID colado ou link do catálogo/biblioteca
					local Direct = tonumber(string.match(Query, "catalog/(%d+)")) or tonumber(string.match(Query, "library/(%d+)"))
						or tonumber(string.match(Query, "^%s*(%d%d%d%d%d+)%s*$"))
					if Direct then
						S.GetInfo(Direct, function(Info)
							if Token ~= S.Token then return end
							if Info.Invalid then
								S.SetStatus("Item " .. Direct .. " não encontrado")
							else
								S.SetStatus("Resultado por ID")
								S.MakeCard(Grid, Direct, {Order = 1})
							end
						end)
						return
					end

					local Cat = S.Categories[S.Category]
					local function Build(UseBundles)
						local Params = CatalogSearchParams.new()
						Params.SearchKeyword = Query
						local Types, BTypes = {}, {}
						if UseBundles then
							for _, TypeName in ipairs(Cat[3] or {}) do
								local Found, Value = pcall(function() return Enum.BundleType[TypeName] end)
								if Found and Value then table.insert(BTypes, Value) end
							end
							if #BTypes == 0 then return nil end
							Params.BundleTypes = BTypes
						else
							for _, TypeName in ipairs(Cat[2]) do
								local Found, Value = pcall(function() return Enum.AvatarAssetType[TypeName] end)
								if Found and Value then table.insert(Types, Value) end
							end
							if #Types == 0 then return nil end
							Params.AssetTypes = Types
						end
						local SortName = S.Sorts[S.Sort][2] or (Query ~= "" and "Relevance" or "Bestselling")
						pcall(function() Params.SortType = Enum.CatalogSortType[SortName] end)
						pcall(function() Params.Limit = 30 end)
						return Params
					end
					-- categorias com 3º campo (cabeça dinâmica) tentam Bundle primeiro e depois Asset
					local Order = Cat[3] and {true, false} or {false}
					for _, UseBundles in ipairs(Order) do
						local Params = Build(UseBundles)
						if Params then
							local Pages = AES:SearchCatalog(Params)
							local Page = Pages:GetCurrentPage()
							if #Page > 0 or UseBundles == Order[#Order] then
								S.Pages, Items = Pages, Page
								break
							end
						end
					end
					if not Items then
						S.SetStatus("Categoria indisponível nesta versão do Roblox · cole o ID do item")
						return
					end
				end

				if Token ~= S.Token then return end

				local Ids = {}
				local Slots = {}
				local Pending = 0
				for Index, Item in ipairs(Items) do
					local ItemId = tonumber(Item.Id)
					if ItemId and string.find(tostring(Item.ItemType), "Asset", 1, true) then
						Slots[Index] = ItemId
					elseif ItemId and string.find(tostring(Item.ItemType), "Bundle", 1, true) then
						-- [v43] bundle de cabeça dinâmica -> acha o asset da cabeça dentro dele (é esse que vai pro Equipar)
						Pending += 1
						task.spawn(function()
							pcall(function()
								local Details = AES:GetItemDetails(ItemId, Enum.AvatarItemType.Bundle)
								local List = Details and (Details.BundledItems or Details.Items)
								if typeof(List) ~= "table" then
									warn("[RoC] bundle " .. ItemId .. " sem lista de itens")
									return
								end
								for _, Sub in ipairs(List) do
									local SubId = tonumber(Sub.Id)
									if SubId and (Sub.Type == nil or string.find(tostring(Sub.Type), "Asset", 1, true)) then
										local Ok, Product = pcall(function() return MPS:GetProductInfo(SubId) end)
										if Ok and typeof(Product) == "table" and (Product.AssetTypeId == 79 or Product.AssetTypeId == 17) then
											S.Info[SubId] = {
												Name = tostring(Details.Name or Product.Name or ("Item " .. SubId)),
												Price = tonumber(Details.Price) or Product.PriceInRobux,
												OnSale = Product.IsForSale,
												AssetTypeId = Product.AssetTypeId,
												Creator = Details.CreatorName,
											}
											Slots[Index] = SubId
											return
										end
									end
								end
							end)
							Pending -= 1
						end)
					end
				end
				local Waited = 0
				while Pending > 0 and Waited < 400 do
					task.wait(0.05)
					Waited += 1
				end
				for Index = 1, #Items do
					if Slots[Index] then table.insert(Ids, Slots[Index]) end
				end

				-- nomes e preços em lote (evita 30 chamadas de GetProductInfo)
				if #Ids > 0 then
					local Done, Details = pcall(function()
						return AES:GetBatchItemDetails(Ids, Enum.AvatarItemType.Asset)
					end)
					if Done and typeof(Details) == "table" then
						for _, D in ipairs(Details) do
							local Id = tonumber(D.Id)
							if Id and not S.Info[Id] then
								S.Info[Id] = {
									Name = tostring(D.Name or ("Item " .. Id)),
									Price = tonumber(D.Price),
									PriceStatus = D.PriceStatus ~= nil and D.PriceStatus ~= "" and tostring(D.PriceStatus) or nil,
									Creator = D.CreatorName,
								}
								if S.Info[Id].Price ~= nil then S.Info[Id].PriceStatus = nil end
							end
						end
					end
				end

				if Token ~= S.Token then return end
				for _, Id in ipairs(Ids) do
					S.ShopCount += 1
					S.MakeCard(Grid, Id, {Order = S.ShopCount})
				end

				local Finished = S.Pages == nil or S.Pages.IsFinished
				S.LoadMoreButton.Visible = not Finished
				if S.ShopCount == 0 then
					S.SetStatus("Nenhum item encontrado")
				else
					S.SetStatus(S.ShopCount .. " itens" .. (Finished and "" or " · role e toque em Mais"))
				end
			end)
			if not Ok and Token == S.Token then
				S.SetStatus("Busca indisponível aqui: cole o ID ou link do item")
				warn("[RoC] busca do catálogo:", Err)
			end
		end)
	end

	function Function.CatalogShop.SetTab(Tab)
		local S = Function.CatalogShop
		S.Tab = Tab
		if S.ShopPage then S.ShopPage.Visible = (Tab == "Loja") end
		if S.EquippedPage then S.EquippedPage.Visible = (Tab == "Equipados") end
		if S.AvatarPage then S.AvatarPage.Visible = (Tab == "Avatar") end
		S.UpdateTabs()
		if Tab == "Equipados" then
			S.RenderEquipped()
		end
		if Tab == "Loja" and not S.Loaded and GUIObject.Catalog_3.Visible then
			S.Loaded = true
			S.Search()
		end
	end

	function Function.CatalogShop.UpdateTabs()
		local S = Function.CatalogShop
		local Theme = Function.MenuTheme
		if not S.TabButtons then return end
		for Name, Button in pairs(S.TabButtons) do
			local Active = (S.Tab == Name)
			Button.BackgroundColor3 = Active and Theme.Accent or Theme.Panel
			Button.TextColor3 = Active and Theme.Deep or Theme.Soft
			if Name == "Equipados" then
				Button.Text = (S.EquippedCount and S.EquippedCount > 0) and ("Equip. " .. S.EquippedCount) or "Equipados"
			end
		end
		if S.AutoButton then
			S.AutoButton.Text = S.AutoApply and "AUTO ✓" or "AUTO"
			S.AutoButton.BackgroundColor3 = S.AutoApply and Theme.Mint or Theme.Panel
			S.AutoButton.TextColor3 = S.AutoApply and Theme.Deep or Theme.Soft
		end
		if S.SortButton then
			S.SortButton.Text = "↕ " .. S.Sorts[S.Sort][1]
		end
		if S.GroupButtons then
			local Members = {}
			for _, Index in ipairs(S.Groups[S.Group][2]) do Members[Index] = true end
			for GIndex, Button in pairs(S.GroupButtons) do
				local Active = (S.Group == GIndex)
				Button.BackgroundColor3 = Active and Theme.Accent or Theme.Panel
				Button.TextColor3 = Active and Theme.Deep or Theme.Soft
			end
			for Index, Chip in pairs(S.ChipButtons or {}) do
				Chip.Visible = Members[Index] == true
			end
		end
		if S.ChipButtons then
			for Index, Chip in pairs(S.ChipButtons) do
				local Active = (S.Category == Index)
				Chip.BackgroundColor3 = Active and Theme.Accent or Theme.Panel
				Chip.TextColor3 = Active and Theme.Deep or Theme.Soft
			end
		end
	end

	-- ---------- monta a interface (depois do estilo do menu, pra não ser reestilizada) ----------
	function Function.CatalogShop.Build()
		local S = Function.CatalogShop
		if S.Built then return end
		local Theme = Function.MenuTheme
		local Page = GUIObject.Catalog_3

		-- a caixinha antiga de "Accessory Id" some: a loja substitui
		GUIObject.AccessoryFrame.Visible = false

		local Root = Instance.new("Frame")
		Root.Name = "MarketRoot"
		Root.Size = UDim2.fromScale(1, 1)
		Root.BackgroundTransparency = 1
		Root.ClipsDescendants = true
		Root.Parent = Page
		local RootPad = Instance.new("UIPadding")
		RootPad.PaddingTop = UDim.new(0, 6)
		RootPad.PaddingBottom = UDim.new(0, 6)
		RootPad.PaddingLeft = UDim.new(0, 6)
		RootPad.PaddingRight = UDim.new(0, 6)
		RootPad.Parent = Root

		local function MakeButton(Parent, Text, Size, Position)
			local Button = Instance.new("TextButton")
			Button.AutoButtonColor = false
			Button.BorderSizePixel = 0
			Button.BackgroundColor3 = Theme.Panel
			Button.TextColor3 = Theme.Soft
			Button.Font = Enum.Font.GothamBold
			Button.TextSize = 11
			Button.Text = Text
			Button.Size = Size
			if Position then Button.Position = Position end
			Button.TextTruncate = Enum.TextTruncate.AtEnd
			Button.Parent = Parent
			Function.ModernCorner(Button, UDim.new(0, 8))
			return Button
		end

		local function MakeBox(Parent, Position, Size)
			local Frame = Instance.new("Frame")
			Frame.Position = Position
			Frame.Size = Size
			Frame.BackgroundColor3 = Theme.Deep
			Frame.BorderSizePixel = 0
			Frame.Parent = Parent
			Function.ModernCorner(Frame, UDim.new(0, 8))
			local Stroke = Instance.new("UIStroke")
			Stroke.Color = Theme.Accent
			Stroke.Thickness = 1.5
			Stroke.Transparency = 0.6
			Stroke.Parent = Frame
			return Frame
		end

		-- barra de abas
		local TabsBar = Instance.new("Frame")
		TabsBar.Name = "TabsBar"
		TabsBar.Size = UDim2.new(1, 0, 0, 30)
		TabsBar.BackgroundTransparency = 1
		TabsBar.Parent = Root

		local TabsHolder = Instance.new("Frame")
		TabsHolder.Size = UDim2.new(1, -82, 1, 0)
		TabsHolder.BackgroundTransparency = 1
		TabsHolder.Parent = TabsBar

		S.TabButtons = {}
		for Index, Name in ipairs({"Loja", "Equipados", "Avatar"}) do
			local Button = MakeButton(TabsHolder, Name, UDim2.new(1 / 3, -4, 1, 0), UDim2.new((Index - 1) / 3, 0, 0, 0))
			S.TabButtons[Name] = Button
			table.insert(AllConnect, Button.MouseButton1Click:Connect(function()
				S.SetTab(Name)
			end))
		end

		local ApplyButton = MakeButton(TabsBar, "⚡", UDim2.new(0, 34, 1, 0), UDim2.new(1, -78, 0, 0))
		ApplyButton.TextSize = 14
		ApplyButton.BackgroundColor3 = Theme.Categories.accent.B
		ApplyButton.TextColor3 = Color3.fromRGB(255, 255, 255)
		table.insert(AllConnect, ApplyButton.MouseButton1Click:Connect(function()
			if Function.CatalogApply() then
				S.Toast("Aplicado no personagem ⚡", Theme.Accent)
			else
				S.Toast("Sem personagem pra aplicar", Theme.Danger)
			end
		end))

		S.AutoButton = MakeButton(TabsBar, "AUTO", UDim2.new(0, 40, 1, 0), UDim2.new(1, -40, 0, 0))
		S.AutoButton.TextSize = 9
		table.insert(AllConnect, S.AutoButton.MouseButton1Click:Connect(function()
			S.AutoApply = not S.AutoApply
			S.UpdateTabs()
			S.Toast(S.AutoApply and "Auto-aplicar ligado: equipar já aplica" or "Auto-aplicar desligado (use ⚡)", Theme.Soft)
		end))

		-- páginas
		local function MakePage(Name)
			local Frame = Instance.new("Frame")
			Frame.Name = Name
			Frame.Position = UDim2.new(0, 0, 0, 36)
			Frame.Size = UDim2.new(1, 0, 1, -36)
			Frame.BackgroundTransparency = 1
			Frame.Visible = false
			Frame.Parent = Root
			return Frame
		end

		-- ===== página Loja =====
		S.ShopPage = MakePage("ShopPage")

		local SearchBox = MakeBox(S.ShopPage, UDim2.new(0, 0, 0, 0), UDim2.new(1, -70, 0, 32))
		local Input = Instance.new("TextBox")
		Input.Name = "SearchBox"
		Input.Size = UDim2.new(1, -12, 1, 0)
		Input.Position = UDim2.fromOffset(8, 0)
		Input.BackgroundTransparency = 1
		Input.ClearTextOnFocus = false
		Input.Font = Enum.Font.GothamMedium
		Input.PlaceholderText = "🔎 Nome, ID ou link do item"
		Input.PlaceholderColor3 = Theme.Soft
		Input.Text = ""
		Input.TextColor3 = Color3.fromRGB(255, 255, 255)
		Input.TextSize = 12
		Input.TextXAlignment = Enum.TextXAlignment.Left
		Input.TextTruncate = Enum.TextTruncate.AtEnd
		Input.Parent = SearchBox
		S.SearchInput = Input

		local SearchButton = MakeButton(S.ShopPage, "Buscar", UDim2.new(0, 64, 0, 32), UDim2.new(1, -64, 0, 0))
		SearchButton.BackgroundColor3 = Theme.Accent
		SearchButton.TextColor3 = Theme.Deep

		local function RunSearch()
			S.Query = Input.Text
			S.Search()
		end
		table.insert(AllConnect, Input.FocusLost:Connect(function(Enter)
			if Enter then RunSearch() end
		end))
		table.insert(AllConnect, SearchButton.MouseButton1Click:Connect(RunSearch))

		-- [v43] filtro fixo (sem rolagem): ordenação + grupos Acessórios / Rosto / Roupas
		local Chips = Instance.new("Frame")
		Chips.Name = "Chips"
		Chips.Position = UDim2.new(0, 0, 0, 38)
		Chips.Size = UDim2.new(1, 0, 0, 26)
		Chips.BackgroundTransparency = 1
		Chips.BorderSizePixel = 0
		Chips.Parent = S.ShopPage

		S.SortButton = MakeButton(Chips, "↕ Auto", UDim2.new(0, 96, 1, 0), UDim2.new(0, 0, 0, 0))
		S.SortButton.BackgroundColor3 = Theme.Categories.amber.B
		S.SortButton.TextColor3 = Theme.Amber
		table.insert(AllConnect, S.SortButton.MouseButton1Click:Connect(function()
			S.Sort = S.Sort % #S.Sorts + 1
			S.UpdateTabs()
			S.Search()
		end))

		local GroupHolder = Instance.new("Frame")
		GroupHolder.Name = "Groups"
		GroupHolder.Position = UDim2.new(0, 101, 0, 0)
		GroupHolder.Size = UDim2.new(1, -101, 1, 0)
		GroupHolder.BackgroundTransparency = 1
		GroupHolder.Parent = Chips

		-- submenu: categorias do grupo escolhido (esta barra rola na horizontal)
		local SubChips = Instance.new("ScrollingFrame")
		SubChips.Name = "SubChips"
		SubChips.Position = UDim2.new(0, 0, 0, 68)
		SubChips.Size = UDim2.new(1, 0, 0, 26)
		SubChips.BackgroundTransparency = 1
		SubChips.BorderSizePixel = 0
		SubChips.ScrollBarThickness = 0
