	function Function.compileOvertime()
		task.spawn(function()
			local filesFound = env.listfiles("RClothesLerp/Bundles")
			local t = {}
			for i, v in pairs(filesFound) do
				if env.isfile(v) then
					local b = HS:JSONDecode(env.readfile(v))
					local storedName = b.BundleName
					b["BundleName"] = nil

					local function fromJSON(t)
						for i, v in pairs(t) do
							local value,original = Function.convertFromJSON(v)
							t[i] = value
							if typeof(v) == "table" and original then
								fromJSON(v)
							end
						end
					end
					fromJSON(b)

					t[storedName] = b
				end
			end
			local function toJSON(t)
				for i, v in pairs(t) do
					if typeof(v) == "table" then
						toJSON(v)
					else
						t[i] = Function.convertToJSON(v)
					end
				end
			end
			toJSON(t)
			if #filesFound > 0 then
				env.writefile("RClothesLerp/BundleLoader.json", HS:JSONEncode(t))
			else
				env.delfile("RClothesLerp/BundleLoader.json")
			end
		end)
	end



	-- // SAVE ALL / LOAD // --
	-- Save All grava tudo num arquivo só (writefile) e o Load lê esse arquivo de volta.
	Function.SaveAllConfig = {
		File = "RClothesLerp/SaveAll.json",
		AutoLoad = true,       -- true = carrega sozinho quando você reexecutar o script
		ApplyAfterLoad = true, -- true = depois de carregar, já aplica no seu personagem (igual ao botão Execute)
		ClearClicks = 2,       -- quantos cliques seguidos o botão "Clear Saved" precisa pra apagar tudo
		ClearTimeout = 3,      -- segundos pra confirmar; passou disso, a contagem de cliques zera
		-- arquivos apagados pelo botão "Clear Saved" (o Save All e os arquivos do antigo botão Save)
		ClearFiles = {
			"RClothesLerp/SaveAll.json",
			"RClothesLerp/Settings.json",
			"RClothesLerp/MobileButtonPlacement.json",
		},
		-- coisas temporárias do jogo (personagem, peças, cooldowns...) que não fazem sentido salvar
		Skip = {
			Character = true, CurrentPartList = true, ConvertedPart = true, PartList = true,
			Cooldown = true, updateCooldown = true, Healing = true, OldestClothings = true,
			OldTransparency = true, PreviousHP = true, SavedPreviousHP = true, SavedTopHP = true,
			SavedBottomHP = true, HealProgress = true, TopRipped = true, BottomRipped = true,
		},
		-- tabelas de configuração que são mescladas (assim campos novos do script não se perdem)
		Struct = {tailSettings = true, LocalTransparency = true, CatalogClothes = true, HPClothes = true},
	}

	function Function.SaveEncode(value, seen)
		local kind = typeof(value)
		if kind == "string" or kind == "boolean" then
			return value
		elseif kind == "number" then
			if value ~= value or value == math.huge or value == -math.huge then return nil end
			return value
		elseif kind == "Color3" then
			return {__t = "C3", r = value.R, g = value.G, b = value.B}
		elseif kind == "Vector3" then
			return {__t = "V3", x = value.X, y = value.Y, z = value.Z}
		elseif kind == "Vector2" then
			return {__t = "V2", x = value.X, y = value.Y}
		elseif kind == "UDim2" then
			return {__t = "U2", xs = value.X.Scale, xo = value.X.Offset, ys = value.Y.Scale, yo = value.Y.Offset}
		elseif kind == "EnumItem" then
			return {__t = "En", e = tostring(value.EnumType), v = value.Value}
		elseif kind == "table" then
			seen = seen or {}
			if seen[value] then return nil end
			seen[value] = true
			local list = {}
			for k, v in pairs(value) do
				local keyKind = typeof(k)
				if keyKind == "string" or keyKind == "number" or keyKind == "boolean" then
					local encoded = Function.SaveEncode(v, seen)
					if encoded ~= nil then
						table.insert(list, {k, encoded})
					end
				end
			end
			seen[value] = nil
			return {__t = "T", p = list}
		end
		return nil -- Instances, funções etc. não são salvos
	end

	function Function.SaveDecode(value)
		if typeof(value) ~= "table" then return value end
		local tag = value.__t
		if tag == "C3" then
			return Color3.new(value.r, value.g, value.b)
		elseif tag == "V3" then
			return Vector3.new(value.x, value.y, value.z)
		elseif tag == "V2" then
			return Vector2.new(value.x, value.y)
		elseif tag == "U2" then
			return UDim2.new(value.xs, value.xo, value.ys, value.yo)
		elseif tag == "En" then
			local ok, item = pcall(function() return Enum[value.e]:FromValue(value.v) end)
			if ok then return item end
			return nil
		elseif tag == "T" then
			local out = {}
			for _, pair in ipairs(value.p or {}) do
				local k = pair[1]
				local v = Function.SaveDecode(pair[2])
				if k ~= nil and v ~= nil then
					out[k] = v
				end
			end
			return out
		end
		return value
	end

	-- devolve (true) ou (false, motivo)
	function Function.SaveAll()
		local cfg = Function.SaveAllConfig
		if not (env.writefile and env.makefolder and env.isfolder) then
			return false, "Executor is not compatible for saving data!"
		end
		local ok, err = pcall(function()
			if not env.isfolder("RClothesLerp") then
				env.makefolder("RClothesLerp")
			end
			local players = {}
			for name, data in pairs(PlayerData) do
				local clean = {}
				for key, value in pairs(data) do
					if not cfg.Skip[key] then
						clean[key] = value
					end
				end
				players[name] = Function.SaveEncode(clean)
			end
			local settings = Function.SaveEncode({
				loadupExecute = loadupExecute,
				MenuScale = MenuScale,
				loadupClosed = loadupClosed,
				loadupFPerson = loadupFPerson,
				KEYBIND = KEYBIND,
				hpKEYBIND = hpKEYBIND,
				dpKEYBIND = dpKEYBIND,
				Method = Method,
				ClickExecute = ClickExecute,
				HealPos = GUIObject.ImageHeal.Position,
				TearPos = GUIObject.ImageTear.Position,
			})
			env.writefile(cfg.File, HS:JSONEncode({version = 1, savedAt = os.time(), settings = settings, players = players}))
		end)
		if ok then return true end
		return false, tostring(err)
	end

	-- devolve (true) ou (false, motivo)
	function Function.LoadAll()
		local cfg = Function.SaveAllConfig
		if not (env.isfile and env.readfile) then
			return false, "Executor is not compatible for loading data!"
		end
		if not env.isfile(cfg.File) then
			return false, "no save"
		end
		local ok, err = pcall(function()
			local raw = HS:JSONDecode(env.readfile(cfg.File))
			local settings = Function.SaveDecode(raw.settings) or {}

			if typeof(settings.loadupExecute) == "boolean" then loadupExecute = settings.loadupExecute end
			if typeof(settings.loadupClosed) == "boolean" then loadupClosed = settings.loadupClosed end
			if typeof(settings.loadupFPerson) == "number" then loadupFPerson = settings.loadupFPerson end
			if typeof(settings.KEYBIND) == "EnumItem" then KEYBIND = settings.KEYBIND end
			if typeof(settings.hpKEYBIND) == "EnumItem" then hpKEYBIND = settings.hpKEYBIND end
			if typeof(settings.dpKEYBIND) == "EnumItem" then dpKEYBIND = settings.dpKEYBIND end
			if typeof(settings.Method) == "number" and settings.Method >= 1 and settings.Method <= MaxMethod then Method = settings.Method end
			if typeof(settings.ClickExecute) == "boolean" then ClickExecute = settings.ClickExecute end
			if typeof(settings.HealPos) == "UDim2" then GUIObject.ImageHeal.Position = settings.HealPos end
			if typeof(settings.TearPos) == "UDim2" then GUIObject.ImageTear.Position = settings.TearPos end
			if typeof(settings.MenuScale) == "number" and settings.MenuScale >= 0.5 and settings.MenuScale <= 2.0 then
				MenuScale = settings.MenuScale
				if GUIObject.MenuSizeScale then
					GUIObject.MenuSizeScale.Scale = MenuScale
					local lbl = GUIObject.optionsFrame and GUIObject.optionsFrame:FindFirstChild("MenuSizeLabel", true)
					if lbl then lbl.Text = "Menu Size: " .. math.round(MenuScale * 100) .. "%" end
				end
			end

			for name, encoded in pairs(raw.players or {}) do
				if not PlayerData[name] and PS:FindFirstChild(name) then
					Function.PlayerDataAdd(name)
				end
				local data = PlayerData[name]
				if data then
					local saved = Function.SaveDecode(encoded)
					if typeof(saved) == "table" then
						for key, value in pairs(saved) do
							if not cfg.Skip[key] then
								if cfg.Struct[key] and typeof(data[key]) == "table" and typeof(value) == "table" then
									for subKey, subValue in pairs(value) do
										data[key][subKey] = subValue
									end
								else
									data[key] = value
								end
							end
						end
					end
					Function.CatalogAccessoryFrameAdd(name)
				end
			end
		end)
		if not ok then
			return false, tostring(err)
		end

		Function.GUIUpdate()

		if cfg.ApplyAfterLoad then
			local Character = Player.Character
			if Character and PlayerData[Player.Name] then
				pcall(function()
					Function.CharacterReset(Player.Name)
					Function.CharacterExecute(Character, Player.Name)
				end)
			end
		end
		return true
	end

	-- devolve (true, quantosArquivosApagou) ou (false, motivo)
	function Function.ClearSaved()
		local cfg = Function.SaveAllConfig
		if not (env.isfile and env.delfile) then
			return false, "Executor is not compatible for deleting data!"
		end
		local removed = 0
		local ok, err = pcall(function()
			for _, path in ipairs(cfg.ClearFiles) do
				if env.isfile(path) then
					env.delfile(path)
					removed += 1
				end
			end
		end)
		if not ok then
			return false, tostring(err)
		end
		return true, removed
	end

	function Function.XformDefault()
		return {Pos = Vector3.new(0, 0, 0), Rot = Vector3.new(0, 0, 0), Size = Vector3.new(1, 1, 1), Uni = 1}
	end

	function Function.XformGet(Data, Name)
		if typeof(Data.ClothesXform) ~= "table" then
			Data.ClothesXform = {}
		end
		local Xform = Data.ClothesXform[Name]
		if typeof(Xform) ~= "table" then
			Xform = Function.XformDefault()
			Data.ClothesXform[Name] = Xform
		else
			for Key, Default in pairs(Function.XformDefault()) do
				if typeof(Xform[Key]) ~= typeof(Default) then
					Xform[Key] = Default
				end
			end
		end
		return Xform
	end

	function Function.RecolorParts(Name)
		local Out = {}
		local Item = Clothes[Name]
		if not Item then
			return Out
		end
		local function Add(List)
			if typeof(List) == "table" then
				for _, PartName in pairs(List) do
					if typeof(PartName) == "string" then
						Out[PartName] = true
					end
				end
			end
		end
		Add(Item.Weld)
		local Alt = Item.Alternative
		if typeof(Alt) == "table" then
			Add(Alt.Weld)
			for _, Entry in pairs(Alt) do
				if typeof(Entry) == "table" then
					Add(Entry.Weld)
				end
			end
		end
		return Out
	end

	function Function.RecolorSlots(Name)
		local Found = {}
		for PartName in pairs(Function.RecolorParts(Name)) do
			local Part = PartList[PartName]
			if Part and Part.Recolor then
				Found[Part.Recolor] = true
			end
		end
		local Out = {}
		for _, Slot in ipairs({"Primary", "Secondary", "Tertiary"}) do
			if Found[Slot] then
				table.insert(Out, Slot)
			end
		end
		return Out
	end

	function Function.RecolorInitSlots(PlayerName, Name)
		local Data = PlayerData[PlayerName]
		if not Data or not Clothes[Name] then
			return
		end
		for _, Slot in ipairs(Function.RecolorSlots(Name)) do
			if typeof(Data.ClothesRecolor[Name]) ~= "table" then
				Data.ClothesRecolor[Name] = {}
			end
			if Data.ClothesRecolor[Name][Slot] == nil then
				Data.ClothesRecolor[Name][Slot] = "nil"
			end
		end
	end

	-- [v33] EDIT + RECOLOR: reflexão, transparência e ID de textura por roupa e por slot (o mesmo slot da cor).
	-- Guardado em PlayerData[Player].ClothesMesh[Roupa][Slot] = {Reflectance, Transparency, TextureId}; o Save All grava junto.
	function Function.MeshOverrideGet(Data, Name, Slot, Create)
		if typeof(Data) ~= "table" or typeof(Name) ~= "string" or typeof(Slot) ~= "string" then
			return nil
		end
		if typeof(Data.ClothesMesh) ~= "table" then
			if not Create then
				return nil
			end
			Data.ClothesMesh = {}
		end
		local Item = Data.ClothesMesh[Name]
		if typeof(Item) ~= "table" then
			if not Create then
				return nil
			end
			Item = {}
			Data.ClothesMesh[Name] = Item
		end
		local Entry = Item[Slot]
		if typeof(Entry) ~= "table" then
			if not Create then
				return nil
			end
			Entry = {}
			Item[Slot] = Entry
		end
		return Entry
	end

	-- Só mexe nas propriedades que têm override no Entry. ResetKeys ({Reflectance = true, ...}) devolve
	-- a propriedade ao valor da peça quando o Entry não tem mais override dela.
	function Function.MeshOverrideApplyPart(Object, Template, Entry, ResetKeys)
		if typeof(Object) ~= "Instance" or not Object:IsA("BasePart") or not Object.Parent then
			return
		end
		Template = Template or {}
		Entry = Entry or {}
		local function Pick(Key, Kind, Default)
			local Value = Entry[Key]
			if typeof(Value) == Kind then
				return Value
			end
			if ResetKeys and ResetKeys[Key] then
				Value = Template[Key]
				if typeof(Value) == Kind then
					return Value
				end
				return Default
			end
			return nil
		end
		local Reflect = Pick("Reflectance", "number", 0)
		if Reflect ~= nil then
			Object.Reflectance = math.clamp(Reflect, 0, 1)
		end
		local Transp = Pick("Transparency", "number", 0)
		if Transp ~= nil then
			Object.Transparency = math.clamp(Transp, 0, 1)
		end
		if Object:IsA("MeshPart") then
			local Texture = Pick("TextureId", "string", "")
			if Texture ~= nil then
				pcall(function()
					Object.TextureID = Texture
				end)
			end
		end
	end

	function Function.MeshOverrideApply(PlayerName, Name, Slot, ResetKeys)
		local Data = PlayerData[PlayerName]
		if not Data or typeof(Data.CurrentPartList) ~= "table" or typeof(Data.CurrentPartList.Clothes) ~= "table" then
			return
		end
		local Entry = Function.MeshOverrideGet(Data, Name, Slot, false)
		for PartName in pairs(Function.RecolorParts(Name)) do
			local Template = PartList[PartName]
			local Object = Data.CurrentPartList.Clothes[PartName]
			if Template and Template.Recolor == Slot and typeof(Object) == "Instance" and Object.Parent then
				Function.MeshOverrideApplyPart(Object, Template, Entry, ResetKeys)
			end
		end
	end

	function Function.RecolorSetup()
		local Theme = Function.MenuTheme
		local TextColor = Function.ModernText
		local Lock = Function.SliderLock
		local RC = {Selected = nil, Player = nil, Tab = "Cor", Slot = nil, H = 0, S = 0, V = 1, Snap = nil, Sig = "", Token = 0, Dirty = false, Sliders = {}, TabButtons = {}, TabFrames = {}, Chips = {}}
		Function.Recolor = RC

		local Palette = {
			Color3.fromRGB(255, 255, 255), Color3.fromRGB(200, 200, 200), Color3.fromRGB(128, 128, 128),
			Color3.fromRGB(60, 60, 60), Color3.fromRGB(20, 20, 20), Color3.fromRGB(0, 0, 0),
			Color3.fromRGB(255, 0, 0), Color3.fromRGB(255, 128, 0), Color3.fromRGB(255, 221, 0),
			Color3.fromRGB(128, 255, 0), Color3.fromRGB(0, 200, 70), Color3.fromRGB(0, 230, 200),
			Color3.fromRGB(0, 170, 255), Color3.fromRGB(0, 70, 255), Color3.fromRGB(110, 0, 255),
			Color3.fromRGB(190, 0, 255), Color3.fromRGB(255, 0, 170), Color3.fromRGB(255, 120, 150),
			Color3.fromRGB(120, 60, 20), Color3.fromRGB(200, 150, 100), Color3.fromRGB(255, 215, 170),
			Color3.fromRGB(140, 0, 30), Color3.fromRGB(0, 70, 60), Color3.fromRGB(20, 30, 90),
		}
		local SlotNames = {Primary = "Primária", Secondary = "Secundária", Tertiary = "Terciária"}

		local function Corner(Obj, Radius)
			local Item = Instance.new("UICorner")
			Item.CornerRadius = Radius or UDim.new(0, 8)
			Item.Parent = Obj
			return Item
		end

		local function Stroke(Obj, Color, Transparency, Thickness)
			local Item = Instance.new("UIStroke")
			Item.Color = Color or Theme.Accent
			Item.Transparency = Transparency or 0.5
			Item.Thickness = Thickness or 1
			Item.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
			Item.Parent = Obj
			return Item
		end

		local function StyleText(Obj, MaxSize)
			Obj.Font = Obj:IsA("TextButton") and Enum.Font.GothamBold or Enum.Font.GothamMedium
			Obj.TextColor3 = TextColor
			Obj.TextScaled = true
			local Constraint = Instance.new("UITextSizeConstraint")
			Constraint.MaxTextSize = MaxSize or 14
			Constraint.MinTextSize = 6
			Constraint.Parent = Obj
		end

		local function NewFrame(Parent, Name, Size, Position, Color, Transparency)
			local Obj = Instance.new("Frame")
			Obj.Name = Name
			Obj.Size = Size or UDim2.new(1, 0, 1, 0)
			Obj.Position = Position or UDim2.new(0, 0, 0, 0)
			Obj.BackgroundColor3 = Color or Theme.Panel
			Obj.BackgroundTransparency = Transparency or 0
			Obj.BorderSizePixel = 0
			Obj.Parent = Parent
			return Obj
		end

		local function NewLabel(Parent, Name, Text, Size, Position, MaxSize, Align)
			local Obj = Instance.new("TextLabel")
			Obj.Name = Name
			Obj.BackgroundTransparency = 1
			Obj.Size = Size
			Obj.Position = Position or UDim2.new(0, 0, 0, 0)
			Obj.Text = Text
			Obj.TextXAlignment = Align or Enum.TextXAlignment.Left
			StyleText(Obj, MaxSize)
			Obj.Parent = Parent
			return Obj
		end

		local function NewButton(Parent, Name, Text, Size, Position, Tint, MaxSize)
			local Obj = Instance.new("TextButton")
			Obj.Name = Name
			Obj.Size = Size
			Obj.Position = Position or UDim2.new(0, 0, 0, 0)
			Obj.AutoButtonColor = false
			Obj.BackgroundColor3 = Theme.Panel:Lerp(Tint or Theme.Accent, 0.25)
			Obj.BorderSizePixel = 0
			Obj.Text = Text
			StyleText(Obj, MaxSize)
			Corner(Obj, UDim.new(0, 7))
			Stroke(Obj, Tint or Theme.Accent, 0.45, 1)
			local Shade = Instance.new("UIGradient")
			Shade.Name = "ModernShade"
			Shade.Color = ColorSequence.new(Theme.Style.ShadeTop, Theme.Style.ShadeBottom)
			Shade.Rotation = 90
			Shade.Parent = Obj
			Obj.Parent = Parent
			return Obj
		end

		-- linha 3D Flat: base escura (degrau) + botão por cima; ao apertar o botão afunda no degrau.
		-- Devolve (Holder, Button); o Holder é o que entra no UIListLayout.
		local function NewFlatRow(Parent, Name, Text, Height, Tint, MaxSize)
			local Depth = Theme.Style.Depth or 3
			local Holder = Instance.new("Frame")
			Holder.Name = "FlatRow"
			Holder.BackgroundTransparency = 1
			Holder.BorderSizePixel = 0
			Holder.Size = UDim2.new(1, -4, 0, Height + Depth)
			local Base = Instance.new("Frame")
			Base.Name = "ModernDepth"
			Base.BackgroundColor3 = Theme.Edge
			Base.BorderSizePixel = 0
			Base.Position = UDim2.fromOffset(0, Depth)
			Base.Size = UDim2.new(1, 0, 0, Height)
			Corner(Base, UDim.new(0, Theme.Style.Radius))
			Base.Parent = Holder
			local Button = NewButton(Holder, Name, Text, UDim2.new(1, 0, 0, Height), nil, Tint, MaxSize)
			Button:FindFirstChildOfClass("UICorner").CornerRadius = UDim.new(0, Theme.Style.Radius)
			Button.BackgroundColor3 = Theme.Panel:Lerp(Tint or Theme.Accent, 0.08)
			local RowStroke = Button:FindFirstChildOfClass("UIStroke")
			RowStroke.Transparency = Theme.Style.StrokeRest
			local function Press(Down)
				Function.ModernTween(Button, 0.08, {Position = UDim2.fromOffset(0, Down and Depth or 0)})
			end
			Button.MouseButton1Down:Connect(function() Press(true) end)
			Button.MouseButton1Up:Connect(function() Press(false) end)
			Button.MouseLeave:Connect(function()
				Press(false)
				Function.ModernTween(RowStroke, 0.12, {Transparency = Theme.Style.StrokeRest})
			end)
			Button.MouseEnter:Connect(function()
				Function.ModernTween(RowStroke, 0.12, {Transparency = Theme.Style.StrokeHover})
			end)
			Holder.Parent = Parent
			return Holder, Button
		end

		local function NewList(Parent, Padding)
			local Layout = Instance.new("UIListLayout")
			Layout.SortOrder = Enum.SortOrder.LayoutOrder
			Layout.Padding = UDim.new(0, Padding or 6)
			Layout.Parent = Parent
			return Layout
		end

		local function BindDrag(Hit, OnPoint)
			local Handle = {Dragging = false, Source = nil}
			function Handle.Move()
			end
			function Handle.Finish()
				Handle.Dragging = false
			end
			Hit.InputBegan:Connect(function(Input)
				local Type = Input.UserInputType
				if Type ~= Enum.UserInputType.MouseButton1 and Type ~= Enum.UserInputType.Touch then
					return
				end
				if Lock.Active then
					return
				end
				Function.SliderHook()
				Lock.Active = Handle
				Lock.Input = Input
				Lock.FramePos = GUIObject.MainFrame.Position
				Handle.Dragging = true
				Handle.Source = Input
				GUIObject.Dragger.Enabled = false
				Lock.Scrolls = {}
				local Parent = Hit.Parent
				while Parent do
					if Parent:IsA("ScrollingFrame") then
						Lock.Scrolls[Parent] = Parent.ScrollingEnabled
						Parent.ScrollingEnabled = false
					end
					Parent = Parent.Parent
				end
				OnPoint(Vector2.new(Input.Position.X, Input.Position.Y))
			end)
			table.insert(AllConnect, UIS.InputChanged:Connect(function(Input)
				if not Handle.Dragging or Lock.Active ~= Handle or not Handle.Source then
					return
				end
				if Handle.Source.UserInputType == Enum.UserInputType.Touch then
					if Input ~= Handle.Source then
						return
					end
				elseif Input.UserInputType ~= Enum.UserInputType.MouseMovement then
					return
				end
				OnPoint(Vector2.new(Input.Position.X, Input.Position.Y))
			end))
			return Handle
		end

		local function NewSlider(Parent, Cfg)
			local Vertical = Cfg.Vertical == true
			local Min, Max, Step = Cfg.Min, Cfg.Max, Cfg.Step
			local Slider = {}
			local Holder = NewFrame(Parent, Cfg.Name, Cfg.Size, Cfg.Position, Theme.Deep, 0.3)
			Corner(Holder, UDim.new(0, 8))

			local Box = Instance.new("TextBox")
			Box.Name = "Value"
			Box.BackgroundColor3 = Theme.Panel
			Box.BackgroundTransparency = 0.2
			Box.BorderSizePixel = 0
			Box.ClearTextOnFocus = false
			Box.Text = ""
			StyleText(Box, 12)
			Corner(Box, UDim.new(0, 5))
			Box.Parent = Holder

			local Track = Instance.new("Frame")
			Track.Name = "Track"
			Track.BackgroundColor3 = Theme.Panel
			Track.BorderSizePixel = 0
			Corner(Track, UDim.new(1, 0))
			Track.Parent = Holder

			local Fill = Instance.new("Frame")
			Fill.Name = "Fill"
			Fill.BackgroundColor3 = Theme.Accent
			Fill.BorderSizePixel = 0
			Corner(Fill, UDim.new(1, 0))
			Fill.Parent = Track

			local Knob = Instance.new("Frame")
			Knob.Name = "Knob"
			Knob.AnchorPoint = Vector2.new(0.5, 0.5)
			Knob.Size = UDim2.new(0, 16, 0, 16)
			Knob.BackgroundColor3 = Theme.Deep
			Knob.BorderSizePixel = 0
			Knob.ZIndex = 3
			Corner(Knob, UDim.new(1, 0))
			Stroke(Knob, Theme.Accent, 0, 2)
			Knob.Parent = Track

			local Hit = Instance.new("TextButton")
			Hit.Name = "Hit"
			Hit.BackgroundTransparency = 1
			Hit.Text = ""
			Hit.AutoButtonColor = false
			Hit.ZIndex = 5
			Hit.Parent = Holder

			if Vertical then
				NewLabel(Holder, "Top", Cfg.TopLabel or "", UDim2.new(1, 0, 0, 14), UDim2.new(0, 0, 0, 2), 11, Enum.TextXAlignment.Center)
				NewLabel(Holder, "Bottom", Cfg.BottomLabel or "", UDim2.new(1, 0, 0, 14), UDim2.new(0, 0, 1, -40), 11, Enum.TextXAlignment.Center)
				Box.AnchorPoint = Vector2.new(0.5, 1)
				Box.Position = UDim2.new(0.5, 0, 1, -3)
				Box.Size = UDim2.new(0.92, 0, 0, 18)
				Track.AnchorPoint = Vector2.new(0.5, 0)
				Track.Position = UDim2.new(0.5, 0, 0, 20)
				Track.Size = UDim2.new(0, 6, 1, -62)
				Fill.AnchorPoint = Vector2.new(0, 1)
				Fill.Position = UDim2.new(0, 0, 1, 0)
				Hit.Position = UDim2.new(0, 0, 0, 16)
				Hit.Size = UDim2.new(1, 0, 1, -58)
			else
				NewLabel(Holder, "Label", Cfg.Label or "", UDim2.new(0.62, -8, 0, 16), UDim2.new(0, 8, 0, 3), 12, Enum.TextXAlignment.Left)
				Box.AnchorPoint = Vector2.new(1, 0)
				Box.Position = UDim2.new(1, -6, 0, 3)
				Box.Size = UDim2.new(0.34, 0, 0, 18)
				Track.Position = UDim2.new(0, 12, 0, 32)
				Track.Size = UDim2.new(1, -24, 0, 6)
				Hit.Position = UDim2.new(0, 0, 0, 22)
				Hit.Size = UDim2.new(1, 0, 0, 26)
			end

			local function Render(Value)
				local Alpha = math.clamp((Value - Min) / (Max - Min), 0, 1)
				if Vertical then
					Fill.Size = UDim2.new(1, 0, Alpha, 0)
					Knob.Position = UDim2.new(0.5, 0, 1 - Alpha, 0)
				else
					Fill.Size = UDim2.new(Alpha, 0, 1, 0)
					Knob.Position = UDim2.new(Alpha, 0, 0.5, 0)
				end
				if not Box:IsFocused() then
					Box.Text = Function.SliderFormat(Value, Step)
				end
			end

			function Slider.Set(Value, Silent)
				Value = math.clamp(math.floor(Value / Step + 0.5) * Step, Min, Max)
				Render(Value)
				if not Silent then
					Cfg.Set(Value)
				end
			end

			function Slider.Refresh()
				local Ok, Value = pcall(Cfg.Get)
				if Ok and typeof(Value) == "number" then
					Render(math.clamp(Value, Min, Max))
				end
			end

			BindDrag(Hit, function(Point)
				local Alpha
				if Vertical then
					Alpha = 1 - math.clamp((Point.Y - Track.AbsolutePosition.Y) / math.max(Track.AbsoluteSize.Y, 1), 0, 1)
				else
					Alpha = math.clamp((Point.X - Track.AbsolutePosition.X) / math.max(Track.AbsoluteSize.X, 1), 0, 1)
				end
				Slider.Set(Min + Alpha * (Max - Min))
			end)

			Box.FocusLost:Connect(function()
				local Number = tonumber(Box.Text)
				if Number then
					Slider.Set(Number)
				else
					Slider.Refresh()
				end
			end)

			Slider.Holder = Holder
			table.insert(RC.Sliders, Slider)
			return Slider
		end

		local function HexOf(Color)
			return string.format("#%02X%02X%02X", math.round(Color.R * 255), math.round(Color.G * 255), math.round(Color.B * 255))
		end

		local function ParseColor(Text)
			Text = string.gsub(Text, "%s", "")
			local Hex = string.match(Text, "^#?(%x%x%x%x%x%x)$")
			if Hex then
				return Color3.fromRGB(tonumber(string.sub(Hex, 1, 2), 16), tonumber(string.sub(Hex, 3, 4), 16), tonumber(string.sub(Hex, 5, 6), 16))
			end
			local Short = string.match(Text, "^#?(%x%x%x)$")
			if Short then
				return Color3.fromRGB(tonumber(string.sub(Short, 1, 1), 16) * 17, tonumber(string.sub(Short, 2, 2), 16) * 17, tonumber(string.sub(Short, 3, 3), 16) * 17)
			end
			local R, G, B = string.match(Text, "^(%d+),(%d+),(%d+)$")
			if R then
				return Color3.fromRGB(math.clamp(tonumber(R), 0, 255), math.clamp(tonumber(G), 0, 255), math.clamp(tonumber(B), 0, 255))
			end
			return nil
		end

		local function BaseColor(Name, Slot)
			for PartName in pairs(Function.RecolorParts(Name)) do
				local Part = PartList[PartName]
				if Part and Part.Recolor == Slot and typeof(Part.Color) == "table" and typeof(Part.Color.Color) == "Color3" then
					return Part.Color.Color
				end
			end
			return Color3.fromRGB(163, 162, 165)
		end

		local function ApplyLive(PlayerName, Name, Slot)
			local Data = PlayerData[PlayerName]
			if not Data or typeof(Data.CurrentPartList) ~= "table" or typeof(Data.CurrentPartList.Clothes) ~= "table" then
				return
			end
			local Value = Data.ClothesRecolor[Name] and Data.ClothesRecolor[Name][Slot]
			if typeof(Value) ~= "Color3" then
				Value = BaseColor(Name, Slot)
			end
			for PartName in pairs(Function.RecolorParts(Name)) do
				local Part = PartList[PartName]
				local Object = Data.CurrentPartList.Clothes[PartName]
				if Part and Part.Recolor == Slot and typeof(Object) == "Instance" and Object.Parent then
					Object.Color = Value
				end
			end
		end

		local function SlotColor(Name, Slot)
			local Data = PlayerData[RC.Player]
			local Value = Data and Data.ClothesRecolor[Name] and Data.ClothesRecolor[Name][Slot]
			if typeof(Value) == "Color3" then
				return Value
			end
			return BaseColor(Name, Slot)
		end

		local function CurrentX()
			local Data = PlayerData[RC.Player]
			if not Data or not RC.Selected then
				return nil
			end
			return Function.XformGet(Data, RC.Selected)
		end

		local MeshKeys = {"Reflectance", "Transparency", "TextureId"}

		local function CopyMesh(Item)
			local Out = {}
			if typeof(Item) == "table" then
				for Slot, Entry in pairs(Item) do
					if typeof(Entry) == "table" then
						local Copy = {}
						for _, Key in ipairs(MeshKeys) do
							if Entry[Key] ~= nil then
								Copy[Key] = Entry[Key]
							end
						end
						Out[Slot] = Copy
					end
				end
			end
			return Out
		end

		local function MeshSame(A, B)
			A = A or {}
			B = B or {}
			for _, Source in ipairs({A, B}) do
				for Slot in pairs(Source) do
					local EntryA = A[Slot] or {}
					local EntryB = B[Slot] or {}
					for _, Key in ipairs(MeshKeys) do
						if EntryA[Key] ~= EntryB[Key] then
							return false
						end
					end
				end
			end
			return true
		end

		local function Snapshot()
			local Data = PlayerData[RC.Player]
			local X = CurrentX()
			if not Data or not X then
				return nil
			end
			local R = {}
			for Slot, Value in pairs(Data.ClothesRecolor[RC.Selected] or {}) do
				R[Slot] = Value
			end
			return {X = {Pos = X.Pos, Rot = X.Rot, Size = X.Size, Uni = X.Uni}, R = R, M = CopyMesh(Data.ClothesMesh and Data.ClothesMesh[RC.Selected])}
		end

		local function IsDirty()
			local X = CurrentX()
			if not RC.Snap or not X then
				return false
			end
			local S = RC.Snap.X
			if S.Pos ~= X.Pos or S.Rot ~= X.Rot or S.Size ~= X.Size or S.Uni ~= X.Uni then
				return true
			end
			local Data = PlayerData[RC.Player]
			for Slot, Value in pairs(Data and Data.ClothesRecolor[RC.Selected] or {}) do
				if RC.Snap.R[Slot] ~= Value then
					return true
				end
			end
			if not MeshSame(RC.Snap.M, Data and Data.ClothesMesh and Data.ClothesMesh[RC.Selected]) then
				return true
			end
			return false
		end

		local function Revert()
			local Data = PlayerData[RC.Player]
			local X = CurrentX()
			if not Data or not X or not RC.Snap then
				return
			end
			local S = RC.Snap.X
			X.Pos, X.Rot, X.Size, X.Uni = S.Pos, S.Rot, S.Size, S.Uni
			if typeof(Data.ClothesRecolor[RC.Selected]) == "table" then
				for Slot, Value in pairs(RC.Snap.R) do
					Data.ClothesRecolor[RC.Selected][Slot] = Value
					ApplyLive(RC.Player, RC.Selected, Slot)
				end
			end
			local Before = Data.ClothesMesh and Data.ClothesMesh[RC.Selected]
			local After = CopyMesh(RC.Snap.M)
			local Changed = {}
			for _, Slot in ipairs(Function.RecolorSlots(RC.Selected)) do
				local EntryBefore = (typeof(Before) == "table" and Before[Slot]) or {}
				local EntryAfter = After[Slot] or {}
				for _, Key in ipairs(MeshKeys) do
					if EntryBefore[Key] ~= EntryAfter[Key] then
						Changed[Slot] = Changed[Slot] or {}
						Changed[Slot][Key] = true
					end
				end
			end
			if typeof(Data.ClothesMesh) ~= "table" then
				Data.ClothesMesh = {}
			end
			Data.ClothesMesh[RC.Selected] = After
			for Slot, Keys in pairs(Changed) do
				Function.MeshOverrideApply(RC.Player, RC.Selected, Slot, Keys)
			end
		end

		local Root = NewFrame(GUIObject.RecolorFrame, "RecolorUI", UDim2.new(1, -12, 1, -12), UDim2.new(0, 6, 0, 6), Theme.Deep, 1)
		RC.Root = Root

		local ListView = NewFrame(Root, "ListView", UDim2.new(1, 0, 1, 0), nil, Theme.Deep, 1)
		local CountLabel = NewLabel(ListView, "Count", "Equipado (0)", UDim2.new(1, 0, 0, 22), nil, 15, Enum.TextXAlignment.Left)
		CountLabel.TextColor3 = Theme.Accent
		CountLabel.Font = Enum.Font.GothamBold
		local ListScroll = Instance.new("ScrollingFrame")
		ListScroll.Name = "List"
		ListScroll.BackgroundTransparency = 1
		ListScroll.BorderSizePixel = 0
		ListScroll.Position = UDim2.new(0, 0, 0, 26)
		ListScroll.Size = UDim2.new(1, 0, 1, -26)
		ListScroll.ScrollBarThickness = 3
		ListScroll.ScrollBarImageColor3 = Theme.Accent
		ListScroll.ScrollingDirection = Enum.ScrollingDirection.Y
		ListScroll.CanvasSize = UDim2.new(0, 0, 0, 0)
		ListScroll.AutomaticCanvasSize = Enum.AutomaticSize.Y
		ListScroll.Parent = ListView
		NewList(ListScroll, 5)
		local EmptyLabel = NewLabel(ListView, "Empty", "Nada equipado. Equipe roupas na aba Clothes.", UDim2.new(0.9, 0, 0, 40), UDim2.new(0.05, 0, 0.3, 0), 13, Enum.TextXAlignment.Center)
		EmptyLabel.TextWrapped = true
		EmptyLabel.TextScaled = true

		local EditView = NewFrame(Root, "EditView", UDim2.new(1, 0, 1, 0), nil, Theme.Deep, 1)
		EditView.Visible = false
		local BackButton = NewButton(EditView, "Back", "◀", UDim2.new(0, 34, 0, 30), nil, Theme.Accent, 16)
		local TitleLabel = NewLabel(EditView, "Title", "", UDim2.new(1, -76, 0, 30), UDim2.new(0, 40, 0, 0), 14, Enum.TextXAlignment.Left)
		local DirtyDot = NewLabel(EditView, "Dirty", "●", UDim2.new(0, 30, 0, 30), UDim2.new(1, -30, 0, 0), 18, Enum.TextXAlignment.Center)
		DirtyDot.TextColor3 = Theme.Amber
		DirtyDot.Visible = false

		local TabBar = NewFrame(EditView, "Tabs", UDim2.new(1, 0, 0, 28), UDim2.new(0, 0, 0, 34), Theme.Deep, 1)
		local TabNames = {{"Cor", "Cor"}, {"Posicao", "Posição"}, {"Size", "Size"}, {"Rotacao", "Rotação"}}
		local Content = Instance.new("ScrollingFrame")
		Content.Name = "Content"
		Content.BackgroundTransparency = 1
		Content.BorderSizePixel = 0
		Content.Position = UDim2.new(0, 0, 0, 66)
		Content.Size = UDim2.new(1, 0, 1, -110)
		Content.ScrollBarThickness = 3
		Content.ScrollBarImageColor3 = Theme.Accent
		Content.ScrollingDirection = Enum.ScrollingDirection.Y
		Content.CanvasSize = UDim2.new(0, 0, 0, 0)
		Content.AutomaticCanvasSize = Enum.AutomaticSize.Y
		Content.Parent = EditView
		NewList(Content, 0)

		local Bar = NewFrame(EditView, "Bar", UDim2.new(1, 0, 0, 38), UDim2.new(0, 0, 1, -38), Theme.Deep, 1)
		local SaveButton = NewButton(Bar, "Save", "Salvar", UDim2.new(0.58, -3, 1, -4), UDim2.new(0, 0, 0, 2), Theme.Mint, 15)
		local UndoButton = NewButton(Bar, "Undo", "Desfazer", UDim2.new(0.42, -3, 1, -4), UDim2.new(0.58, 3, 0, 2), Theme.Amber, 13)
		local DefaultStatus = "Salvo • Save All grava no arquivo"
		local Status = NewLabel(Bar, "Status", DefaultStatus, UDim2.new(1, 0, 1, 0), nil, 12, Enum.TextXAlignment.Center)
		Status.TextColor3 = Theme.Soft
		SaveButton.Visible = false
		UndoButton.Visible = false

		for Index, Info in ipairs(TabNames) do
