		function RC.RefreshDirty()
			RC.Dirty = IsDirty()
			DirtyDot.Visible = RC.Dirty
			SaveButton.Visible = RC.Dirty
			UndoButton.Visible = RC.Dirty
			Status.Visible = not RC.Dirty
		end

		function RC.Flash(Text)
			RC.Token += 1
			local Token = RC.Token
			Status.Text = Text
			task.delay(2.5, function()
				if RC.Token == Token then
					Status.Text = DefaultStatus
				end
			end)
		end

