		ResetColor.LayoutOrder = 8

		local VSlider

		local function UpdateWheel()
			local Angle = RC.H * math.pi * 2
			Ring.Position = UDim2.new(0.5 + 0.5 * RC.S * math.cos(Angle), 0, 0.5 + 0.5 * RC.S * math.sin(Angle), 0)
			Ring.BackgroundColor3 = Color3.fromHSV(RC.H, RC.S, RC.V)
			Shade.BackgroundTransparency = RC.V
		end

		local function UpdateChips()
			if not RC.Selected then
				return
			end
			for Slot, Chip in pairs(RC.Chips) do
				local Color = SlotColor(RC.Selected, Slot)
				Chip.BackgroundColor3 = Color
				local Light = (Color.R * 0.299 + Color.G * 0.587 + Color.B * 0.114) > 0.55
				Chip.TextColor3 = Light and Color3.new(0, 0, 0) or Color3.new(1, 1, 1)
				local Line = Chip:FindFirstChildOfClass("UIStroke")
				if Line then
					Line.Color = (Slot == RC.Slot) and Theme.Mint or Theme.Accent
					Line.Thickness = (Slot == RC.Slot) and 3 or 1
					Line.Transparency = (Slot == RC.Slot) and 0 or 0.5
				end
			end
		end

		local function CommitColor(Color, FromHSV)
			local Data = PlayerData[RC.Player]
			if not Data or not RC.Selected or not RC.Slot then
				return
			end
			if typeof(Data.ClothesRecolor[RC.Selected]) ~= "table" then
				Data.ClothesRecolor[RC.Selected] = {}
			end
			Data.ClothesRecolor[RC.Selected][RC.Slot] = Color
			if not FromHSV then
				RC.H, RC.S, RC.V = Color:ToHSV()
			end
			ApplyLive(RC.Player, RC.Selected, RC.Slot)
			UpdateWheel()
			if VSlider then
				VSlider.Refresh()
			end
			if not CodeBox:IsFocused() then
				CodeBox.Text = HexOf(Color)
			end
			UpdateChips()
			RC.RefreshDirty()
		end

		function RC.SelectSlot(Slot)
			RC.Slot = Slot
			local Color = SlotColor(RC.Selected, Slot)
			RC.H, RC.S, RC.V = Color:ToHSV()
			UpdateWheel()
			if VSlider then
				VSlider.Refresh()
			end
			if RC.MeshRefresh then
				RC.MeshRefresh()
			end
			CodeBox.Text = HexOf(Color)
			UpdateChips()
		end

		function RC.BuildSlots()
			for _, Chip in pairs(RC.Chips) do
				Chip:Destroy()
			end
			RC.Chips = {}
			local Slots = Function.RecolorSlots(RC.Selected)
			NoSlot.Visible = #Slots == 0
			ColorBody.Visible = #Slots > 0
			SlotRow.Visible = #Slots > 0
			for Index, Slot in ipairs(Slots) do
				local Chip = NewButton(SlotRow, Slot, SlotNames[Slot] or Slot, UDim2.new(1 / #Slots, -4, 1, 0), nil, Theme.Accent, 13)
				Chip.LayoutOrder = Index
				Chip.MouseButton1Click:Connect(function()
					RC.SelectSlot(Slot)
				end)
				RC.Chips[Slot] = Chip
			end
			if #Slots > 0 then
				RC.SelectSlot(Slots[1])
			end
		end

		BindDrag(WheelHit, function(Point)
			local Center = Wheel.AbsolutePosition + Wheel.AbsoluteSize / 2
			local Delta = Point - Center
			local Radius = math.max(Wheel.AbsoluteSize.X / 2, 1)
			RC.S = math.clamp(Delta.Magnitude / Radius, 0, 1)
			RC.H = (math.deg(math.atan2(Delta.Y, Delta.X)) % 360) / 360
			CommitColor(Color3.fromHSV(RC.H, RC.S, RC.V), true)
		end)

		VSlider = NewSlider(ColorBody, {Name = "Brilho", Label = "Brilho", Min = 0, Max = 1, Step = 0.01, Size = UDim2.new(1, 0, 0, 46),
			Get = function() return RC.V end,
			Set = function(Value)
				RC.V = Value
				CommitColor(Color3.fromHSV(RC.H, RC.S, RC.V), true)
			end})
		VSlider.Holder.LayoutOrder = 2

		-- [v33] EDIT + RECOLOR: reflexão, transparência e ID de textura logo abaixo do Brilho.
		-- Valem para o slot selecionado (Primária/Secundária/Terciária), igual à cor.
		do
			local function CurrentEntry(Create)
				local Data = PlayerData[RC.Player]
				if not Data or not RC.Selected or not RC.Slot then
					return nil
				end
				return Function.MeshOverrideGet(Data, RC.Selected, RC.Slot, Create)
			end

			local function TemplateValue(Key, Kind, Default)
				if RC.Selected and RC.Slot then
					for PartName in pairs(Function.RecolorParts(RC.Selected)) do
						local Part = PartList[PartName]
						if Part and Part.Recolor == RC.Slot then
							local Value = Part[Key]
							if typeof(Value) == Kind then
								return Value
							end
						end
					end
				end
				return Default
			end

			local function MeshSet(Key, Value)
				local Entry = CurrentEntry(true)
				if not Entry then
					return
				end
				Entry[Key] = Value
				Function.MeshOverrideApply(RC.Player, RC.Selected, RC.Slot, Value == nil and {[Key] = true} or nil)
				RC.RefreshDirty()
			end

			local MeshSliders = {}
			local function MeshSlider(Name, Label, Key, Order)
				local Slider = NewSlider(ColorBody, {Name = Name, Label = Label, Min = 0, Max = 1, Step = 0.01, Size = UDim2.new(1, 0, 0, 46),
					Get = function()
						local Entry = CurrentEntry(false)
						local Value = Entry and Entry[Key]
						if typeof(Value) == "number" then
							return Value
						end
						return TemplateValue(Key, "number", 0)
					end,
					Set = function(Value)
						MeshSet(Key, Value)
					end})
				Slider.Holder.LayoutOrder = Order
				table.insert(MeshSliders, Slider)
			end
			MeshSlider("Reflexao", "Reflexão", "Reflectance", 3)
			MeshSlider("Transparencia", "Transparência", "Transparency", 4)

			local TexHolder = NewFrame(ColorBody, "TextureRow", UDim2.new(1, 0, 0, 58), nil, Theme.Deep, 0.3)
			TexHolder.LayoutOrder = 5
			Corner(TexHolder, UDim.new(0, 8))
			NewLabel(TexHolder, "Label", "ID de textura (vazio = original)", UDim2.new(1, -16, 0, 16), UDim2.new(0, 8, 0, 3), 12, Enum.TextXAlignment.Left)
			local TexBox = Instance.new("TextBox")
			TexBox.Name = "TextureBox"
			TexBox.Position = UDim2.new(0, 6, 0, 24)
			TexBox.Size = UDim2.new(0.68, -9, 0, 28)
			TexBox.BackgroundColor3 = Theme.Panel
			TexBox.BorderSizePixel = 0
			TexBox.ClearTextOnFocus = false
			TexBox.PlaceholderText = "número ou rbxassetid://..."
			TexBox.PlaceholderColor3 = Theme.Soft
			TexBox.Text = ""
			StyleText(TexBox, 13)
			Corner(TexBox, UDim.new(0, 7))
			Stroke(TexBox, Theme.Accent, 0.45, 1)
			TexBox.Parent = TexHolder
			local TexOk = NewButton(TexHolder, "Ok", "OK", UDim2.new(0.32, -9, 0, 28), UDim2.new(0.68, 3, 0, 24), Theme.Mint, 14)

			-- "" limpa o override; nil = texto inválido
			local function ParseTexture(Text)
				local Trimmed = string.match(Text, "^%s*(.-)%s*$")
				if Trimmed == "" then
					return ""
				end
				if string.match(Trimmed, "^%d+$") then
					return "rbxassetid://" .. Trimmed
				end
				if string.match(Trimmed, "^rbxassetid://%d+$")
					or string.sub(Trimmed, 1, 11) == "rbxasset://"
					or string.match(Trimmed, "^https?://www%.roblox%.com/asset") then
					return Trimmed
				end
				return nil
			end

			function RC.MeshRefresh()
				for _, Slider in ipairs(MeshSliders) do
					Slider.Refresh()
				end
				local Entry = CurrentEntry(false)
				local Texture = Entry and Entry.TextureId
				TexBox.Text = typeof(Texture) == "string" and Texture or ""
			end

			local function ApplyTexture()
				local Id = ParseTexture(TexBox.Text)
				if Id == nil then
					RC.Flash("ID de textura inválido")
					RC.MeshRefresh()
					return
				end
				if Id == "" then
					local Entry = CurrentEntry(false)
					if not Entry or Entry.TextureId == nil then
						return
					end
					MeshSet("TextureId", nil)
				else
					MeshSet("TextureId", Id)
				end
				RC.MeshRefresh()
			end
			TexBox.FocusLost:Connect(ApplyTexture)
			TexOk.MouseButton1Click:Connect(ApplyTexture)
		end

