		local PosReset = NewButton(PosColumn, "Reset", "Resetar posição", UDim2.new(1, 0, 0, 32), UDim2.new(0, 0, 0, 104), Theme.Danger, 13)

		local SizePage = RC.TabFrames.Size
		local SizeSliders = {}
		SizeSliders[1] = NewSlider(SizePage, {Name = "Uni", Label = "Size geral", Min = 0.1, Max = 3, Step = 0.01, Size = UDim2.new(1, 0, 0, 46),
