		SizeSliders[2] = NewSlider(SizePage, {Name = "SX", Label = "Largura (X)", Min = 0.1, Max = 3, Step = 0.01, Size = UDim2.new(1, 0, 0, 46),
			Get = function() local X = CurrentX() return X and X.Size.X or 1 end,
