		SizeSliders[3] = NewSlider(SizePage, {Name = "SY", Label = "Altura (Y)", Min = 0.1, Max = 3, Step = 0.01, Size = UDim2.new(1, 0, 0, 46),
			Get = function() local X = CurrentX() return X and X.Size.Y or 1 end,
			Set = function(Value) local X = CurrentX() if X then X.Size = Vector3.new(X.Size.X, Value, X.Size.Z) RC.RefreshDirty() end end})
		SizeSliders[4] = NewSlider(SizePage, {Name = "SZ", Label = "Espessura (Z)", Min = 0.1, Max = 3, Step = 0.01, Size = UDim2.new(1, 0, 0, 46),
			Get = function() local X = CurrentX() return X and X.Size.Z or 1 end,
			Set = function(Value) local X = CurrentX() if X then X.Size = Vector3.new(X.Size.X, X.Size.Y, Value) RC.RefreshDirty() end end})
		for Index, Slider in ipairs(SizeSliders) do
			Slider.Holder.LayoutOrder = Index
