			end
		end

		PosReset.MouseButton1Click:Connect(function()
			local X = CurrentX()
			if X then
				X.Pos = Vector3.new(0, 0, 0)
				RC.RefreshControls()
				RC.RefreshDirty()
			end
		end)
		SizeReset.MouseButton1Click:Connect(function()
			local X = CurrentX()
			if X then
				X.Size = Vector3.new(1, 1, 1)
				X.Uni = 1
				RC.RefreshControls()
				RC.RefreshDirty()
			end
		end)
		RotReset.MouseButton1Click:Connect(function()
			local X = CurrentX()
			if X then
				X.Rot = Vector3.new(0, 0, 0)
				RC.RefreshControls()
				RC.RefreshDirty()
			end
		end)

		function RC.SelectTab(Name)
			RC.Tab = Name
			for Key, Page in pairs(RC.TabFrames) do
				Page.Visible = Key == Name
			end
			for Key, Button in pairs(RC.TabButtons) do
				local Active = Key == Name
				Button.BackgroundColor3 = Theme.Panel:Lerp(Theme.Accent, Active and 0.55 or 0.15)
			end
			Content.CanvasPosition = Vector2.new(0, 0)
		end

		for Key, Button in pairs(RC.TabButtons) do
			Button.MouseButton1Click:Connect(function()
				RC.SelectTab(Key)
			end)
		end

		local function IsCustom(Data, Name)
			local X = Data.ClothesXform and Data.ClothesXform[Name]
			if typeof(X) == "table" then
				if X.Pos ~= Vector3.new(0, 0, 0) or X.Rot ~= Vector3.new(0, 0, 0) or X.Size ~= Vector3.new(1, 1, 1) or X.Uni ~= 1 then
					return true
				end
			end
			for _, Value in pairs(Data.ClothesRecolor[Name] or {}) do
				if typeof(Value) == "Color3" then
					return true
				end
			end
			local MeshItem = typeof(Data.ClothesMesh) == "table" and Data.ClothesMesh[Name]
			if typeof(MeshItem) == "table" then
				for _, Entry in pairs(MeshItem) do
					if typeof(Entry) == "table" and next(Entry) ~= nil then
						return true
					end
				end
			end
			return false
		end

		function RC.Signature()
			local Data = PlayerData[SelectPlayer]
			if not Data then
				return ""
			end
			local Parts = {SelectPlayer}
			for _, Name in ipairs(Data.CurrentClothes) do
				table.insert(Parts, tostring(Name))
			end
			return table.concat(Parts, "|")
		end

		function RC.RefreshList()
			for _, Child in ipairs(ListScroll:GetChildren()) do
				if Child:IsA("TextButton") or Child.Name == "FlatRow" then
					Child:Destroy()
				end
			end
			local Data = PlayerData[SelectPlayer]
			local Count = 0
			if Data then
				for Index, Name in ipairs(Data.CurrentClothes) do
					if Name ~= "nil" and Clothes[Name] then
						Count += 1
						local Holder, Row = NewFlatRow(ListScroll, Name, Name, 36, Theme.Accent, 14)
						Holder.LayoutOrder = Index
						Row.TextXAlignment = Enum.TextXAlignment.Left
						local Pad = Instance.new("UIPadding")
						Pad.PaddingLeft = UDim.new(0, 10)
						Pad.PaddingRight = UDim.new(0, 26)
						Pad.Parent = Row
						if IsCustom(Data, Name) then
							local Mark = NewLabel(Row, "Mark", "●", UDim2.new(0, 20, 1, 0), UDim2.new(1, 22, 0, 0), 14, Enum.TextXAlignment.Center)
							Mark.TextColor3 = Theme.Mint
						end
						Row.MouseButton1Click:Connect(function()
							RC.Open(Name)
						end)
					end
				end
			end
			CountLabel.Text = "Equipado (" .. Count .. ")"
			EmptyLabel.Visible = Count == 0
			RC.Sig = RC.Signature()
		end

		function RC.Close(Discard)
			if RC.Selected and Discard and IsDirty() then
				Revert()
			end
			RC.Selected = nil
			RC.Snap = nil
			RC.Slot = nil
			EditView.Visible = false
			ListView.Visible = true
			RC.RefreshList()
		end

		function RC.Open(Name)
			local Data = PlayerData[SelectPlayer]
			if not Data or not Clothes[Name] then
				return
			end
			if RC.Selected then
				RC.Close(true)
			end
			Function.RecolorInitSlots(SelectPlayer, Name)
			RC.Player = SelectPlayer
			RC.Selected = Name
			RC.Snap = Snapshot()
			TitleLabel.Text = Name
			ListView.Visible = false
			EditView.Visible = true
			RC.BuildSlots()
			RC.SelectTab(RC.Tab)
			RC.RefreshControls()
			RC.RefreshDirty()
		end

		BackButton.MouseButton1Click:Connect(function()
			RC.Close(true)
		end)

		SaveButton.MouseButton1Click:Connect(function()
			if not RC.Selected then
				return
			end
			RC.Snap = Snapshot()
			RC.RefreshDirty()
			RC.Flash("Salvo ✓  use Save All p/ gravar")
		end)

		UndoButton.MouseButton1Click:Connect(function()
			if not RC.Selected then
				return
			end
			local Previous = RC.Slot
			Revert()
			RC.BuildSlots()
			if Previous and RC.Chips[Previous] then
				RC.SelectSlot(Previous)
			end
			RC.RefreshControls()
			RC.RefreshDirty()
		end)

		local function FitWheel()
			local Size = math.clamp(Content.AbsoluteSize.X - 28, 80, 170)
			Wheel.Size = UDim2.new(0, Size, 0, Size)
			WheelHolder.Size = UDim2.new(1, 0, 0, Size + 10)
		end
		table.insert(AllConnect, Content:GetPropertyChangedSignal("AbsoluteSize"):Connect(FitWheel))
		FitWheel()

		GUIObject.RecolorListFrame.Visible = false
		table.insert(AllConnect, GUIObject.RecolorFrame:GetPropertyChangedSignal("Visible"):Connect(function()
			if GUIObject.RecolorFrame.Visible then
				if RC.Selected and (RC.Player ~= SelectPlayer or not PlayerData[SelectPlayer] or not table.find(PlayerData[SelectPlayer].CurrentClothes, RC.Selected)) then
					RC.Close(RC.Player ~= SelectPlayer)
				end
				if not RC.Selected then
					RC.RefreshList()
				end
				task.defer(FitWheel)
			end
		end))

		task.spawn(function()
			while GUIObject.Screen and GUIObject.Screen.Parent do
				task.wait(0.4)
				if GUIObject.RecolorFrame.Visible then
					local Data = PlayerData[SelectPlayer]
					if RC.Selected and (RC.Player ~= SelectPlayer or not Data or not table.find(Data.CurrentClothes, RC.Selected)) then
						RC.Close(RC.Player ~= SelectPlayer)
					end
					if RC.Signature() ~= RC.Sig and not RC.Selected then
						RC.RefreshList()
					end
				end
			end
		end)

		RC.RefreshList()
		if GUIObject.RecolorFrame.Visible then
			task.defer(FitWheel)
		end
	end

	local HPButtons = {}
	function Function.GUIFunc()
		for _, Button in pairs(GUIObject.ButtonFrame:GetChildren()) do
			if Button:FindFirstChildOfClass("TextButton") then
				Button:FindFirstChildOfClass("TextButton").MouseButton1Click:Connect(function()
					for _, Page in pairs(GUIObject.PageFrame:GetChildren()) do
						if Page:IsA("Frame") or Page:IsA("ScrollingFrame") then
							Page.Visible = false
						end
					end

					local Page = GUIObject.PageFrame:WaitForChild(Button.Name)
					Page.Visible = true
					if Page.Name == "HP" then
						for i, v in pairs(GUIObject.HPListFrame:GetChildren()) do
							if not v:IsA("UIGridLayout") then
								v:Destroy()
							end
						end
						for i, v in pairs(HPButtons) do
							v:Disconnect()
							table.remove(AllConnect,table.find(AllConnect, v))
						end
						HPButtons = {}

						for i, v in pairs(PlayerData[SelectPlayer].CurrentClothes) do
							local button = Function.ButtonCreate(v, GUIObject.HPListFrame, false, {Color = Color3.new(1,1,1), Text = v.. ": nil"})
							button:FindFirstChildOfClass("UIAspectRatioConstraint"):Destroy()
							local b = button:FindFirstChildOfClass("TextButton")

							local switch = PlayerData[SelectPlayer].ClothesHP[v] or 0
							if switch ~= 0 then
								if PlayerData[SelectPlayer].ClothesHP[v].HP == "TopHP" then
									if PlayerData[SelectPlayer].ClothesHP[v].Inverse == true then
										switch = 3
										b.Text = v.. ": InverseTop"
									else
										switch = 1
										b.Text = v.. ": TopHP"
									end
								elseif PlayerData[SelectPlayer].ClothesHP[v].HP == "BottomHP" then
									if PlayerData[SelectPlayer].ClothesHP[v].Inverse == true then
										switch = 4
										b.Text = v.. ": InverseBottom"
									else
										switch = 2
										b.Text = v.. ": BottomHP"
									end
								end
							else
								if switch == 0 then
									b.Text = v.. ": nil"
								else
									b.Text = v.. ": "..switch
									switch = 0
								end
							--[[else
								if Clothes[v] then
									switch = Clothes[v].HP
									if Clothes[v].HP == 1 then
										b.Text = v.. ": TopHP"
										PlayerData[SelectPlayer].ClothesHP[v] = {["HP"]="TopHP",["Inverse"]=false}
									elseif Clothes[v].HP == 2 then
