						local reFormat = "local import = {".. Text .."} return import"
						success, ouput = pcall(function()
							return loadstring(reFormat)()
						end)
					end
					if success then
						local function sanitize(str)
							for _, char in ipairs({"/", "<", ">", "?", "*", "|", "\ ","\\",'"', ":"}) do
								str = string.gsub(str, char, "_")
