	-- ====================================================================================
	-- // ARRASTAR O MENU + 4 POSIÇÕES FIXAS (topo / baixo / esquerda / direita) // --
	-- Substitui o UIDragDetector antigo (que arrastava o menu junto com sliders/listas).
	--  * Só começa a arrastar pela BARRA DO TÍTULO (RoClothes modded) ou por um espaço vazio do painel
	--    (botões, caixas, sliders e listas rolantes NÃO movem mais o menu).
	--  * Precisa SEGURAR 1.5s parado antes de poder arrastar (toque/clique rápido ou deslizar o dedo nunca move o menu).
	--    Se mexer o dedo/mouse antes dos 1.5s, cancela. Quando completa, aparecem os 4 previews e aí é só arrastar.
	--  * Enquanto arrasta, mostra o preview da posição mais próxima; ao soltar, o menu desliza até lá.
	--  * GUIObject.Dragger.Enabled continua funcionando (os sliders usam para travar o arrasto).
	-- ====================================================================================
	do
		local Theme = Function.MenuTheme
		local MainFrame = GUIObject.MainFrame
		local ScreenGui = GUIObject.Screen
		local MarginPx = 12
		local HoldTime = 1.5      -- segundos segurando parado até liberar o arrasto
		local HoldTolerance = 12  -- px de tremida do dedo/mouse permitida durante a espera
		local SpotNames = {"TOP", "BOTTOM", "LEFT", "RIGHT"}

		-- referência do "espaço da tela" (mesma origem onde Position/AbsolutePosition do menu são medidos)
		local Probe = Instance.new("Frame")
		Probe.Name = "DragSpace"
		Probe.BackgroundTransparency = 1
		Probe.BorderSizePixel = 0
		Probe.Active = false
		Probe.Size = UDim2.fromScale(1, 1)
		Probe.ZIndex = 0
		Probe.Parent = ScreenGui

		-- área de pegar (barra do título), fora do MainFrame para não ser "estilizada" pelos temas
		local Handle = Instance.new("Frame")
		Handle.Name = "DragHandle"
		Handle.BackgroundTransparency = 1
		Handle.BorderSizePixel = 0
		Handle.Active = true
		Handle.ZIndex = 20
		Handle.Size = UDim2.fromOffset(0, 0)
		Handle.Parent = ScreenGui

		-- previews das 4 posições
		local Ghosts = {}
		for Index, Name in ipairs(SpotNames) do
			local Frame = Instance.new("Frame")
			Frame.Name = "SnapPreview" .. Name
			Frame.BackgroundColor3 = Theme.Mint
			Frame.BackgroundTransparency = 1
			Frame.BorderSizePixel = 0
			Frame.Active = false
			Frame.Visible = false
			Frame.ZIndex = 50

			local Corner = Instance.new("UICorner")
			Corner.CornerRadius = UDim.new(0, 16)
			Corner.Parent = Frame

			local Stroke = Instance.new("UIStroke")
			Stroke.Color = Theme.Accent
			Stroke.Thickness = 2
			Stroke.Transparency = 0.8
			Stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
			Stroke.Parent = Frame

			local Label = Instance.new("TextLabel")
			Label.BackgroundTransparency = 1
			Label.Size = UDim2.fromScale(1, 1)
			Label.Font = Enum.Font.Code
			Label.Text = Name
			Label.TextSize = 22
			Label.TextColor3 = Theme.Mint
			Label.TextTransparency = 1
			Label.TextStrokeTransparency = 1
			Label.ZIndex = 51
			Label.Parent = Frame

			Frame.Parent = ScreenGui
			Ghosts[Index] = {Frame = Frame, Stroke = Stroke, Label = Label}
		end

		local Drag = {
			Input = nil, Moving = false, Start = Vector2.zero, FramePos = nil, HoldStart = 0,
			BoundsPos = Vector2.zero, BoundsSize = Vector2.zero, Spot = nil,
		}
		local SnapRemain = Vector2.zero

		local function Fit(Value, Low, High)
			if High < Low then return Low end
			return math.clamp(Value, Low, High)
		end

		-- retângulo que contém o menu inteiro (painel + abas + nome + espelho)
		local function Bounds()
			local MinX, MinY, MaxX, MaxY = math.huge, math.huge, -math.huge, -math.huge
			local Found = false
			for _, Name in ipairs({"PageFrame", "ButtonFrame", "NameFrame", "CharacterPreviewFrame"}) do
				local Obj = GUIObject[Name]
				if Obj and Obj:IsA("GuiObject") and Obj.Visible then
					local P, S = Obj.AbsolutePosition, Obj.AbsoluteSize
					if S.X > 0 and S.Y > 0 then
						MinX = math.min(MinX, P.X)
						MinY = math.min(MinY, P.Y)
						MaxX = math.max(MaxX, P.X + S.X)
						MaxY = math.max(MaxY, P.Y + S.Y)
						Found = true
					end
				end
			end
			if not Found then return nil end
			return Vector2.new(MinX, MinY), Vector2.new(MaxX - MinX, MaxY - MinY)
		end

		-- canto superior esquerdo do menu em cada posição fixa
		local function SpotPosition(Index, Size)
			local O, S = Probe.AbsolutePosition, Probe.AbsoluteSize
			local X = O.X + (S.X - Size.X) / 2
			local Y = O.Y + (S.Y - Size.Y) / 2
			if Index == 1 then
				Y = O.Y + MarginPx
			elseif Index == 2 then
				Y = O.Y + S.Y - Size.Y - MarginPx
			elseif Index == 3 then
				X = O.X + MarginPx
			else
				X = O.X + S.X - Size.X - MarginPx
			end
			X = Fit(X, O.X, O.X + S.X - Size.X)
			Y = Fit(Y, O.Y, O.Y + S.Y - Size.Y)
			return Vector2.new(X, Y)
		end

		local function Highlight(Index)
			Drag.Spot = Index
			local Info = TweenInfo.new(0.12, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
			for I, G in ipairs(Ghosts) do
				local On = I == Index
				TS:Create(G.Frame, Info, {BackgroundTransparency = On and 0.82 or 1}):Play()
				TS:Create(G.Stroke, Info, {
					Color = On and Theme.Mint or Theme.Accent,
					Thickness = On and 3 or 2,
					Transparency = On and 0.05 or 0.78,
				}):Play()
				TS:Create(G.Label, Info, {TextTransparency = On and 0.1 or 1}):Play()
			end
		end

		local function HideGhosts()
			local Info = TweenInfo.new(0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
			for _, G in ipairs(Ghosts) do
				TS:Create(G.Frame, Info, {BackgroundTransparency = 1}):Play()
				TS:Create(G.Stroke, Info, {Transparency = 1}):Play()
				TS:Create(G.Label, Info, {TextTransparency = 1}):Play()
				task.delay(0.18, function()
					if not Drag.Moving and G.Frame.Parent then
						G.Frame.Visible = false
					end
				end)
			end
		end

		local function CanStart()
			if not GUIObject.Dragger.Enabled then return false end
			local Lock = Function.SliderLock
			if Lock and Lock.Active then return false end
			local Anim = Function.Anim
			if Anim and Anim.Menu and Anim.Menu.Session then return false end
			return ScreenGui.Enabled
		end

		local function Pointer(Input)
			if Input.UserInputType == Enum.UserInputType.Touch then
				return Vector2.new(Input.Position.X, Input.Position.Y)
			end
			return UIS:GetMouseLocation()
		end

		local function Begin(Input)
			if Drag.Input or not CanStart() then return end
			local Type = Input.UserInputType
			if Type ~= Enum.UserInputType.MouseButton1 and Type ~= Enum.UserInputType.Touch then return end
			Drag.Input = Input
			Drag.Moving = false
			Drag.Start = Pointer(Input)
			Drag.HoldStart = os.clock()
		end

		local function Engage()
			local Pos, Size = Bounds()
			if not Pos then
				Drag.Input = nil
				return
			end
			SnapRemain = Vector2.zero -- se ainda estava deslizando, o novo arrasto assume
			Drag.Moving = true
			Drag.FramePos = MainFrame.Position
			Drag.BoundsPos = Pos
			Drag.BoundsSize = Size
			Drag.Spot = nil
			local O = Probe.AbsolutePosition
			for Index, G in ipairs(Ghosts) do
				local Target = SpotPosition(Index, Size)
				G.Frame.Position = UDim2.fromOffset(math.round(Target.X - O.X), math.round(Target.Y - O.Y))
				G.Frame.Size = UDim2.fromOffset(math.round(Size.X), math.round(Size.Y))
				G.Frame.BackgroundTransparency = 1
				G.Stroke.Transparency = 1
				G.Label.TextTransparency = 1
				G.Frame.Visible = true
			end
		end

		local function Update(Cursor)
			local O, S = Probe.AbsolutePosition, Probe.AbsoluteSize
			local Size = Drag.BoundsSize
			local Wanted = Drag.BoundsPos + (Cursor - Drag.Start)
			-- não deixa o menu sumir da tela (sempre sobra um pedaço pra pegar)
			local Pos = Vector2.new(
				Fit(Wanted.X, O.X - Size.X + 80, O.X + S.X - 80),
				Fit(Wanted.Y, O.Y, O.Y + S.Y - 40)
			)
			local Delta = Pos - Drag.BoundsPos
			MainFrame.Position = Drag.FramePos + UDim2.fromOffset(math.round(Delta.X), math.round(Delta.Y))

			local Center = Pos + Size / 2
			local Best, BestDist = 1, math.huge
			for Index = 1, #Ghosts do
				local Dist = (SpotPosition(Index, Size) + Size / 2 - Center).Magnitude
				if Dist < BestDist then
					Best, BestDist = Index, Dist
				end
			end
			if Best ~= Drag.Spot then
				Highlight(Best)
			end
		end

		local function Finish(Cancel)
			if not Drag.Input then return end
			local Moving = Drag.Moving
			Drag.Input = nil
			Drag.Moving = false
			if not Moving then return end
			HideGhosts()
			if Drag.Spot and not Cancel then
				local Pos, Size = Bounds()
				if Pos then
					local Target = SpotPosition(Drag.Spot, Size)
					SnapRemain = Vector2.new(math.round(Target.X - Pos.X), math.round(Target.Y - Pos.Y))
				end
			end
		end

		-- onde pode começar o arrasto: espaço vazio do painel + barra do título
		table.insert(AllConnect, MainFrame.InputBegan:Connect(Begin))
		table.insert(AllConnect, Handle.InputBegan:Connect(Begin))

		table.insert(AllConnect, UIS.InputChanged:Connect(function(Input)
			local Held = Drag.Input
			if not Held then return end
			if Held.UserInputType == Enum.UserInputType.Touch then
				if Input ~= Held then return end
			elseif Input.UserInputType ~= Enum.UserInputType.MouseMovement then
				return
			end
			local Cursor = Pointer(Held)
			if not Drag.Moving then
				-- ainda esperando os 1.5s: o RenderStepped (abaixo) controla o tempo.
				-- aqui só cancela se um slider/lista pegou o toque, ou se mexeu antes da hora
				if not CanStart() or (Cursor - Drag.Start).Magnitude > HoldTolerance then
					Drag.Input = nil
				end
				return
			end
			Update(Cursor)
		end))

		table.insert(AllConnect, UIS.InputEnded:Connect(function(Input)
			local Held = Drag.Input
			if not Held then return end
			if Input == Held
				or (Held.UserInputType == Enum.UserInputType.MouseButton1 and Input.UserInputType == Enum.UserInputType.MouseButton1) then
				Finish(false)
			end
		end))

		-- menu fechou no meio do arrasto
		table.insert(AllConnect, ScreenGui:GetPropertyChangedSignal("Enabled"):Connect(function()
			if not ScreenGui.Enabled then
				Finish(true)
			end
		end))

		-- a cada frame: acompanha a barra do título e desliza o menu até a posição escolhida
		table.insert(AllConnect, RS.RenderStepped:Connect(function()
			if not ScreenGui.Enabled then return end
			local Name = GUIObject.NameFrame
			local O = Probe.AbsolutePosition
			local NP, NS = Name.AbsolutePosition, Name.AbsoluteSize
			local MP, MS = MainFrame.AbsolutePosition, MainFrame.AbsoluteSize
			local Pad = 8
			local NewPos = UDim2.fromOffset(math.round(MP.X - O.X), math.round(NP.Y - O.Y - Pad))
			local NewSize = UDim2.fromOffset(math.round(MS.X), math.round(NS.Y + Pad * 2))
			if Handle.Position ~= NewPos then Handle.Position = NewPos end
			if Handle.Size ~= NewSize then Handle.Size = NewSize end

			-- segurando: passou o tempo parado? libera o arrasto (mostra os 4 previews)
			if Drag.Input and not Drag.Moving then
				local Cursor = Pointer(Drag.Input)
				if not CanStart() or (Cursor - Drag.Start).Magnitude > HoldTolerance then
					Drag.Input = nil -- mexeu antes da hora ou outro elemento assumiu: cancela
				elseif os.clock() - Drag.HoldStart >= HoldTime then
					Engage()
					if Drag.Moving then
						Drag.Start = Cursor -- o arrasto começa daqui (sem pulo)
						Update(Cursor)
					end
				end
			end

			if SnapRemain.X ~= 0 or SnapRemain.Y ~= 0 then
				if Drag.Moving or (Function.Anim and Function.Anim.Menu and Function.Anim.Menu.Session) then
					SnapRemain = Vector2.zero
					return
				end
				-- 30% do que falta por frame, no mínimo 1px (UDim2 só aceita pixels inteiros)
				local function Step(Value)
					local Part = Value * 0.3
					if Part == 0 then return 0 end
					Part = Part > 0 and math.ceil(Part) or math.floor(Part)
					if math.abs(Part) > math.abs(Value) then Part = Value end
					return Part
				end
				local DX, DY = Step(SnapRemain.X), Step(SnapRemain.Y)
				MainFrame.Position = MainFrame.Position + UDim2.fromOffset(DX, DY)
				SnapRemain = Vector2.new(SnapRemain.X - DX, SnapRemain.Y - DY)
			end
		end))
	end

	GUIObject.PageFrame.Name = "PageFrame"
	GUIObject.PageFrame.Parent = GUIObject.MainFrame
	GUIObject.PageFrame.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
	GUIObject.PageFrame.BorderColor3 = Color3.fromRGB(0, 0, 0)
	GUIObject.PageFrame.Position = UDim2.new(0,0,0)
	GUIObject.PageFrame.Size = UDim2.new(1,0,1,0)

	GUIObject.UIGradient.Color = ColorSequence.new{ColorSequenceKeypoint.new(0.00, Color3.fromRGB(27, 27, 27)), ColorSequenceKeypoint.new(1.00, Color3.fromRGB(50, 50, 50))}
	GUIObject.UIGradient.Rotation = -90
	GUIObject.UIGradient.Parent = GUIObject.PageFrame

	GUIObject.UICorner.CornerRadius = UDim.new(0.100000001, 0)
	GUIObject.UICorner.Parent = GUIObject.PageFrame

