	-- ordem das categorias: mantém a ordem de criação, mas "Options" fica logo depois de "Settings"
	function Function.OrderTabs()
		local Index = 0
		for _, Tab in ipairs(GUIObject.ButtonFrame:GetChildren()) do
			if Tab:IsA("Frame") and Tab ~= GUIObject.optionsframeButton then
				Index = Index + 1
				Tab.LayoutOrder = Index * 2
			end
		end
		local Settings = GUIObject.ButtonFrame:FindFirstChild("Menu2")
		if Settings then
			GUIObject.optionsframeButton.LayoutOrder = Settings.LayoutOrder + 1
		else
			GUIObject.optionsframeButton.LayoutOrder = Index * 2 + 2
		end
	end
	Function.OrderTabs()

