		local function MakeStep(Name, Text, Anchor, OffsetX)
			local Step = Instance.new("TextButton")
			Step.Name = Name
			Step.Parent = SizeFrame
			Step.AnchorPoint = Vector2.new(Anchor, 0.5)
			Step.Position = UDim2.new(Anchor, OffsetX, 0.5, 0)
			Step.SizeConstraint = Enum.SizeConstraint.RelativeYY
			Step.Size = UDim2.fromScale(0.76, 0.76)
			Step.AutoButtonColor = false
			Step.BackgroundColor3 = Theme.Deep
			Step.BorderSizePixel = 0
			Step.ZIndex = 3
			Step.Font = Enum.Font.GothamBold
			Step.Text = Text
			Step.TextColor3 = Theme.Mint
			Step.TextScaled = true
			Function.ModernCorner(Step, UDim.new(0, 6))
			local StepPad = Instance.new("UIPadding")
			StepPad.PaddingTop = UDim.new(0.18, 0)
			StepPad.PaddingBottom = UDim.new(0.18, 0)
			StepPad.PaddingLeft = UDim.new(0.18, 0)
			StepPad.PaddingRight = UDim.new(0.18, 0)
			StepPad.Parent = Step
			local StepStroke = Instance.new("UIStroke")
