	Function.ClearSavedState = {Clicks = 0, Token = 0, Busy = false}
	table.insert(AllConnect, GUIObject.clearSavedButton.MouseButton1Click:Connect(function()
		local state = Function.ClearSavedState
		local cfg = Function.SaveAllConfig
		if state.Busy then return end
		state.Clicks += 1
		state.Token += 1
		local token = state.Token
		if state.Clicks < cfg.ClearClicks then
			-- ainda falta confirmar: mostra o progresso e zera sozinho se demorar
			GUIObject.clearSavedButton.Text = "Sure? Click again (" .. state.Clicks .. "/" .. cfg.ClearClicks .. ")"
			task.delay(cfg.ClearTimeout, function()
				if state.Token == token and not state.Busy then
					state.Clicks = 0
					GUIObject.clearSavedButton.Text = "Clear Saved"
				end
			end)
			return
		end
		state.Clicks = 0
		state.Busy = true
		local ok, result = Function.ClearSaved()
		if ok then
			print("Cleared RC saves (" .. tostring(result) .. " file(s))")
			GUIObject.clearSavedButton.Text = result > 0 and "Cleared!" or "Nothing saved"
		else
			warn("Failed to clear RC saves: " .. tostring(result))
			GUIObject.clearSavedButton.Text = "FAILED!"
		end
		task.delay(1.2, function()
			GUIObject.clearSavedButton.Text = "Clear Saved"
			state.Busy = false
		end)
	end))

