	local BREAKER = Instance.new("BoolValue")
	BREAKER.Name = "RoClothesBreaker"
	BREAKER.Parent = workspace

	local function loader()
		local loadui = Instance.new("ScreenGui",game:GetService("CoreGui"))
		loadui.Enabled = true
		RoCLoad.FullScreen(loadui)
		local oload = Instance.new("ImageLabel",loadui)
		oload.Image = getId("rbxasset://RClothesContent/load.png")
		oload.Size = UDim2.new(1,0,1,0)
		oload.Transparency = 1
		oload.ImageTransparency = .999
		local load = Instance.new("ImageLabel",loadui)
		load.Image = getId("rbxasset://RClothesContent/loadv9.1.png")
		load.Size = UDim2.new(1,0,1,0)
		load.Transparency = 1
		load.ImageTransparency = .999

		local debounce = 0
		local loadtxt
		repeat
			task.wait(.1)
			if loadtxt then
				loadtxt:Destroy()
			end
			loadtxt = Instance.new("TextLabel",loadui)
			loadtxt.BackgroundTransparency = 1
			loadtxt.TextColor3 = Color3.new(1,1,1)
			loadtxt.TextScaled = true
			loadtxt.Size = UDim2.new(1,0,1,0)
				loadtxt.Text = ""
			debounce += 1
				RoCLoad.Set(99, string.format("Verificando arquivos (%d/50)", debounce))
		until debounce >= 50 or load.IsLoaded == true
		if loadtxt then
			loadtxt:Destroy()
		end
		if load.IsLoaded == false then
			GUIObject.Screen.Enabled = false
			local BREAKER = Instance.new("BoolValue")
			BREAKER.Name = "RoClothesBreaker"
			BREAKER.Parent = workspace
			if oload.IsLoaded == true then
				local txt = Instance.new("TextLabel",loadui)
				txt.BackgroundTransparency = 1
				txt.TextColor3 = Color3.new(1,1,1)
				txt.TextScaled = true
				txt.Size = UDim2.new(1,0,1,0)
				txt.Text = "WRONG VERSION FILES ARE LOADED"
				game:GetService("Debris"):AddItem(loadui,2)
				warn("WRONG VERSION FILES ARE LOADED")
				RoCLoad.Fail("Arquivos de versão errada em RClothesContent")
			else
				local txt = Instance.new("TextLabel",loadui)
				txt.BackgroundTransparency = 1
				txt.TextColor3 = Color3.new(1,1,1)
				txt.TextScaled = true
				txt.Size = UDim2.new(1,0,1,0)
				txt.Text = "FILES ARE NOT LOADED CORRECTLY"
				game:GetService("Debris"):AddItem(loadui,2)
				warn("FILES ARE NOT LOADED CORRECTLY")
				RoCLoad.Fail("Arquivos não carregados: confira a pasta RClothesContent")
			end
		else
				RoCLoad.Done()
			if loadupFPerson > 0 then
				PlayerData[Player.Name].FPerson = true
				if loadupFPerson >= 3 and loadupFPerson < 4 then
					PlayerData[Player.Name].FPsnap = true
				end
				if loadupFPerson >= 4 then
					PlayerData[Player.Name].HeadTracking = true
				end
				if loadupFPerson == 1 or loadupFPerson == 3 or loadupFPerson == 5 then
					PlayerData[Player.Name].LocalTransparency = {
						["Head"] = false,
						["Right Arm"] = true,
						["Left Arm"] = true,
						["Torso"] = true,
						["Right Leg"] = true,
						["Left Leg"] = true,
						["Hat"] = true
					}
				end
			end
			if loadupClosed == false then
				Function.Anim.SetMenu(true)
			end
			if loadupExecute == true and Player.Character then
				local ok, err = pcall(Function.CharacterExecute,Player.Character, Player.Name)
				if not ok then warn("[RoC] CharacterExecute error:", err) end
			end
			loadui:Destroy()
		end
	end
	RoCLoad.Step(99, "Verificando arquivos")
	loader()
	task.wait(2)

	if BREAKER.Parent ~= nil then
		BREAKER:Destroy()
	end

	task.spawn(function()
		while task.wait(0.5) do
			local BreakerObject = game.Workspace:FindFirstChild("RoClothesBreaker")

			if BreakerObject then
				for _, Connect in pairs(AllConnect) do
					Connect:Disconnect()
				end
				task.cancel(aWhile)
				pcall(Function.SBShutdown)

				GUIObject.Screen:Destroy()
				GUIObject.MobileCloseButtonScreen:Destroy()
				BreakerObject:Destroy()
				print("RoCDC")
				break
			end
		end
	end)
end

local function RoCRun(Player)
	local Ok, Err = xpcall(RoClothes, function(E) return debug.traceback(tostring(E), 2) end, Player)
	if not Ok then
		warn("[RoC] erro ao iniciar:", Err)
		RoCLoad.Fail("Erro ao iniciar. Veja o console (F9).")
	end
end

-- espera o jogo terminar de carregar (injetar durante o loading é uma causa comum de crash)
if RS:IsClient() and not RS:IsStudio() and not game:IsLoaded() then
	RoCLoad.Set(2, "Aguardando o jogo carregar")
	local WaitStart = os.clock()
	while not game:IsLoaded() and os.clock() - WaitStart < 30 do
		task.wait(0.1)
		RoCLoad.Set(2)
	end
end
RoCLoad.Step(3, "Iniciando")

if RS:IsStudio() then
	RoCRun(PS.LocalPlayer)
else
	if RS:IsClient() then
		if not PS.LocalPlayer then
			RoCLoad.Set(3, "Aguardando o jogador")
			PS.PlayerAdded:Wait()
		end
		RoCRun(PS.LocalPlayer)
	elseif RS:IsServer() then
		RoCRun(PS:WaitForChild("lerp()"))
	end
end
return nil
